(window.GIM_TS=window.GIM_TS||{})["Kiddushin.1"]={"from":24,"a":[["\u0003\"יבמה יבא עליה ולקחה לו לאשה\"\u0004 (דברים כה, ה), לומר שביאתו עושה אותה לאשתו. ומקשים: \u0003ואימא לכולה מילתא\u0004 \u0005[ואמור\u0006 ש\u0005לכל הדבר]\u0006 יהא דינה \u0003כאשה,\u0004 שנקנית גם בכסף ובשטר! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר זאת, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהו כסף ושטר גומרים בה,\u0004 ביבמה, להיחשב כנשואה \u0003כדרך שהביאה גומרת בה? תלמוד לומר\u0004 פעם נוספת בהמשך הפסוק: \u0003\"ויבמה\"\u0004 (שם) לומר: דווקא \u0003ביאה גומרת בה ואין כסף ושטר גומרים בה.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ויבמה\"\u0004 ללמדנו — שגם \u0003בעל כרחה מיבם,\u0004 שאין היבום כנישואין, ואינו תלוי ברצון האשה. ומשיבים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"ויבם\",\u0004 ונבין שהדבר תלוי רק בו ומייבם אותה גם בעל כרחה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ההדגשה \u0003\"ויבמה\"\u0004 — \u0003שמעת מינה תרתי\u0004 \u0005[שומע אתה ממנה שני\u0006 דברים\u0005]\u0006 — הן לענין יבום בעל כרחה, והן שאין דרך נוספת של קנין גומרת בה מלבד ביאתה.","שנינו במשנה שהיבמה קונה את עצמה \u0003בחליצה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין יבמה, לאחר שחלץ היבם: \u0003\"ונקרא שמו בישראל בית חלוץ הנעל\"\u0004 (שם י), לומר: \u0003כיון שחלץ בה נעל\u0004 — \u0003הותרה לכל ישראל.\u0004","ומקשים: והאם \u0003האי\u0004 \u0005[\u0006מלה \u0005זו]\u0006 \u0003\"ישראל\" להכי הוא דאתא\u0004 \u0005[לכך היא באה\u0006 ללמד\u0005]?\u0006 הרי \u0003האי מיבעי ליה לכדתני\u0004 \u0005[\u0006דבר \u0005זה צריך לו לכפי ששנה]\u0006 \u0003רב שמואל בר יהודה:\u0004 נאמר \u0003\"בישראל\"\u0004 לומר שחליצה עושים רק \u0003בבית דין של ישראל, ולא בבית דין של גוים!\u0004 ומשיבים: \u0003תרי\u0004 \u0005[שתי\u0006 פעמים\u0005]\u0006 \u0003\"בישראל\" כתיבי\u0004 \u0005[נאמרו]\u0006 שם (\"...להקים לאחיו שם בישראל\", \"ונקרא שמו בישראל...\"), וכל אחד מהם בא ללמד ענין לעצמו.","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין צריך אותו]\u0006 את הביטוי \"בישראל\" הנוסף \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: פעם אחת היינו יושבים לפני ר' טרפון, ובאתה\u0004 (באה) לפנינו \u0003יבמה לחלוץ, ואמר לנו\u0004 ר' טרפון לאחר החליצה: \u0003ענו כולכם ואמרו \"חלוץ הנעל, חלוץ הנעל\".\u0004 כלומר, ש\"בישראל\" משמעו שצריך לפרסם את הדבר בישראל! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 דין\u0005]\u0006 לא מן המלה \"בישראל\" הוא נלמד, אלא \u0003מ\"ונקרא שמו\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שצריך שידאגו להודיע ברבים שזה שמו.","ועוד שנינו שם שהיבמה נפטרת מחובת היבום \u0003ו\u0004מותרת להנשא \u0003\"במיתת היבם\".\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומעירים: \u0003קל וחומר\u0004 הוא: \u0003ומה אשת איש שהיא\u0004 אסורה לזר איסור חמור, שהבא עליה עונשו הוא \u0003בחנק\u0004 — בכל זאת \u0003מיתת הבעל מתירתה, יבמה שהיא\u0004 אסורה לזר כשהיבם חי רק \u0003ב\u0004איסור \u0003לאו\u0004 \u0005[לא\u0006 תעשה\u0005],\u0006 \u0003לא כל שכן\u0004 שמיתת היבם מתירתה?","ומקשים על כך: \u0003מה לאשת איש\u0004 — \u0003שכן יוצאה\u0004 גם \u0003בגט, תאמר בזו\u0004 ביבמה \u0003שאינה יוצאה בגט!\u0004 ומשיבים: זו אינה פירכה לקל וחומר: \u0003הא נמי\u0004 \u0005[זו\u0006 היבמה \u0005גם כן]\u0006 \u0003יוצאה בחליצה\u0004 במקום גט.","\u0003אלא\u0004 כך אפשר להקשות על הקל וחומר: \u0003מה לאשת איש שכן\u0004 אותו האיש, בעלה, הוא ש\u0003אוסרה\u0004 לכל והוא עצמו \u0003מתירה\u0004 כשמת, מה שאין כן יבמה שהרי איסורה בא מחמת בעלה שמת, והוא אינו מתירה לאחרים! \u0003אמר רב אשי: הא נמי\u0004 \u0005[זו\u0006 היבמה, \u0005גם כן]\u0006 מי ש\u0003אוסרה\u0004 הוא גם זה ש\u0003מתירה,\u0004 שכן ה\u0003יבם\u0004 הוא ש\u0003אוסרה,\u0004 שכן לולא היה קיים היתה הרי מותרת לעולם בלא כלום, וכן ה\u0003יבם שרי לה\u0004 \u0005[מתיר אותה]\u0006 על ידי חליצה.","ושואלים מצד אחר: \u0003ותהא אשת איש יוצאה בחליצה מקל וחומר: ומה יבמה שאינה יוצאה בגט\u0004 — \u0003יוצאה בחליצה, זו,\u0004 אשת איש, \u0003שיוצאה בגט אינו דין שיוצאה בחליצה?\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי אשת איש \u0003\"ספר כריתת\"\u0004 (שם כד, ג), לומר שדווקא \u0003ספר\u0004 (גט) \u0003כורתה, ואין דבר אחר כורתה,\u0004 שאין מעשה המבטל את הנישואין בחיי הבעל אלא גט בלבד.","ושואלים עוד: \u0003ותהא יבמה יוצאת\u0004 גם \u0003בגט, מקל וחומר; ומה אשת איש שאין יוצאה בחליצה\u0004 — \u0003יוצאה בגט, זו שיוצאה בחליצה\u0004 — \u0003אין דין שיוצאה בגט?\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בחליצת יבמה \u0003\"ככה\"\u0004 (שם כה, ט) \u0003ו\u0004לשון \u0003\"\u0004\u0003ככה\"\u0004 משמעה \u0003עיכובא\u0004 \u0005[לעכב]\u0006 שאין לעשות אלא רק בדרך זו.","ושואלים: \u0003וכל היכא דאיכא עיכובא לא דרשי\u0004 \u0005[וכל מקום שיש\u0006 במקרא לשון \u0005עיכוב אין דורשים]\u0006 \u0003קל וחומר? והא\u0004 \u0005[והרי]\u0006 \u0003יום הכפורים דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 בבחירת שעיר לה' ולעזאזל \u0003\"גורל\"\u0004 (\"והשעיר אשר עלה עליו הגורל\". ויקרא טז, ט) \u0003ו\u0004נאמר בו \"\u0003חוקה\"\u0004 (\"והיתה לכם לחוקת עולם\". שם כט. \"והיתה זאת לכם לחוקת עולם\". שם לד), שמשמעה שכל מה שנאמר במצוות יום הכיפורים הוא לעכב,","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"\u0003ועשהו חטאת\"\u0004 (ויקרא טז, ט) לומר \u0003הגורל עושה\u0004 אותו \u0003חטאת, ואין השם\u0004 שקרא לו הכהן הגדול ומקדישו לשם כך \u0003עושה\u0004 את השעיר \u0003חטאת.\u0004","ודנים שם: \u0003שיכול\u0004 אני לומר, \u0003והלא דין\u0004 (סברה) \u0003הוא: ומה במקום שלא קידש הגורל,\u0004 כלומר, בשאר קרבנות שאין מועיל בהם גורל — \u0003קידש השם,\u0004 שכאשר מקדישים בהמה לשם קרבן מסויים הריהי מתקדשת, \u0003מקום שקידש הגורל אינו דין שיקדש השם?\u0004","\u0003תלמוד לומר\u0004 בהדגשה נוספת: \u0003\"ועשהו חטאת\"\u0004 (שם) לומר: דווקא \u0003הגורל עושה חטאת ואין השם עושה חטאת.\u0004 ומדרך לימוד זו נדייק: \u0003וטעמא דמעטיה קרא\u0004 \u0005[והטעם,\u0006 דווקא, משום \u0005שמיעט אותו הכתוב]\u0006 שאמר \"ועשהו\", \u0003הא לאו הכי דרשינן\u0004 \u0005[הרי לולא זאת\u0006 היינו \u0005דורשים]\u0006 \u0003קל וחומר, אף על גב דכתיב ביה\u0004 \u0005[אף על פי שנאמר בו]\u0006 \u0003\"חוקה\",\u0004 שהיא לעכב ואף בדין חליצה לא תהיה המלה \"ככה\" מונעת מלדרוש קל וחומר, ותהא היבמה יוצאת גם בגט!","אלא יש להשיב באופן אחר: שאף כאן יש מיעוט בכתוב: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בגט אשה \"וכתב \u0003לה\u0004 ספר כריתות\" (דברים כד, ג), \u0003\"לה\"\u0004 הוא מיעוט הבא ללמד: לאשה סתם מועיל הגט \u0003ולא ליבמה.\u0004 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שההדגשה \"\u0003לה\"\u0004 כוונתה שיהא הגט כתוב \u0003לשמה!\u0004","ומשיבים: \u0003תרי\u0004 \u0005[שתי]\u0006 \u0003\"לה\" כתיבי\u0004 \u0005[נאמרו]\u0006 — אחד לענין זה, ואחד לענין זה. ומקשים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין צריכים אותו],\u0006 כך ש\u0003חד\u0004 \u0005[אחד]\u0006 \u0003\"לה\"\u0004 לענין כתיבת הגט \u0003לשמה, ואידך\u0004 \u0005[והאחר]\u0006 \u0003\"לה\"\u0004 כוונתו: \u0003ולא לה ולחבירתה,\u0004 שאין גט לשתי נשים כאחת!","\u0003אלא\u0004 יש להסביר באופן אחר: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ביבמה: \u0003\"\u0004בית חלוץ ה\u0003נעל\"\u0004 (דברים כה, י), לומר: בחליצת \u0003נעל אין\u0004 \u0005[כן]\u0006 יוצאת מן היבם, \u0003מידי אחרינא\u0004 \u0005[\u0006וב\u0005דבר אחר]\u0006 — \u0003לא.\u0004","ושואלים: \u0003והאי \"נעל\" להכי הוא דאתא\u0004 \u0005[ו\"נעל\" זו לכך הוא שבאה\u0006 ללמד\u0005]?\u0006 \u0003האי מיבעי ליה\u0004 \u0005[זה\u0006 הרי \u0005צריך אותו]\u0006 לענין אחר, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"\u0004וחלצה \u0003נעלו\"\u0004 (שם כה, ט), ו\u0003אין לי אלא נעלו\u0004 השייכת לו, \u0003נעל של כל אדם מנא ליה\u0004 \u0005[מניין לו]\u0006 שיכול גם כן לחלוץ בה?","\u0003תלמוד לומר: \"נעל\"\u0004 ושוב חזר ואמר בפסוק השני \u0003\"נעל\",\u0004 ובזה \u0003ריבה\u0004 הכתוב כל נעל אחרת. \u0003אם כן מה תלמוד לומר \"נעלו\"\u0004 שמתייחסת אליו — לומר: \u0003נעלו הראוי לו, פרט ל\u0004מנעל \u0003גדול\u0004 כל כך \u0003שאין יכול להלך בו, פרט ל\u0004מנעל \u0003קטן שאין חופה\u0004 (מקיף, עוטף) \u0003את רוב רגלו, פרט\u0004"],["\u0003למסולים\u0004 (מין סנדל) \u0003שאין לו עקב,\u0004 שאינו קרוי נעל! ומשיבים: \u0003אם כן\u0004 שרק לצורך זה נאמרה המלה \u0003ניכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"נעל\", מאי\u0004 \u0005[מה\u0006 הטעם\u0005]\u0006 בהדגשה \u0003\"הנעל\"\u0004 — \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שני\u0006 דברים\u0005].\u0006","\u0003עבד עברי נקנה\u0004 לאדוניו \u0003בכסף ובשטר, וקונה\u0004 את \u0003עצמו\u0004 (משתחרר) \u0003בשנים\u0004 כשגומר את שש שנות עבודתו, \u0003וביובל,\u0004 כשמגיעה שנת היובל, \u0003ובגרעון כסף,\u0004 שיכול לפדות בכסף את יתרת שנות עבודתו שנותרו לו עד מלאת שש שנים לתחילת עבדותו. \u0003יתירה עליו אמה העבריה שקונה את עצמה\u0004 גם \u0003בסימנין,\u0004 שאם מביאה סימני בגרות יוצאה לחפשי. העבד \u0003הנרצע\u0004 אחרי שעבד שש שנים, \u0003נקנה\u0004 להיות עבד עולם \u0003ברציעה, וקונה את עצמו\u0004 להיות חפשי \u0003ביובל, ובמיתת האדון.\u0004","שנינו במשנה ש\u0003עבד עברי נקנה בכסף\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מכסף מקנתו\"\u0004 (ויקרא כה, נא) — \u0003מלמד שנקנה בכסף.\u0004 ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו,\u0006 למדנו\u0005]\u0006 מכתוב זה ש\u0003עבד עברי הנמכר לגוי\u0004 נקנה בכסף, אבל אין מכאן ראיה לנמכר לישראלי, שאפשר לומר \u0003הואיל וכל קנינו\u0004 של גוי אינו אלא \u0003בכסף\u0004 לכן קונה הוא גם את העבד העברי בכסף,","ואולם עבד עברי ה\u0003נמכר לישראל מנלן\u0004 \u0005[מניין לנו]\u0006 שנקנה אף הוא בכסף? — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באמה עבריה \u0003\"והפדה\"\u0004 (שמות כא, ח) — \u0003מלמד ש\u0004אם השיגה כסף ורצונה להשתתחרר טרם זמנה, הריהי \u0003מגרעת פדיונה,\u0004 שמפחיתה מכסף מכירתה את תמורת השנים שכבר עבדה ומשלמת את השאר \u0003ויוצאה\u0004 לחפשי, ואגב כך למדנו שאמה העבריה נקנית בכסף, והוא הדין לגבי עבד עברי.","ומקשים: אמנם \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה ב\u0003אמה העבריה,\u0004 אבל ממנה אין ללמוד כי אפשר לומר שדווקא אמה העבריה \u0003הואיל\u0004 \u0003ומיקדשה\u0004 \u0005[ו\u0006היא \u0005מתקדשת]\u0006 בדרך כלל \u0003בכסף\u0004 — \u0003מיקניא\u0004 \u0005[נקנית]\u0006 גם כן לאמה \u0003בכסף,\u0004 ואולם \u0003עבד עברי מנלן\u0004 \u0005[מניין לנו]\u0006 שאף הוא נקנה בכסף? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כי ימכר לך אחיך העברי או העבריה ועבדך שש שנים\"\u0004 (דברים טו, יב) \u0003מקיש\u0004 (משווה) הכתוב \u0003עברי לעבריה\u0004 לומר שדרך קניינם אחת.","ועדיין שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 בכתוב זה מקור לעבד ש\u0003מכרוהו בית דין,\u0004 שמפרשים אותו במי שגנב ואין ביכולתו לשלם את דמי הגניבה, ואז מוכרים אותו לעבד ובכסף זה משלם את חובו, ואפשר לומר שיש לו דין מיוחד \u0003הואיל ונמכר\u0004 \u0003בעל כורחו,\u0004 ואולם זה ה\u0003מוכר עצמו מנלן\u0004 \u0005[מניין לנו]\u0006 שגם הוא נקנה בכסף?","ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"שכיר\"\u0004 הנאמר במוכר עצמו (\"כשכיר כתושב יהיה עימך\". ויקרא כה, מ) מ\u0003\"שכיר\"\u0004 הנאמר במכרוהו בית דין (\"כי משנה שכר שכיר עבדך\". דברים טו, יח). ושואלים: \u0003הניחא למאן דיליף\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שלומד]\u0006 גזירה שווה זו של \u0003\"שכיר\" \"שכיר\"\u0004 שמלה זו אמורה גם במוכר עצמו וגם בנמכר על ידי בית דין \u0003אלא למאן דלא יליף\u0004 \u0005[ל\u0006דעת \u0005מי שאיננו לומד]\u0006 גזירה שווה \u0003\"שכיר\" \"שכיר\", מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מהיכן הוא לומד?","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפתיחת פרשת הנמכר לגוי: \u0003\"וכי תשיג\"\u0004 (ויקרא כה, מז) בוא\"ו החיבור, לומר שדבר זה הוא \u0003מוסף על ענין ראשון,\u0004 פרשת המוכר עצמו לישראל ומחבר את שניהם, \u0003ו\u0004משום כך \u0003ילמד עליון\u0004 (המוקדם), דין המוכר עצמו לישראל הנאמר קודם, \u0003מתחתון\u0004 (המאוחר), מדין הנמכר לגוי שנכתב אחריו. שכמו שנמכר לגוי נקנה בכסף, כך גם מוכר עצמו לישראל נמכר בכסף.","ומעירים: \u0003ומאן\u0004 \u0005[ומי הוא]\u0006 ה\u0003תנא דלא יליף\u0004 \u0005[שאינו לומד]\u0006 גזירה שווה של \"\u0003שכיר\" \"שכיר\"\u0004 — \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר עצמו\u0004 לעבד \u0003נמכר לשש\u0004 שנים, \u0003ו\u0004אם רוצה — אף \u0003יתר על שש\u0004 שנים, ואילו זה ש\u0003מכרוהו בית דין אינו נמכר אלא לשש\u0004 שנים בלבד.","והבדלים נוספים: \u0003המוכר עצמו אינו נרצע,\u0004 ואילו זה ש\u0003מכרוהו בית דין\u0004 — \u0003נרצע. מוכר עצמו אין מעניקים לו\u0004 בעליו מענקים כשיוצא לחפשי, ואילו זה ש\u0003מכרוהו בית דין\u0004 — \u0003מעניקים לו. המוכר עצמו אין רבו\u0004 (אדוניו) \u0003מוסר לו שפחה כנענית\u0004 לשם אישות כדי שיעמיד ולדות לצורך עבדות, ואילו זה ש\u0003מכרוהו בית דין רבו מוסר לו שפחה כנענית.\u0004","ואילו \u0003ר' אלעזר אומר\u0004 אין כל הבדל ביניהם אלא: \u0003זה וזה אינו נמכר אלא לשש\u0004 שנים, \u0003זה וזה נרצע, וזה וזה מעניקים לו, וזה וזה רבו מוסר לו שפחה כנענית.\u0004 ואם כן, \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים],\u0006 שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לא יליף\u0004 \u0005[לומד]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\",\u0004 ולכן בכל אחד מהמקרים הוא דן רק לפי ההלכות המפורשות בו, \u0003ו\u0004אילו \u0003ר' אלעזר יליף\u0004 \u0005[לומד]\u0006 גזירה שווה \u0003\"שכיר\" \"שכיר\"\u0004 ולומד דינים האמורים בזה מדינים האמורים באחר?","\u0003אמר רב טביומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יליף\u0004 \u0005[לומדים]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\", והכא\u0004 \u0005[וכאן]\u0006 במחלוקת זו בברייתא \u0003בהאי קרא קמיפלגי\u0004 \u0005[בכתוב זה נחלקו]:\u0006 \u0003מאי טעמא\u0004 \u0005מה הטעם\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ש\u0003אמר\u0004 שה\u0003מוכר עצמו נמכר לשש\u0004 שנים \u0003ויתר על שש?\u0004 — לדעתו \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 ל\u0003גבי מכרוהו בית דין,\u0004 שנאמר \u0003\"ועבדך שש שנים\"\u0004 (דברים טו, יב) לומר ש\u0003זה\u0004 בלבד עובד רק שש שנים, \u0003ולא מוכר עצמו,\u0004 שאם התנה כך הריהו עובד גם יתר על שש שנים.","\u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' אלעזר, לומד מן ההדגשה הזו דבר אחר: \u0003\"ועבדך\"\u0004 כוונתו עובד הוא \u0003לך, ולא ליורש\u0004 שאינו עובר בירושה לא לבת ולא לאח אם אין לו בנים כשאר נכסים, ואולם אם יש לו בן, הריהו יורש אף את עבדו העברי.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 התנא הראשון, כיצד יודע הוא הלכה זו שאינו עובר בירושה? ומשיבים: ש\u0003\"ועבדך\" אחרינא כתיב\u0004 \u0005[אחר,\u0006 פעם נוספת, \u0005נאמר]\u0006 וממנו לומד הוא דין זה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מה הוא עושה בכתוב זה, שלדעתו הוא מיותר? ומשיבים: לדעתו הכתוב \u0003ההוא להרצאת\u0004 (לריצוי, לפיוס) ה\u0003אדון הוא דאתא\u0004 \u0005[שבא],\u0006 כדי שלא יירע בעיניו הדבר שצריך לשחררו כעבור שש שנים שעבדו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ש\u0003אמר\u0004 שה\u0003מוכר עצמו אינו נרצע?\u0004 ומשיבים: \u0003מדמיעט רחמנא\u0004 \u0005[מ\u0006שום \u0005ש\u0006לדעתו \u0005מיעטה התורה]\u0006 ל\u0003גבי מכרוהו בית דין\u0004 שנאמר \u0003\"ורצע אדניו את אזנו במרצע\"\u0004 (שמות כא, ו) לומר: \u0003אזנו שלו,\u0004 של עבד זה \u0003ולא אזנו של\u0004 עבד אחר, ה\u0003מוכר עצמו.\u0004"],["\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 אומר ש\u0003ההיא\u0004 \u0005[אותה]\u0006 מלה \"אזנו\" — \u0003לגזירה שוה הוא דאתא\u0004 \u0005[שבאה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מנין לרציעה שהיא\u0004 נעשית \u0003באזן ימנית\u0004 דווקא? — \u0003נאמר כאן\u0004 בעבד עברי \u0003\"אזן\" ונאמר להלן\u0004 בטהרת המצורע \u0003\"אזן\u0004 המטהר הימנית\u0003\"\u0004 (ויקרא יד, יז), \u0003מה להלן\u0004 במצורע מפורש שהיא אוזן \u0003ימין\u0004 — \u0003אף כאן\u0004 הרציעה צריכה להיעשות באוזן \u0003ימין.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מניין יודע הוא שנרצע דווקא באוזן ימין? ומשיבים: לדעתו, \u0003אם כן\u0004 שרק לגזירה שווה נאמר \"אוזן\" \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"אזן\"\u0004 בלבד, ונלמד גזירה שווה מאוזן האמור במצורע, \u0003מאי\u0004 \u0005[מה]\u0006 טעם אמר \u0003\"אזנו\"\u0004 — הרי זה בא למעט מוכר עצמו שאינו נרצע.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 שאינו ממעט מ\"אזנו\" מוכר עצמו מרציעה, סבור כי הביטוי \u0003ההוא מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 כדי להדגיש \u0003\"אזנו\" ולא אזנה,\u0004 שאין דין רציעה אלא בעבד ולא באמה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מהיכן יודע הוא הלכה זו? ומשיבים: \u0003נפקא לה\u0004 \u0005[יוצאת לו,\u0006 נלמדת\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"ואם\u0004 אמר \u0003יאמר העבד\"\u0004 (שמות כא, ה), לומר: \u0003העבד ולא אמה.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 שלא למד דין זה כתנא קמא \u0003מיבעי ליה\u0004 \u0005[צריך לו]\u0006 לכתוב זה להדגשה לענין אחר: \u0003עד שיאמר כשהוא\u0004 עדיין \u0003עבד,\u0004 שלאחר שחרורו שוב אינו יכול לומר שהוא רוצה להשאר עבד.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מהיכן הוא יודע הלכה זו? ומשיבים: \u0003מ\"עבד\" \"העבד\" נפקא\u0004 \u0005[יוצא\u0006 נלמד\u0005],\u0006 שאם היה נאמר \"עבד\" היינו למדים רק שיכול לומר כך בהיותו עבד, וכתב \"העבד\" להדגיש: העבד נרצע ולא האמה. ומסכמים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 את ההבדל הזה של \"\u0003עבד\" \"העבד\"\u0004 — \u0003לא דריש\u0004 \u0005[אינו דורש].\u0006","ומבררים לפי שיטה זו פרטים נוספים באותה מחלוקת: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ש\u0003אמר מוכר עצמו אין מעניקין לו?\u0004 — כי \u0003מיעט רחמנא גבי\u0004 \u0005[מיעטה התורה אצל]\u0006 \u0003מכרוהו בית דין,\u0004 שנאמר \u0003\"העניק תעניק לו\"\u0004 (דברים טו, יד), \"\u0003לו\",\u0004 לז שמכרוהו בית דין — \u0003ולא למוכר עצמו.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 מה הוא דורש מדרשה זו? ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר: \u0003\"לו\",\u0004 לעבד, מעניקים \u0003ולא ליורשיו.\u0004 ותוהים: \u0003יורשיו אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 הלא \u0003\"שכיר\" קרייה רחמנא\u0004 \u0005[קראה לו התורה]\u0006 לעבד עברי, \u0003מה שכיר\u0004 שכר \u0003פעולתו\u0004 (עבודתו) כשמת מגיע \u0003ליורשיו\u0004 — \u0003אף האי\u0004 \u0005[זה]\u0006 העבד \u0003פעולתו\u0004 (הענקתו) מגיעה \u0003ליורשיו! אלא\u0004 הכוונה היא להדגיש: \u0003\"לו\"\u0004 — \u0003ולא לבעל חובו\u0004 של העבד, שאין הנושה בו יכול לגבות את ההענקה במקומו. ומדוע צריך להדגיש זאת?","\u0003מדסבירא לן בעלמא\u0004 \u0005[מכיון שאנו סבורים בכלל]\u0006 \u0003כ\u0004שיטת \u0003ר' נתן, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' נתן: מנין לנושה בחברו מנה, וחברו\u0004 אף הוא נושה \u0003בחברו\u0004 — \u0003מנין שמוציאין מזה\u0004 מן הלווה האחרון \u0003ונותנין\u0004 ישירות \u0003לזה,\u0004 למלווה הראשון, ואין צורך לתת לאיש באמצע — \u0003תלמוד לומר\u0004 בכופר במלוה ואחר כך הודה: \u0003\"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז), כלומר, למי שנתחייב לו בסופו של דבר.","ולכן \u0003אתא\u0004 \u0005[באה]\u0006 המלה \u0003\"לו\" לאפוקי\u0004 \u0005[להוציא\u0006 למעט\u0005],\u0006 שבמקרה זה של עבד עברי, מעניקים לו עצמו, ואין מעבירים את הסכום ישירות לבעל חובו, \u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מדוע אין הוא למד מיעוט זה — כי לדעתו \u0003בעלמא נמי לא סבירא לן\u0004 \u0005[בכלל גם כן אין אנו סבורים]\u0006 \u0003כ\u0004שיטת \u0003ר' נתן,\u0004 וממילא אין צריך לזה מיעוט מיוחד.","ועוד שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במה ש\u0003אמר\u0004 ש\u0003מוכר עצמו אין רבו\u0004 (אדוניו) \u0003מוסר לו שפחה כנענית\u0004 — ומשיבים: כי \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 ל\u0003גבי\u0004 מי ש\u0003מכרוהו בית דין \"אם אדניו יתן לו אשה\"\u0004 (שמות כא, ד), להדגיש: \u0003\"לו\"\u0004 — \u0003ולא למוכר עצמו. ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 מפרש: \"\u0003לו\"\u0004 — כוונתו \u0003בעל כרחו.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 תנא קמא\u0005]\u0006 מניין הוא יודע שצריך לחיות עם השפחה הזו בעל כרחו — \u0003מ\u0004מה שנאמר \u0003\"כי משנה שכר שכיר\"\u0004 (דברים טו, יח) \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"כי משנה\u0004 (כפל) \u0003שכר שכיר עבדך\"\u0004 כוונתו — \u0003שכיר אינו עובד אלא ביום,\u0004 ואילו \u0003עבד עברי עובד בין ביום ובין בלילה.\u0004","ומבררים: \u0003וכי תעלה על דעתך שעבד עברי עובד\u0004 ממש \u0003בין ביום ובין בלילה? והלא כבר נאמר \"כי טוב לו עמך\"\u0004 (שם טז), וכוונתו: \u0003עמך במאכל, עמך במשתה,\u0004 שצריך לדאוג לו לכל מחסורו ולהשוות את תנאיו לאדון עצמו, ובוד אי שאין מעבידים אותו יותר מדרך הראוי. \u0003ו\u0004משום כך \u0003אמר ר' יצחק: מכאן שרבו מוסר לו שפחה כנענית\u0004 בעל כרחו כדי להוליד ממנה ילדים עבור האדון, וזוהי העבודה שהוא עובד בלילה.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אלעזר\u0005]\u0006 אומר שמכאן אין ראיה; כי \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי מדעתיה\u0004 \u0005[דברים אלה\u0006 אמורים שהעבד בוחר בשפחה \u0005מדעתו],\u0006 \u0003אבל בעל כרחו אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב במלה \"לו\" לומר שמוסר לו האדון אף בעל כרחו.","לפי מה שביארנו אין מחלוקת זו תלויה אם למדים גזירה שווה של \"שכיר\" \"שכיר\". \u0003אלא, מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דלא יליף\u0004 \u0005[שאינו לומד]\u0006 גזירה שווה זו של \u0003\"שכיר\" \"שכיר\"\u0004 — \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 על מה שנאמר: \u0003\"\u0004...עד שנת היובל יעבוד עמך ויצא מעמך הוא ובניו עימו \u0003ושב אל משפחתו וגו'\"\u0004 (ויקרא כה, מ–מא), \u0003אמר ר' אליעזר בן יעקב: במה הכתוב מדבר? אי\u0004 \u0005[אם]\u0006 \u0003במוכר עצמו\u0004 והגיעה שנת היובל בתוך שש שנות העבדות — \u0003הרי כבר אמור\u0004 \"עד שנת היובל יעבוד עמך ויצא מעמך\" (שם).","\u0003אי\u0004 \u0005[אם]\u0006 \u0003בנרצע\u0004 — \u0003הרי כבר אמור, הא\u0004 \u0005[הרי]\u0006 ש\u0003אין הכתוב מדבר אלא ב\u0004אדם ש\u0003מכרוהו בית דין שתים ושלש שנים לפני היובל, שהיובל מוציאו\u0004 לחופשי. \u0003ואי סלקא דעתך יליף\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005למדים]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\",\u0004 אם כן \u0003למה לי\u0004 לימוד מיוחד זה? \u0003נילף\u0004 \u0005[נלמד]\u0006 מ\u0003\"שכיר\" \"שכיר\"\u0004 בגזירה שווה ממוכר עצמו!","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לדחות ולומר כי \u0003לעולם\u0004 גם תנא זה \u0003יליף\u0004 \u0005[לומד]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\", ו\u0004בכל זאת \u0003איצטריך\u0004 \u0005[וצריך]\u0006 לדין זה לימוד מיוחד, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003מוכר עצמו הוא\u0004 ש\u0003לא עבד איסורא\u0004 \u0005[עשה איסור]\u0006 ולכן הוא יוצא ביובל אף בתוך שש השנים, \u0003אבל\u0004 אם \u0003מכרוהו בית דין דעבד איסורא\u0004 \u0005[שעשה איסור],\u0006 שהרי מוכרים אותו רק משום שאינו יכול לשלם מה שגנב, ואם כן \u0003אימא ניקנסיה\u0004 \u0005[אמור\u0006 ש\u0005נקנסנו]\u0006 ולא ייצא ביובל במקרה כזה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006 הכתוב\u0005]\u0006 שאף הוא יוצא.","\u0003אמר מר\u0004 \u0005[אמר החכם]\u0006 בברייתא שהובאה קודם: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנרצע הרי כבר אמור.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו מקרא שכבר נאמר בו הדבר? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ושבתם איש אל אחזתו ואיש אל משפחתו\u0004 תשובו\u0003\"\u0004 (ויקרא כה, י) \u0003במה הכתוב מדבר? אי\u0004 \u0005[אם]\u0006 \u0003במוכר עצמו\u0004 — \u0003הרי כבר אמור\u0004 \"עד שנת היובל יעבוד עמך\" (ויקרא כה, מ),","\u0003אי\u0004 \u0005[אם]\u0006 \u0003במכרוהו בית דין\u0004 — \u0003הרי כבר אמור\u0004 \"ויצא מעמך... ושב אל משפחתו\" (שם, מא), \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003אין הכתוב מדבר אלא בנרצע שתים ושלש שנים לפני היובל, שהיובל מוציאו.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 מהיכן נובע דבר זה מן הכתוב לומר שמדובר פה דווקא במי שנרצע? \u0003אמר רבא בר שילא: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"איש\", איזהו דבר שנוהג באיש ואין נוהג באשה\u0004 — \u0003הוי אומר זו רציעה.\u0004","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 במקרא דין זה שיוצא ביובל ב\u0003מכרוהו בית דין, ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 ב\u0003נרצע,\u0004 ואין למדים זה מזה, משום \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003מכרוהו בית דין\u0004 היינו אומרים כי היובל מוציאו \u0003משום\u0004 ש\u0003לא מטאי זמניה\u0004 \u0005[הגיע זמנו]\u0006 להשתחרר באופן אחר, \u0003אבל נרצע דמטאי זמניה אימא ניקנסיה\u0004 \u0005[שהגיע זמנו\u0006 ולא רצה להשתחרר \u0005אמור\u0006 ש\u0005נקנסנו]\u0006 ויישאר עבד עולם.","\u0003ו\u0004להיפך, \u0003אי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003נרצע,\u0004 היינו אומרים שהיובל מוציאו \u0003משום\u0004 שעל כל פנים \u0003עבד ליה\u0004 \u0005[אותו,\u0006 את האדון\u0005]\u0006 \u0003שש\u0004 שנים כדינו, \u0003אבל מכרוהו בית דין\u0004 ש\u0003לא עבד ליה\u0004 \u0005[אותו]\u0006 עדיין \u0003שש\u0004 שנים, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ישתחרר ביובל, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בשני המקרים.","\u0003ו\u0004כן \u0003איצטריך למיכתב\u0004 \u0005[הוצרך לכתוב]\u0006 בענין יציאה ביובל לנרצע \u0003\"ושבתם\u0004 איש אל אחוזתו \u0003\",\u0004 \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 גם באופן נוסף \u0003\"\u0004ועבדו \u0003לעולם\",\u0004 כלומר, עד היובל. \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"לעולם\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003לעולם ממש,\u0004 כלומר, כל ימי חייו, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 \u0003\"ושבתם\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \"\u0003ושבתם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שיוצא רק ביובל אמורים \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא עבד שש\u0004 שנים לפני שנרצע, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 שכבר \u0003עבד שש\u0004 שנים לפני הרציעה \u0003לא יהא סופו\u0004 כשהוא נרצע \u0003חמור מתחלתו\u0004 כשנמכר, ונאמר: \u0003מה תחלתו\u0004 עובד \u0003שש\u0004 שנים בלבד — \u0003אף סופו נמי\u0004 \u0005[גם כן]\u0006 אינו עובד אלא \u0003שש\u0004 ולא יותר, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003\"לעולם\"\u0004 פירושו \u0003לעולמו של יובל,\u0004 גם אם הגיע היובל אחרי שנים רבות. ומכל מקום אין לנו הוכחה גם מדברי תנא זה שאינו דורש גזירה שווה \"שכיר\" \"שכיר\".","\u0003אלא מאן תנא דלא יליף\u0004 \u0005[מיהו התנא שאינו לומד]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\"\u0004 — \u0003רבי היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["נאמר בעבד עברי הנמכר לגוי, שיש לו דרך להשתחרר אם גואלים אותו קרוביו: \u0003\"ואם לא יגאל באלה\u0004 ויצא בשנת היובל\u0003\"\u0004 (ויקרא כה, נד) \u0003רבי אומר:\u0004 דווקא \u0003באלה\u0004 (בעזרת קרוביו) \u0003הוא נגאל, ואין\u0004 הוא \u0003נגאל בשש,\u0004 שאינו משתחרר אחרי שש שנים.","\u0003שיכול\u0004 הייתי לדרוש קל וחומר: \u0003והלא דין הוא: ומה מי שאינו נגאל באלה\u0004 — עבד עברי הנמכר לישראל שאין בו דין גאולה בקרובים — \u0003נגאל בשש,\u0004 משתחרר אחרי שש שנים, \u0003זה\u0004 — עבד עברי הנמכר לגוי — \u0003שנגאל באלה\u0004 (בקרובים) \u0003אינו דין שנגאל בשש?\u0004 — \u0003תלמוד לומר: \"באלה\",\u0004 להדגיש: דווקא \u0003באלה הוא נגאל, ואין\u0004 הוא \u0003נגאל בשש.\u0004","\u0003ואי סלקא דעתך יליף\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005לומד]\u0006 בגזירה שווה \u0003\"שכיר\" \"שכיר\", אמאי קאמר\u0004 \u0005[מדוע\u0006 הוא \u0005אומר]\u0006 לגבי הנמכר לישראל \u0003\"ומה מי שאינו נגאל באלה\"? נילף\u0004 \u0005[שילמד]\u0006 מנמכר לגוי בגזירה שווה של \u0003\"שכיר\" \"שכיר\",\u0004 שכן גם בנמכר לגוי נזכרה המלה \"שכיר\" — \"כשכיר שנה בשנה יהיה עימו\" (שם נג) ונאמר שאף הנמכר לישראל יש לו גאולה על ידי קרובים! ומאחר שאין אומרים כן משמע שאינו דורש גזירה שווה \"שכיר\" \"שכיר\".","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לדחות ראיה זאת, \u0003ו\u0004\u0003לעולם\u0004 תפרש כי \u0003יליף\u0004 \u0005[לומד]\u0006 גזירה שווה של \u0003\"שכיר\" \"שכיר\", ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בנמכר לגוי \u0003\"\u0004או דודו או בן דודו \u0003יגאלנו\"\u0004 (שם מט), והדגשה זו באה למעט: \u0003לזה, ולא לאחר.\u0004","לגופה של מחלוקת זו מבררים \u0003ומאן\u0004 \u0005[ומיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו],\u0006 על \u0003רבי\u0004 בענין זה — \u0003ר' יוסי הגלילי ור' עקיבא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על מה שנאמר \u0003\"\u0004ואם \u0003לא יגאל באלה\", ר' יוסי הגלילי אומר:\u0004 ההדגשה \u0003\"באלה\"\u0004 באה לומר דבר אחר: שאם פודים אותו קרוביו (\"אלה\") הרי זה \u0003לשחרור,\u0004 שיוצא לחופשי לגמרי, אבל אם נגאל \u0003בשאר כל אדם\u0004 שמשלם את דמיו לאדוניו הגוי — הרי זה \u0003לשעבוד,\u0004 שהוא משתעבד לו עד שישלם בעבודתו את דמי פדיונו. ואילו \u0003ר' עקיבא אומר: \"באלה\"\u0004 — \u0003לשעבוד,\u0004 ואילו \u0003בשאר כל אדם\u0004 הריהו נפדה \u0003לשחרור\u0004 גמור.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אם לא יגאל באלה\",\u0004 וכוונתו: אם נגאל באלה — משתחרר, \u0003אלא\u0004 כשייגאל \u0003באחר\u0004 (על ידי אחר) אז \u0003\"ויצא בשנת היובל\"\u0004 ולא קודם לכן, כי הוא משועבד לו, \u0003ור' עקיבא אומר: אם לא יגאל אלא באלה\u0004 — \u0003ויצא בשנת היובל,\u0004 ואולם אם נגאל באחרים — הריהו יוצא מיד. \u0003ור' יוסי הגלילי\u0004 טוען כנגדו: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"אלא באלה\" כתיב\u0004 \u0005[נאמר]?\u0006","\u0003אלא\u0004 מפני קושיה זו על שיטת ר' עקיבא, יש לחזור מן ההסבר הקודם ולומר כי \u0003בהאי קרא קמיפלגי\u0004 \u0005[ב\u0006פירוש \u0005כתוב זה נחלקו];\u0006 מה שנאמר \u0003\"או דדו או בן דדו יגאלנו\"\u0004 (שם) — הרי \u0003זה גאולת קרובים, \"או השיגה ידו\"\u0004 (שם) — \u0003זה גאולת עצמו, \"ונגאל\"\u0004 — \u0003זו גאולת אחרים\u0004 הפודים אותו מיד הגוי.","\u0003ר' יוסי הגלילי סבר: מקרא נדרש לפניו,\u0004 כלומר, יש לדרוש ולהסמיך את המקרא לענין הקרוב אליו לפניו, ואם כן \u0003שדי\u0004 \u0005[השלך],\u0006 כלומר, קרב והשווה את הדין של \u0003גאולת קרובים\u0004 ל\u0003גאולת עצמו; מה גאולת עצמו\u0004 היא \u0003לשחרור\u0004 גמור — \u0003אף גאולת קרובים\u0004 היא \u0003לשחרור. ו\u0004אילו \u0003ר' עקיבא סבר: מקרא נדרש לאחריו,\u0004 ואם כן \u0003שדי\u0004 \u0005[השלך,\u0006 קרב דין\u0005]\u0006 \u0003גאולת אחרים\u0004 ל\u0003גאולת עצמו; מה גאולת עצמו לשחרור\u0004 — \u0003אף גאולת אחרים לשחרור,\u0004 אבל גאולת קרובים לשעבוד.","ושואלים: \u0003אי הכי\u0004 \u0005[אם\u0006 ב\u0005כך]\u0006 הם חולקים, בין לר' יוסי הגלילי ובין לר' עקיבא ההדגשה \u0003\"באלה\", למה לי?\u0004 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היה נאמר \"\u0003באלה\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מקרא נדרש בין לפניו בין לאחריו, והכל,\u0004 בכל מקרה שנגאל, הוא \u0003לשחרור,\u0004 בא המיעוט \"אלה\" למעט קרובים או אחרים כל אחד לשיטתו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנו למדים מן המלה \"באלה\", אם כן \u0003הדר קושיא לדוכתיה\u0004 \u0005[חוזרת הקושיה למקומה]\u0006 מה שהקשו על ר ' עקיבא שלא נאמר \"אלא באלה\". \u0003אלא,\u0004 יש לחזור גם מהסבר זה ולומר ש\u0003בסברא קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים]\u0006 ולא בלימוד מן המקראות;","\u0003ר' יוסי הגלילי סבר: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003גאולת אחרים\u0004 היא \u0003לשיעבוד, דאי אמרת\u0004 \u0005[שאם אתה אומר]\u0006 \u0003לשחרור הוו מימנעי\u0004 \u0005[היו נמנעים]\u0006 \u0003ולא פרקי ליה\u0004 \u0005[פודים אותו],\u0006 אבל אם צריך העבד לעבוד עבורם ואינם מפסידים את כספם — יפדו אותו. \u0003ור' עקיבא סבר: מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003גאולת קרובים לשיעבוד.\u0004 מדוע? \u0003דאי אמרת\u0004 \u0005[שאם תאמר]\u0006 שהיא \u0003לשחרור,\u0004 אם כן \u0003כל יומא ויומא אזל ומזבין נפשיה\u0004 \u0005[יום ויום יילך וימכור את עצמו]\u0006 ויסמוך על קרוביו שישחררו אותו.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: זו דברי ר' יוסי הגלילי ור' עקיבא\u0004 הסבורים שלא בכל מקרה שפודים את העבד מיד אדוניו הגוי הוא משתחרר, \u0003אבל חכמים אומרים: הכל לשחרור.\u0004","\u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 — \u0003רבי היא, דמפיק ליה להאי\u0004 \u0005[שמוציא את\u0006 המלה \u0005הזו]\u0006 \u0003\"באלה\" לדרשה אחרינא\u0004 \u0005[אחרת]\u0006 כפי שאמרנו. \u0003ו\u0004לדעתו \u0003מקרא נדרש בין לפניו ובין לאחריו,\u0004 ולכן בין בגאולת אחרים ובין בגאולת קרובים — הרי הוא משתחרר לגמרי.","ושואלים: \u0003ורבי, האי\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003\"\u0004ואם לא יגאל באלה \u0003ויצא בשנת היובל\"\u0004 (שם נד) \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]\u0006 שהרי עצם הדין שעובד את אדוניו הגוי עד היובל מפורש כבר קודם! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 מה שנאמר \u0003\"ויצא בשנת היובל\"\u0004 משמעו כפשוטו, שאם אין העבד נגאל קודם יוצא הוא רק בשנת היובל מידי אדוניו הגוי."],["\u0003בגוי שישנו תחת ידך,\u0004 כלומר, שאתה מושל בו ואתה יכול לקבוע עבורו את החוקים. \u0003או\u0004 שמא תאמר: \u0003אינו אלא בגוי שאינו תחת ידך?\u0004 אולם דבר זה אינו אפשרי, שכן \u0003אמרת\u0004 \u0005[\u0006יכול אתה \u0005לומר]\u0006 \u0003וכי מה אפשר לעשות לו\u0004 שיציית לדברי התורה? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין הכתוב מדבר אלא בגוי שישנו תחת ידך.\u0004","בין הדרכים שהעבד נקנה בהן שנינו במשנה שהוא נקנה גם \u0003בשטר.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר עולא: אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין אמה העבריה: \u0003\"אם אחרת יקח לו\"\u0004 (שמות כא, י) — \u0003הקישה\u0004 (השווה אותה) \u0003הכתוב\u0004 את האמה \u0003ל\u0004אשה \u0003אחרת\u0004 המתקדשת, \u0003מה אחרת מקניא\u0004 \u0005[נקנית]\u0006 לבעלה \u0003בשטר\u0004 — \u0003אף אמה העבריה מקניא\u0004 \u0005[נקנית]\u0006 \u0003בשטר.\u0004","ושואלים על השוואה זו: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003שטר אמה העבריה\u0004 ה\u0003אדון\u0004 הוא ש\u0003כותבו\u0004 כמו שטר קידושין שהבעל כותבו, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שה\u0003אב\u0004 הוא ש\u0003כותבו\u0004 והוא כעין שטר מכירה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אינו דומה כלל שטר מכירת אמה עבריה לשטר קידושין! \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שחלקו אמוראים בבעיה זו: \u0003שטר אמה העבריה, מי כותבו? רב הונא אמר: אדון כותבו, רב חסדא אמר: אב כותבו.\u0004 ואם כן, \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב הונא, אלא ל\u0004שיטת \u0003רב חסדא מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמר רב אחא בר יעקב,\u0004 יש ללמוד בדרך אחרת: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי אמה עבריה (שם ז): \u0003\"לא תצא כצאת העבדים\"\u0004 הכנענים, מכאן למדים — \u0003אבל נקנית היא כקנין עבדים\u0004 כנעניים. \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 קנין זה — \u0003שטר.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003אבל נקנית היא כקנין עבדים, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 קנין זה — \u0003חזקה!\u0004 ומשיבים: אי אפשר לומר כן, כי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בעבדים כנענים: \u0003\"והתנחלתם אותם לבניכם אחריכם\"\u0004 (ויקרא כה, מו), כלומר, דווקא \u0003אותם\u0004 את הגויים אתה קונה \u0003בחזקה\u0004 כאחוזת נחלה של קרקע, \u0003ולא אחר בחזקה.\u0004","ומקשים: אם כן \u0003ואימא\u0004 \u0005[ואמור]\u0006 כמו כן \u0003אותם\u0004 אתה קונה \u0003בשטר, ולא אחר בשטר!\u0004 ומשיבים: \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לא תצא כצאת העבדים\"\u0004 וכפי שדייקנו: אבל נקנית היא כקנין עבדים — בשטר. ושואלים: כיון שאין הדבר מוכח מן הענין, אם כן \u0003ומה ראית\u0004 לדמות אמה עבריה לעבד כנעני לענין שטר דווקא ולהבדילה מדין עבד בקנין חזקה, אולי נאמר להיפך שדומה היא לעבד בדין חזקה ושונה ממנו בדין שטר?","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003שטר הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לענין קנין עבד, \u0003שכן\u0004 שטר כוחו גדול, שהרי שטר (גט) גם \u0003מוציאה בבת ישראל.\u0004 ודוחים: \u0003אדרבה, חזקה הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 \u0003שכן\u0004 גדולה חזקה ש\u0003קונה בנכסי הגר\u0004 שמת בלי יורשים, שאינם נקנים בכל דרך אחרת! ומשיבים: \u0003ב\u0004דיני \u0003אישות מיהת\u0004 \u0005[על כל פנים\u0006 \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 קנין של חזקה. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תשובה אחרת: \u0003להכי אהני\u0004 \u0005[לכך הועיל]\u0006 מה שנאמר \u0003\"אם אחרת\u0004 יקח לו","\u0003\"\u0004ללמדנו שראוי ללמוד קנין עבדים מקנין המצוי בקידושין דווקא והוא שטר. ושואלים: \u0003ורב הונא האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"לא תצא כצאת העבדים\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 שאינו צריך ללמוד ממנו קנין שטר באמה עבריה כרב אחא בר יעקב. ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לגופו ללמד \u0003שאינה יוצאה בראשי אברים כעבד\u0004 כנעני, שאם האדון גרם לה שייפגע אחד מראשי האיברים שלה — אינה יוצאת על ידי כך לחופשי. ושואלים: \u0003ורב חסדא,\u0004 מהיכן לומד הוא דבר זה? ומשיבים: \u0003אם כן,\u0004 שהפסוק בא ללמדנו רק דין אחד \u0003לכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"לא תצא כעבדים\", מאי\u0004 \u0005[מה]\u0006 טעם התוספת \u0003\"כצאת העבדים\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני דברים],\u0006 הן שאינה יוצאת בראשי איברים, הן שדרך קניינה הוא כקנין עבדים — בשטר.","מקור הדין ששנינו במשנה לגבי עבד עברי שהוא \u0003קונה את עצמו בשנים\u0004 כשמסתיימות שש שנות עבודתו הוא במה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שש שנים יעבד ובשבעת\u0004 יצא לחפשי חינם\u0003\"\u0004 (שמות כא, ב).","יוצא \u0003ביובל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"עד שנת היבל יעבד עמך\"\u0004 (ויקרא כה, מ).","יוצא \u0003בגרעון כסף\u0004 — \u0003אמר חזקיה: דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 \u0003\"והפדה\"\u0004 (שמות כא, ח) — \u0003מלמד שמגרע פדיונה,\u0004 כלומר, מחזיר לאדון חלק מהכסף לפי חשבון עבור אותם השנים שלא עבדה — \u0003ויוצאה,\u0004 והוא הדין לעבד. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וקונה\u0004 העבד \u0003את עצמו בכסף ובשוה כסף ובשטר.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 זה שנקנה ב\u0003כסף\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מכסף מקנתו\"\u0004 (ויקרא כה, נא), \u0003שוה כסף נמי\u0004 \u0005[גם כן]\u0006 \u0003\"ישיב\u0004 את \u0003גאלתו\"\u0004 (שם) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 ובא כתוב זה \u0003לרבות שוה כסף\u0004 שהוא נחשב \u0003ממש\u0004 \u0003ככסף,\u0004 שכל דבר שיש בו ערך יש בו כדי השבה. \u0003אלא האי שטר היכי דמי\u0004 \u0005[שטר זה\u0006 שאמרנו \u0005באיזה אופן הוא בדיוק]?\u0006 \u0003אילימא דכתב ליה שטרא אדמיה\u0004 \u0005[אם תאמר שכתב לו\u0006 העבד \u0005שטר על דמי עצמו]\u0006 אם כן \u0003היינו\u0004 \u0005[הרי הוא]\u0006 ממש כמו \u0003כסף,\u0004 ומה ההבדל?","\u0003אלא\u0004 הכוונה היא לשטר \u0003שיחרור,\u0004 שכתב לו האדון שטר שהוא משוחרר. ושואלים: \u0003שטר למה לי\u0004 לצורך זה? \u0003לימא ליה באפי תרי \"זיל\"\u0004 \u0005[שיאמר לו בפני שנים \"לך\",\u0006 צא לחופשי\u0005].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שיאמר לו \u0003באפי בי דינא\u0004 \u0005[בפני בית\u0006 \u0005דין]\u0006 \u0003\"זיל\"\u0004 \u0005[לך].\u0006 \u0003אמר רבא: זאת אומרת עבד עברי גופו קנוי\u0004 ואין זה נחשב כחוב כספי בלבד, \u0003ו\u0004משום כך \u0003הרב שמחל על גרעונו\u0004 (על הכסף שצריך העבד לתת לו תמורת השנים שנותרו לו לעבוד) — \u0003אין גרעונו מחול,\u0004 שאף שיכול למחול על ידי אמירה בלבד על החוב הכספי, אין זה כשלעצמו מבטל את הקנין שיש לו בעבד, אלא אם כן משחררו בשטר.","שנינו במשנה ש\u0003יתירה עליו, אמה העבריה\u0004 על עבד עברי, שהיא יוצאה מרשות האדון אף בסימנים. \u0003אמר ריש לקיש: אמה העבריה קונה את עצמה במיתת האב\u0004 ויוצאת על ידי כך \u0003מרשות אדון.\u0004 ודבר זה נלמד \u0003מקל וחומר: ומה סימנין שאין מוציאין מרשות אב,\u0004 שהרי אף שהביאה סימני נערות עדיין היא ברשותו לכמה דברים, מכל מקום \u0003מוציאין\u0004 הם אותה \u0003מרשות אדון, מיתה שמוציאה\u0004 אותה \u0003מרשות אב\u0004 לגמרי, \u0003אינו דין שמוציאה\u0004 אותה \u0003מרשות אדון?\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה שאמר \u0003רב הושעיא:\u0004 שנינו במשנתנו ש\u0003יתירה עליו אמה העבריה שקונה את עצמה\u0004 אף \u0003בסימנין, ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום להלכה זו של ריש לקיש, \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]\u0006 הבדל נוסף — שיוצאה אף ב\u0003מיתת האב!\u0004 ומשיבים: אין להוכיח ממה שלא נזכר הדבר במפורש כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 עוד הבדלים נוספים שלא מנה.","ומקשים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006אף דבר \u0005זה]\u0006 \u0003שייר,\u0004 שהרי בודאי לא שייר דבר אחד בלבד? ומשיבים: \u0003שייר מיתת האדון,\u0004 שיוצאת לחופשי אם מת, ואינה עובדת את יורשיו. ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום מיתת האדון לאו שיורא הוא\u0004 \u0005[אין זה שיור]\u0006 ש\u0003כיון דאיכא נמי\u0004 \u0005[שיש גם כן]\u0006 דין דומה לזה \u0003באיש\u0004 (בעבד נרצע) — \u0003לא קתני\u0004 \u0005[שנה]\u0006 אותו.","ואם כן חוזרת שוב הקושיה: \u0003ואלא ניתני\u0004 \u0005[שישנה]\u0006 שיוצאה במיתת האב! ומשיבים: ה\u0003תנא\u0004 של המשנה \u0003דבר שיש לו קצבה קתני\u0004 \u0005[שנה\u0006 במשנה\u0005],\u0006 \u0003דבר שאין לו קצבה,\u0004 שאין בו זמן קבוע, וייתכן שלא יקרה — \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003סימנין\u0004 ש\u0003אין להם קצבה,\u0004 שהרי אין זמן קבוע להופעתם שהרי יש נערות המקדימות להביא סימנים ויש המאחרות, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]!\u0006 \u0003אמר רב ספרא:\u0004 אף על פי שסימנים \u0003אין להם קצבה למעלה,\u0004 שבכל עת שתביא סימנים לאחר שמלאו לה שתים עשרה שנה יצאה מכלל קטנה, \u0003אבל יש להם קצבה\u0004"],["\u0003למטה\u0004 שיש גבול זמן תחתון, שבפחות מגיל זה גם אם הביאו סימנים אין הם נחשבים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן תשע שנים שהביא שתי שערות\u0004 — לכל הדעות אין הן נחשבות לסימן בגרות, אלא הריהן כשערות הגדלות ב\u0003שומא\u0004 (יבלת), \u0003מבן תשע שנים ויום אחד עד בן שתים עשרה שנה ויום אחד ו\u0004אפילו \u0003עודן בו,\u0004 שלא נשרו — הרי היא \u0003שומא,\u0004 ואילו \u0003ר' יוסי בר' יהודה אומר: סימן\u0004 הוא לבגרות. \u0003בן שלש עשרה שנה ויום אחד\u0004 והביא שתי שערות — \u0003דברי הכל סימן.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת:\u0004 שנינו ש\u0003ר' שמעון אומר: ארבעה\u0004 אופנים שונים של שחרור עבדים יש, ובזמן השחרור \u0003מעניקים להם,\u0004 למשוחררים. \u0003שלשה\u0004 אופנים \u0003באיש\u0004 (עבד עברי), \u0003ושלשה באשה\u0004 (אמה עבריה) \u0003ואי\u0004 (ואין) \u0003אתה יכול לומר ארבעה ב\u0004אף \u0003אחד\u0004 מהם, \u0003לפי שאין\u0004 שחרור על ידי \u0003סימנים באיש, ואין\u0004 שחרור על ידי \u0003רציעה באשה,\u0004 ולכן יש בכל אחד מהם רק שלוש דרכי שחרור.","\u0003ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום לדברי ריש לקיש \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003מיתת אב\u0004 באמה עבריה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הכא נמי תני\u0004 \u0005[כאן גם כן שנה]\u0006 \u0003ושייר\u0004 אופן נוסף \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ארבעה קתני\u0004 \u0005[שנה]\u0006 משמע שקובע מספר מדוייק! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שה\u0003תנא, דבר שיש לו קצבה קתני\u0004 \u0005[שנה]\u0006 \u0003ודבר שאין לו קצבה לא קתני\u0004 \u0005[שנה]\u0006 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003סימנין\u0004 ש\u0003אין להם קצבה, ו\u0004בכל זאת \u0003קתני\u0004 \u0005[ושנה]\u0006 אותם!","\u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 תפרש \u0003כ\u0004מו שאמר \u0003רב ספרא\u0004 שיש להם קצבה למטה, \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מיתת אדון,\u0004 ש\u0003אין להם קצבה וקתני\u0004 \u0005[ושנה],\u0006 ואם כן אין להסביר את דברי ר' שמעון בדרך זו! ומשיבים: \u0003מיתת אדון נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 ואין אופן שחרור זה נמנה בין ארבעת דרכי השחרור שהוזכרו.","ושואלים: \u0003ואלא\u0004 אם אין אתה מונה מיתת אדון, אם כן, \u0003ארבעה מאי ניהו\u0004 \u0005[מה הם]?\u0006 ומשיבים: \u0003שנים,\u0004 שעבד ואמה יוצאים לאחר שש שנים, \u0003ו\u0004יוצאים ב\u0003יובל\u0004 אף אם חל בתוך שש השנים, \u0003ו\u0004כן \u0003יובל של רציעה,\u0004 של עבד נרצע, \u0003ואמה העבריה\u0004 שיוצאה \u0003בסימנים.\u0004","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דקתני סיפא\u0004 \u0005[ששנה בסופה]\u0006 של הברייתא: \u0003אי\u0004 (אין) \u0003אתה יכול לומר ארבעה באחד מהם, לפי שאין סימנים באיש ואין רציעה באשה. ואם איתא\u0004 \u0005[ואם ישנה]\u0006 גם מיתת האדון, אם כן \u0003באשה מיהא משכחת לה\u0004 \u0005[לפחות מוצא אתה]\u0006 \u0003ארבעה\u0004 דרכי שחרור (שנים, יובל, סימנים, מיתת האדון), ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 גם \u0003רב עמרם\u0004 על דברי ריש לקיש ממה ששנינו: \u0003ואלו מעניקים להם: היוצא בשנים, וביובל, ובמיתת האדון, ואמה העבריה\u0004 היוצאה \u0003בסימנים. ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום לדברי ריש לקיש אם כן \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003מיתת אב! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר, והא\u0004 \u0005[והרי]\u0006 \u0003\"אלו\" קתני\u0004 \u0005[שנה],\u0006 לומר שדווקא אלו, ולא יותר!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שרק \u0003דבר שיש לו קצבה קתני\u0004 \u0005[שנה]\u0006 ואילו \u0003דבר שאין לו קצבה לא קתני\u0004 \u0005[לא שנה],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003סימנין\u0004 ש\u0003אין להם קצבה וקתני\u0004 \u0005[ושנה]\u0006 אותם כאן. \u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 \u0003כ\u0004דברי \u0003רב ספרא\u0004 שיש להם קצבה למטה, \u0003האיכא\u0004 \u0005[הרי יש]\u0006 \u0003מיתת אדון\u0004 ולכך אין קצבה! ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003ריש לקיש!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה]\u0006 היא ונדחו דבריו.","ושואלים: כיצד אתה סותר את דבריו \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ריש לקיש קל וחומר אמר,\u0004 וכיצד דוחים נימוק זה? ומשיבים: \u0003קל וחומר פריכא היא\u0004 \u0005[שבור,\u0006 רעוע \u0005הוא],\u0006 שאין לו בסיס. \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום לפרוך אותו\u0005]\u0006 ולטעון כך: \u0003מה לסימנין\u0004 — \u0003שנשתנה הגוף,\u0004 ואפשר לומר שעכשיו היא נחשבת כאישיות אחרת ולכן היא יוצאת לחירות, \u0003תאמר במיתת אב\u0004 — \u0003שכן לא נשתנה הגוף.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003ענק\u0004 (הענקה) שנותנים ל\u0003עבד עברי\u0004 כשמשתחרר — \u0003לעצמו, וענק\u0004 של \u0003אמה העבריה\u0004 — \u0003לעצמה. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003ענק אמה העבריה ומציאתה\u0004 שייכים \u0003לאביה, ואין לרבה\u0004 (אדוניה) \u0003אלא שכר בטלה בלבד,\u0004 כלומר, מה שיכול היה להשתכר מעבודתה בזמן שהגביהה את המציאה.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 ההבדל בין שתי הברייתות הוא \u0003הא\u0004 — \u0003דנפקא\u0004 \u0005[זו\u0006 שמענקה לאביה היא זו \u0005שיוצאת]\u0006 \u0003בסימנים,\u0004 שכיון שהיא נערה ועודנה ברשות אביה לכמה דברים, לכן הוא המקבל את המענק, \u0003והא\u0004 \u0005[וזו]\u0006 שמענקה לעצמה היא זו \u0003דנפקא לה\u0004 \u0005[שיוצאת]\u0006 \u0003במיתת אב\u0004 ומכיון שאין לה אב — המענק הוא לעצמה. וכדברי ריש לקיש, ובניגוד למסקנה שדחתה את דבריו!","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זו וזו],\u0006 שתי הברייתות, עוסקות באמה \u0003דנפקא\u0004 \u0005[שיוצאת]\u0006 \u0003לה בסימנין, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאיתיה לאב\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 היא במקרה \u0005שישנו האב]\u0006 ואז הוא המקבל את המענק, \u0003הא דליתיה לאב\u0004 \u0005[\u0006וברייתא \u0005זו\u0006 במקרה \u0005שהאב איננו],\u0006 שמת בינתיים לפני שהביאה סמנים ואז היא מקבלת את המענק.","שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו \u0003ענק\u0004 של \u0003אמה העבריה לעצמה\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003אחין\u0004 של האמה, שהם אינם מקבלים את המענק לאחר מיתת האב. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"והתנחלתם אתם לבניכם אחריכם\"\u0004 (ויקרא כה, מו) מדייקים: \u0003אותם,\u0004 את העבדים הגויים, אתם מורישים \u0003לבניכם, ולא\u0004 את \u0003בנותיכם לבניכם. מכאן שאין אדם מוריש זכות\u0004 שיש לו ב\u0003בתו לבנו.\u0004","\u0003אלא ענק עבד עברי לעצמו פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! \u0003אלא למאן\u0004 \u0005[למי\u0006 יתנו אותו\u0005]?\u0006 \u0003אמר רב יוסף: יו\"ד קרת קא חזינא הכא\u0004 \u0005[יו\"ד\u0006 קטנה שנעשתה \u0005עיר\u0006 גדולה \u0005אני רואה כאן],\u0006 כלומר, התנא לא היה צריך לשנות זאת, ואמר את הדברים משום גרר הלשון, ואין בהם כל חידוש.","\u0003אביי אמר, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת: הא מני\u0004 \u0005[זו\u0006 הברייתא כשיטת \u0005מי היא]\u0006 — כשיטת החכם \u0003תוטאי הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003תוטאי אומר:\u0004 מה שנאמר \"העניק תעניק \u0003לו\"\u0004 הכוונה — \u0003ולא לבעל חובו.\u0004 שגם אם העבד חייב כסף — אין המענק עובר לבעל החוב.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה שהזכרנו. שנינו, \u0003אלו מעניקים להם\u0004 עת שחרורם: עבד \u0003היוצא בשנים, וביובל, ובמיתת אדון, ואמה העבריה\u0004 היוצאת \u0003בסימנין. אבל\u0004 ה\u0003בורח\u0004 מאדוניו \u0003ו\u0004כן ה\u0003יוצא בגרעון כסף\u0004 — \u0003אין מעניקים לו. ר' מאיר אומר: בורח אין מעניקין לו, ויוצא בגרעון כסף\u0004 — \u0003מעניקים לו.\u0004","\u0003ר' שמעון אומר: ארבעה מעניקים להם, שלשה באיש ושלשה באשה, ואי\u0004 (ואין) \u0003אתה יכול לומר ארבעה באחד מהן לפי שאין סימנין באיש ו\u0004אין \u0003רציעה באשה.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומבארים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003יכול לא יהו מעניקים אלא ליוצא בשש, מנין לרבות\u0004 שמעניקים גם לזה ש\u0003יוצא ביובל ובמיתת האדון, ואמה העבריה\u0004 היוצאה \u0003בסימנין? תלמוד לומר:\u0004 שכתוב פעמיים \u0003\"תשלחנו\" \"וכי תשלחנו\"\u0004 (דברים טו, יג), שבאו לרבות שבכל אופן שמשחררים את העבד צריכים להעניק לו.","\u0003יכול שאני מרבה\u0004 אף \u0003את ה\u0004\u0003בורח ויוצא בגרעון כסף\u0004 — \u0003תלמוד לומר: \"וכי תשלחנו חפשי מעמך\"\u0004 (שם) \u0003מי ששילוחו\u0004 הוא \u0003מעמך,\u0004 כלומר, מרצונך ולפי דעתך, \u0003יצא בורח ויוצא בגרעון כסף שאין שילוחו מעמך. ר' מאיר אומר: בורח אין מעניקין לו\u0004 לפי ש\u0003אין שילוחו מעמך\u0004 אלא הוא מעצמו ברח, \u0003אבל יוצא בגרעון כסף ששילוחו מעמך\u0004 שהדבר צריך להיעשות בהסכמת האדון המקבל את הכסף.","ותוהים על עצם הענין: \u0003בורח, השלמה בעי\u0004 \u0005[צריך],\u0006 כלומר, צריך הוא להשלים את השנים שהיה מחוייב לעבוד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין לבורח שחייב להשלים\u0004 — \u0003תלמוד לומר: \"שש שנים יעבד\"\u0004 (שמות כא, ב) ולא בפחות מזה, ואם ברח באמצע — חייב הוא להשלים עבודת שש שנים."],["\u0003יכול אפילו\u0004 מי ש\u0003חלה\u0004 ולא יכול היה לעבוד יצטרך להשלים את זמן מחלתו — \u0003תלמוד לומר: \"ובשבעת יצא\"\u0004 (שמות כא, ב) מכל מקום, ואפילו לא עבד בכל שש השנים. ולענייננו, מדוע לא יקבל הענקה, והרי השלים את שש שנות עבדותו?","\u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כגון שברח ופגע בו יובל\u0004 מיד אחר כך ולא השלים את השנים. וחידוש דין למדנו, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ואפיק ליה\u0004 \u0005[והוציא אותו]\u0006 ה\u0003יובל שילוחו מעמך קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003ולא ניקנסיה\u0004 \u0005[נקנוס אותו],\u0006 \u0003ונעניק ליה\u0004 \u0005[לו]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שברח איבד את מענקו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול אפילו חלה\u0004 יצטרך להשלים בעבודה את הזמן שהיה חולה — \u0003תלמוד לומר: \"ובשבעת יצא\".\u0004 ויש לשאול: \u0003אפילו חלה כל שש\u0004 לא יצטרך להשלים זמן עבודתו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חלה שלש\u0004 שנים \u0003ועבד שלש\u0004 שנים — \u0003אינו חייב להשלים,\u0004 ואולם אם \u0003חלה כל שש\u0004 — \u0003חייב להשלים! אמר רב ששת:\u0004 מדובר שחלה ואינו יכול לעבוד עוד עבודה קשה, אבל עובד הוא עבודה כלשהי, כגון \u0003בעושה מעשה מחט\u0004 (תופר בגדים), לכן אינו חייב להשלים, אפילו חלה כל שש.","ומעירים: \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה]\u0006 שיש בה סתירה פנימית, \u0003אמרת\u0004 מצד אחד כי כאשר \u0003חלה שלש ועבד שלש\u0004 — \u0003אין חייב להשלים,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם חלה \u0003ארבע\u0004 שנים — \u0003חייב להשלים. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003חלה כל שש\u0004 — \u0003חייב להשלים,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם חלה \u0003ארבע\u0004 — \u0003אין חייב להשלים!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003חלה ארבע נעשה כמי שחלה כל שש וחייב להשלים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כמה מעניקים לו\u0004 לעבד המשתחרר? — שווי \u0003חמש סלעים מכל מין ומין\u0004 האמור בפרשה \"העניק תעניק לו מצאנך ומגרנך ומיקבך\" (דברים טו, יד), \u0003שהן\u0004 בסך הכל \u0003חמש עשרה סלעים,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: שלשים\u0004 סלעים בסך הכל, \u0003כשלשים\u0004 שקלים \u0003של\u0004 כופר שמשלמים עבור \u0003עבד\u0004 (ראה שמות כא, לב). \u0003ר' שמעון אומר: חמשים\u0004 שקל נותנים לו, \u0003כחמשים שבערכין,\u0004 שהוא הערך הקצוב הגדול ביותר לאדם (ראה ויקרא כז, ג).","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חמש סלעים מכל מין ומין, שהם חמש עשרה סלעים,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ושואלים: \u0003ו\u0004כי \u0003ר' מאיר מנינא אתא לאשמועינן\u0004 \u0005[מנין בא\u0006 הוא \u0005להשמיע לנו]\u0006 ששלוש פעמים חמש הן חמש עשרה? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003מיבצר\u0004 \u0005[לפחות]\u0006 \u0003הוא\u0004 ש\u0003לא מבצר ליה מהאי מנינא\u0004 \u0005[פוחת לו\u0006 לעבד \u0005ממנין\u0006 כולל \u0005זה],\u0006 \u0003ואי בצר ליה מחד מינא וטפי ליה מחד מינא לית לן\u0004 \u0005[\u0006אבל \u0005אם פחת לו ממין אחד והוסיף לו ממין אחד אין לנו]\u0006 \u0003בה\u0004 הקפדה, וגם כך קיים את המצוה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר?\u0004 שהרי הוא לא נתן נימוק לדבריו. ומסבירים: \u0003יליף\u0004 \u0005[לומד]\u0006 הוא גזירה שווה \u0003\"ריקם\"\u0004 האמור בהענקה (\"לא תשלחנו ריקם\". דברים טו, יג) \u0003\"ריקם\" מבכור\u0004 (\"כל בכור בניך תפדה ולא יראו פני ריקם\". שמות לד, כ), \u0003מה להלן\u0004 בפדיון הבכור השיעור הוא \u0003חמש סלעים\u0004 — \u0003אף כאן\u0004 בהענקה השיעור הוא \u0003חמש סלעים.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003חמש סלעים מכולהו\u0004 \u0005[מכולם],\u0006 מכל המינים? ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005נאמר]\u0006 \u0003\"ריקם\" לבסוף,\u0004 היה הדין \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"ריקם\" ברישא\u0004 \u0005[בתחילה]\u0006 \"לא תשלחנו ריקם. העניק תעניק לו מצאנך וכו'\" \u0003שדי\u0004 \u0005[השלך],\u0006 כלומר, יחס ושייך \u0003\"ריקם\"\u0004 על \u0003\"צאן\"\u0004 שנזכר שם, \u0003\"ריקם\"\u0004 על \u0003\"גורן\",\u0004 \u0003\"ריקם\"\u0004 על \u0003\"יקב\".\u0004","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003\"ריקם\" \"ריקם\" מעולת ראיה\u0004 שאף בה נאמר \"ולא יראה את פני ה' ריקם\" (דברים טז, טז) ואין לה שיעור קצוב! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשר ברכך ה' אלהיך\"\u0004 (שם טו, יד), כלומר, שצריך לתת כשיעור המרובה, בדבר שיש בו ברכה.","על מה ש\u0003ר' יהודה אומר\u0004 שמעניקים לו \u0003שלשים כשלשים\u0004 שקלים \u0003של עבד,\u0004 שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 הוא בגזירה שווה של לשון \u0003\"נתינה\"\u0004 האמורה, בהענקה (\"תתן לו\") מלשון \u0003\"נתינה\"\u0004 האמורה בדמי \u0003עבד\u0004 שנגחו שור (\"כסף שלשים שקלים יתן לאדוניו\". שמות כא, לב), \u0003מה להלן\u0004 בתשלומי עבד \u0003שלשים\u0004 שקלים — \u0003אף כאן\u0004 בהענקה \u0003שלשים.\u0004","ושואלים: ואם כן שלומדים גזירה שווה \"נתינה\" \"נתינה\", \u0003ונילף\u0004 \u0005[ושילמד]\u0006 גזירה שווה \u0003\"נתינה\" \"נתינה\" מערכין, מה להלן\u0004 בערכין \u0003חמשים\u0004 — \u0003אף כאן חמשים!\u0004","ומשיבים: \u0003חדא\u0004 \u0005[\u0006נימוק \u0005אחד],\u0006 \u0003דתפשתה מרובה לא תפשתה, תפשתה מועט תפשתה,\u0004 ואם יש לדמות — צריך לדמות למועט. \u0003ועוד\u0004 דבר, האמור ב\u0003עבד מעבד הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 ולא מסתם אדם.","על מה ש\u0003ר' שמעון אומר\u0004 שמעניקים לו \u0003חמשים כחמשים שבערכין,\u0004 שואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון\u0004 ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 \u0003\"נתינה\" \"נתינה\" מערכין, מה להלן חמשים\u0004 — \u0003אף כאן חמשים.\u0004 ושואלים: כיון שהגזירה שווה מתייחסת לערכין ככלל \u0003ואימא\u0004 \u0005[ואמור]\u0006 שיתן \u0003בפחות שבערכין\u0004 (שלשה סלעים בלבד)! ומשיבים: \u0003\"אשר ברכך ה' אלהיך\" כתיב\u0004 \u0005[נאמר]\u0006 שיש לתת כשיעור הגדול, שיש בו ברכה.","ומקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 כר' יהודה \u0003\"נתינה\" \"נתינה\" מעבד, מה להלן שלשים אף כאן שלשים,\u0004 ויש שני טעמים ללמוד דווקא משם, \u0003חדא\u0004 \u0005[אחד]\u0006 \u0003דתפשתה מרובה לא תפשתה, ועוד, עבד מעבד הוה ליה למילף\u0004 \u0005[היה לו ללמוד]!\u0006 ומשיבים: \u0003ר' שמעון \"מיכה\" \"מיכה\" גמר\u0004 \u0005[למד]\u0006 בגזירה שווה שבדין ערכין נאמר \"ואם מך הוא\" (ויקרא כז, ח) ובעבד עברי נאמר \"וכי ימוך\" (שם כה, לט).","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' מאיר היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003צאן גורן ויקב\u0004 שמכאן נלמד סכום של חמשה עשר סלעים להענקה. \u0003אלא ל\u0004שיטת \u0003ר' יהודה ו\u0004שיטת \u0003ר' שמעון האי\u0004 \u0005[זה]\u0006 \u0003צאן גורן ויקב למה לי,\u0004 הרי יכול לתת גם ממין אחר?","ומשיבים: \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[\u0006דבר \u0005זה צריך לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול לא יהו מעניקין אלא מצאן גורן ויקב, מנין לרבות כל דבר\u0004 — \u0003תלמוד לומר: \"אשר ברכך ה' אלהיך\". אם כן מה תלמוד לומר צאן גורן ויקב\u0004 — \u0003לומר לך: מה צאן גורן ויקב מיוחדים שישנן בכלל ברכה,\u0004 שהם דברים הגדלים ומתרבים \u0003אף כל\u0004 דברים \u0003שישנן בכלל ברכה, יצאו כספים\u0004 שאין נותן לו שאינם מתרבים מעצמם, אלו \u0003דברי ר' שמעון. ר' אליעזר בן יעקב אומר: יצאו פרדות,\u0004 שכיון שאינן פרות ורבות אינן בכלל ברכה.","ושואלים: \u0003ור' שמעון\u0004 מדוע מיעט כספים ולא פרדות? ומשיבים: \u0003פרדות\u0004 מכל מקום \u0003משבחן בגופייהו\u0004 \u0005[משביחות בגופן],\u0006 שאף שאינן מתרבות, מכל מקום הן גדלות ומשביחות. \u0003ו\u0004לעומת זאת סבור \u0003ר' אליעזר בן יעקב\u0004 ש\u0003כספים עביד בהו עיסקא\u0004 \u0005[עושה בהם עסק]\u0006 ומרויח בו, והרי יש בכך ברכה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כולם — צאן, גורן ויקב; \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה אומרת התורה]\u0006 \u0003צאן\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003בעלי חיים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יתן לו, ואולם \u0003גידולי קרקע\u0004 — \u0003לא,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003גורן. ואי כתב\u0004 \u0005[ואם היתה אומרת]\u0006 \u0003גורן\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003גידולי קרקע\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואילו \u0003בעלי חיים\u0004 — \u0003לא,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003צאן.\u0004 ושואלים: אם כן \u0003יקב למה לי?\u0004 אחרי שכבר נזכר גורן?"],["ומשיבים: \u0003למר\u0004 \u0005[לחכם\u0006 זה, ר' שמעון\u0005]\u0006 בא הדבר \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003כספים, למר\u0004 \u0005[לחכם\u0006 זה, ר' אליעזר\u0005]\u0006 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003פרדות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"\u0004העניק תעניק לו... \u0003אשר ברכך ה' אלהיך\"\u0004 (דברים טו, יד) \u0003יכול\u0004 רק אם \u0003נתברך בית בגללו\u0004 — \u0003מעניקים לו,\u0004 אבל אם \u0003לא נתברך בית בגללו\u0004 — \u0003אין מעניקים לו, תלמוד לומר: \"העניק תעניק\",\u0004 כלומר, ש\u0003מכל מקום\u0004 אתה מעניק. \u0003אם כן מה תלמוד לומר \"אשר ברכך\"\u0004 — לומר: \u0003הכל לפי ברכה תן לו,\u0004 שאם היתה ברכה מרובה — צריך להוסיף.","\u0003ר' אלעזר בן עזריה אומר:\u0004 יש לקיים \u0003דברים ככתבן:\u0004 אם \u0003נתברך בית בגללו\u0004 — \u0003מעניקים לו, לא נתברך\u0004 \u0003בית בגללו\u0004 — \u0003אין מעניקים לו\u0004 כלל. \u0003אם כן מה תלמוד לומר\u0004 הכפילות של \u0003\"העניק תעניק\"\u0004 — \u0003דברה תורה כלשון בני אדם,\u0004 וכפילות זו היא מסגנון המקרא ואינה באה ללמד דבר הלכה מיוחד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עבד עברי עובד את הבן\u0004 של אדוניו שמת, \u0003ואינו עובד את הבת. אמה עבריה אינה עובדת לא את הבן ולא את הבת,\u0004 אלא את האדון בלבד. עבד \u0003הנרצע, ו\u0004העבד \u0003הנמכר לגוי אינו עובד לא את הבן ולא את הבת. אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עבד עברי עובד את הבן, ואינו עובד את הבת. מנהני מילי\u0004 \u0005[מניין הדברים האלה]?\u0006","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בעבד עברי \u0003\"ועבדך שש שנים\"\u0004 (שם, יב) והלשון \"עבדך\" יש בו הדגשה: \u0003לך ולא ליורש,\u0004 כלומר, לא לשאר יורשים כגון הבן או האח, שאם מת האדון וירש אדם אחר את נכסיו — אין העבד עובד אותו. \u0003אתה אומר\u0004 שהמיעוט הוא: \u0003לך ולא ליורש, או אינו אלא\u0004 למעט לגמרי: \u0003לך ולא לבן?\u0004 ומשיבים: \u0003כשהוא אומר \"שש שנים יעבד\"\u0004 (שמות כא, ב) בלא למעט דבר \u0003הרי\u0004 הריבוי \u0003לבן\u0004 הוא \u0003אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"ועבדך שש שנים\"\u0004 ש\"עבדך\" מדגיש דווקא \u0003לך\u0004 — כוונתו \u0003ולא ליורש\u0004 שאינו בן.","ושואלים: \u0003מה ראית לרבות את הבן\u0004 היורש, \u0003ולהוציא את האח\u0004 היורש? ומשיבים: \u0003מרבה אני את הבן\u0004 — \u0003שכן קם תחת אביו\u0004 הן \u0003ליעדה,\u0004 שכשם שהאב יכול לייעד את האמה כאשה לעצמו, כך יכול לקדשה לבנו. \u0003ו\u0004כן \u0003לשדה אחוזה\u0004 שאם הקדיש אביו שדה והבן פדה אותו — הרי זה כאילו פדה אותו הוא עצמו ושב השדה ביובל למשפחה, אבל אם פדאו אחר אינו חוזר למשפחה.","ושואלים: \u0003אדרבה, מרבה אני את האח שכן קם תחת אחיו ליבום!\u0004 אומרים: זו אינה ראיה, \u0003כלום יש יבום\u0004 — \u0003אלא במקום שאין בן, הא\u0004 \u0005[הרי]\u0006 אם \u0003יש בן\u0004 — \u0003אין יבום.\u0004","ושואלים: \u0003אלא טעמא דאיכא הא פירכא\u0004 \u0005[הטעם\u0006 דווקא, משום \u0005שיש פירכה זו]\u0006 שאין יבום במקום שיש בן, \u0003הא לאו הכי\u0004 \u0005[הרי לולא זה]\u0006 הייתי אומר ש\u0003אח עדיף\u0004 על בן? \u0003ותיפוק\u0004 \u0005[ותצא]\u0006 \u0003לי\u0004 מסקנה זו שבן עומד במקום אביו יותר מאשר אח באופן אחר גם בלא כוונה זו, \u0003דהכא תרתי\u0004 \u0005[שכאן\u0006 ביחס להעדפת הבן יש \u0005שתי\u0006 ראיות\u0005],\u0006 יעוד ושדה אחוזה, \u0003והכא חדא\u0004 \u0005[וכאן,\u0006 ביחס לאח, יש רק ראיה \u0005אחת]!\u0006","ומשיבים: \u0003שדה אחוזה נמי מהאי\u0004 \u0005[גם כן מאותה]\u0006 \u0003פירכא הוא דקא נפקא ליה\u0004 \u0005[שיוצא לו]\u0006 \u0003לתנא\u0004 שמייבום הוא למד שרק הבן קם תחת אביו לפדיון השדה ולא האח, שאומר שם: \u0003כלום יש יבום אלא במקום שאין בן.\u0004","שנינו באותה ברייתא ש\u0003אמה העבריה אינה עובדת לא את הבן ולא את הבת.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר ר' פדא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בסוף הפסוק המדבר על עבד נרצע: \u0003\"ואף לאמתך תעשה כן\"\u0004 (דברים טו, יז) \u0003הקישה\u0004 (השווה אותה) \u0003הכתוב\u0004 בכתוב זה \u0003ל\u0004עבד \u0003נרצע,\u0004 \u0003מה\u0004 העבד ה\u0003נרצע אינו עובד לא את הבן ולא את הבת\u0004 — \u0003אף אמה העבריה אינה עובדת לא את הבן ולא את הבת.\u0004 ושואלים: \u0003והאי\u0004 \u0005[ו\u0006הכתוב \u0005הזה]\u0006 \u0003\"לאמתך תעשה כן\" להכי\u0004 \u0005[ל\u0006דבר \u0005זה]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד? \u0003הא מיבעי ליה לכדתניא\u0004 \u0005[הרי צריך אותו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ואף לאמתך תעשה כן\" —\u0004 הכוונה היא \u0003להעניק\u0004 לה.","\u0003אתה אומר\u0004 שהשוואה זו באה לחיוב \u0003להעניק\u0004 לאמה העבריה \u0003או אינו אלא ל\u0004דין \u0003רציעה\u0004 (האמור בענין הקודם לאמה עבריה) נאמר \"ואף לאמתך תעשה כן\", שאף היא נרצעת? — \u0003כשהוא אומר\u0004 בענין רציעה \u0003\"ואם אמר יאמר העבד\u0004\u0003\"\u0004 (שמות כא, ה) — הרי זה בא למעט: העבד, \u0003ולא אמה העבריה. הרי רציעה אמור\u0004 שאינה שייכת באמה,","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"ואף לאמתך תעשה כן\"\u0004 — \u0003להעניק!\u0004 ומשיבים: \u0003אם כן\u0004 שלצורך ההיקש לנרצע בלבד בא הכתוב \u0003נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"\u0004ואף \u0003לאמתך כן\" מאי\u0004 \u0005[מהי]\u0006 התוספת \u0003\"תעשה\"? שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שני\u0006 דברים\u0005],\u0006 גם שאין אמה העבריה עובדת את הבן וגם שזכאית להענקה.","עוד שנינו בברייתא ש\u0003הנרצע והנמכר לגוי אינו עובד לא את הבן ולא את הבת.\u0004 ושואלים: \u0003נרצע\u0004 מניין? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ורצע אדניו את אזנו במרצע ועבדו לעלם\"\u0004 (שם, ו) להדגיש: \"ועבדו\" — אותו, \u0003ולא את הבן ואת הבת. נמכר לגוי מנין? אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]\u0006 ביציאת עבד הנמכר: \u0003\"וחשב עם קנהו\"\u0004 (ויקרא כה, נ) והרי זו הדגשה: עם קונהו בלבד \u0003ולא עם יורשי קונהו.\u0004","\u0003אמר רבא: דבר תורה\u0004 (מדין התורה) \u0003גוי יורש את אביו, שנאמר\u0004 בנמכר לגוי: \u0003\"וחשב עם קונהו\"\u0004 ודרשנו: \u0003ולא עם יורשי קונהו. מכלל\u0004 הדברים אתה למד \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 בדרך כלל \u0003יורשים\u0004 לגוי. ואולם \u0003גר\u0004 שיורש \u0003את הגוי\u0004 אביו או את מורישו — \u0003אינו מדברי תורה,\u0004 שכיון שנתגייר נעשה כאדם חדש שאין לו קשר עם משפחתו הקודמת, \u0003אלא\u0004 יורשו \u0003מדברי סופרים.\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003גר וגוי שירשו את אביהם\u0004 ה\u0003גוי, גר יכול לומר ל\u0004אחיו ה\u0003גוי: טול אתה עבודה זרה ואני\u0004 אטול \u0003מעות, טול אתה יין נסך ואני פירות.\u0004 שכל עוד לא באו לרשות הגר יכול הוא לחלוק עם אחיו ולהניח לאח דברים שהוא אסור לו להשתמש בהם כיהודי. אבל \u0003משבאו\u0004 כבר \u0003לרשות גר\u0004 — \u0003אסור\u0004 להחליפם עם אחיו.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שירושת הגר את אביו היא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא באו לרשותו נמי\u0004 \u0005[גם כן],\u0006 \u0003כי שקיל\u0004 \u0005[כאשר\u0006 הוא \u0005לוקח]\u0006 מעות או פירות ונותן לו את העבודה זרה הלא \u0003חילופי עבודה זרה הוא דקא שקיל\u0004 \u0005[ש\u0006הוא \u0005לוקח],\u0006 שהרי זכה בחצי הירושה משעה שמת אביו ויש לו חלק בזה.","\u0003אלא\u0004 יש לומר כי זה שהגר יורש את אביו הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003גזירה הוא דעבוד רבנן\u0004 \u0005[שעשו חכמים]\u0006 שאם לא היה זוכה בירושת אביו \u0003שמא יחזור לסורו\u0004 (לקלקולו), שבגלל הפסד הירושה יחזור ויהיה גוי. ומשום שזכות זו בירושת אביו אינה זכות גמורה, אין העבודה זרה נחשבת כשייכת לו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003במה דברים אמורים\u0004 שמותר לגר לומר לאחיו הגוי שיטול מן הירושה את הדברים האסורים לו והוא יטול את המותרים — \u0003כשירשו, אבל כשנשתתפו\u0004 הגר והגוי — \u0003אסור\u0004 להם להתחלק בדרך זו שהגוי יקבל את העבודה הזרה שהרי נמצא הגר נהנה בדרך זו מעבודה זרה.","ובאותו ענין אומרים: ירושת \u0003גוי את\u0004 אביו \u0003הגר, וגר את\u0004 אביו \u0003הגר\u0004 — \u0003אינו לא מדברי תורה ולא מדברי סופרים. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לוה מעות מן הגר שנתגיירו בניו עמו\u0004 וכיון שכל אחד מהם התגייר לחוד, אין עוד קשר מבחינת ההלכה בין הבנים ובין האב, ולכן — \u0003לא יחזיר לבניו,\u0004 שהרי אינם נחשבים כיורשיו. \u0003ואם החזיר\u0004 — \u0003אין רוח חכמים נוחה הימנו.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אם החזיר \u0003רוח חכמים נוחה הימנו!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 מדובר בבן גר \u0003שהורתו ולידתו שלא בקדושה\u0004 של ישראל, שנולד הבן כשהיה אביו גוי, ולאחר מכן התגייר ומאחר שנולד כגוי ונתגייר אין כל קשר ביניהם, ואם חייב לאב — אינו צריך להחזיר לבן."],["\u0003וכאן\u0004 מדובר \u0003שהורתו שלא בקדושה,\u0004 שהרתה אותו אמו לפני שנתגיירה \u0003ו\u0004אולם \u0003לידתו בקדושה,\u0004 שנתגיירה אמו לפני שנולד ולזה ראוי להחזיר חוב.","\u0003רב חייא בר אבין אמר ר' יוחנן: גוי יורש את אביו דבר תורה,\u0004 וראיה לדבר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ירשה לעשו נתתי את הר שעיר\"\u0004 (דברים ב, ה). ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003ישראל משומד שאני\u0004 \u0005[שונה],\u0006 דינו מדין סתם גוי, ועשו אינו בגדר גוי אלא בגדר ישראל, כמו האבות, אלא שהוא נחשב כישראל משומד. \u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 ההוכחה: \u0003\"כי לבני לוט נתתי את ער ירשה\"\u0004 (שם, ט), ובני לוט הריהם גויים גמורים.","ושואלים: \u0003ורב חייא בר אבין מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבא\u0004 שלומד דין ירושה בגויים מהפסוק \"וחשב עם קונהו\"? ומשיבים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בתורה במפורש \u0003\"וחשב עם קונהו ולא עם יורשי קונהו\"?\u0004 ואם כן אין זו ראיה מכתוב מפורש אלא מדרשה.","ומצד שני שואלים: \u0003ורבא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב חייא בר אבין?\u0004 ומשיבים: שמא \u0003משום כבודו\u0004 של \u0003אברהם שאני\u0004 \u0005[שונה],\u0006 שמשום כבודו וזכותו נתנו באופן מיוחד ירושה זו לצאצאיו ולקרובי משפחתו, ואין הדין כן בשאר גויים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש ב\u0004דין עבד \u0003עברי\u0004 מה \u0003שאין ב\u0004אמה ה\u0003עבריה; ויש בעבריה\u0004 מה \u0003שאין בעברי.\u0004 ומפרטים: \u0003יש ב\u0004עבד \u0003עברי\u0004 — \u0003שהוא יוצא בשנים\u0004 כעבור שש שנים של עבדות, \u0003וביובל, ובמיתת האדון\u0004 — \u0003מה שאין כן ב\u0004אמה ה\u0003עבריה. ויש ב\u0004אמה ה\u0003עבריה\u0004 — \u0003שהרי\u0004 אמה \u0003עבריה יוצאה בסימנין\u0004 (סימני בגרות) \u0003ואינה נמכרת ונשנית\u0004 (פעם שניה), \u0003ומפדין אותה,\u0004 כלומר, אפשר לפדות אותה, אם יש כסף לאביה, \u0003בעל כורחו\u0004 של האדון, \u0003מה שאין כן ב\u0004עבד \u0003עברי.\u0004","ומפרשים את הברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יש בעברי שאין בעבריה\u0004 וכו'. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה: \u0003יתירה עליו אמה העבריה שקונה עצמה בסימנין\u0004 משמע מלשון \"יתירה\" שאף היא יוצאת בכל הדרכים שהעבד יוצא בהם! \u0003אמר רב ששת:\u0004 בברייתא מדובר \u0003כגון שיעדה\u0004 האדון לו בתוך שש, וכיון שכך הריהי כאשתו ואינה יוצאה מרשותו בכל הדרכים שבהם יוצא עבד.","ותוהים: אם \u0003יעדה פשיטא\u0004 \u0005[פשוט],\u0006 שהרי במקרה כזה כאשתו היא ו\u0003גיטא בעיא\u0004 \u0005[גט\u0006 היא \u0005צריכה]!\u0006 ואומרים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ש\u0003לא ליבטלה הילכתא מינה\u0004 \u0005[תיבטל ההלכה\u0006 העיקרית \u0005ממנה]\u0006 וגם אם ייעד אותה בכל זאת תוכל להשתחרר כעבד, ואף בלא גט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר באופן שייעדה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003יוצאה בסימנין?\u0004 שהרי אם ייעדה היא כאשתו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם לא יעדה\u0004 — \u0003יוצאה אף בסימנין.\u0004","שנינו בין דיני אמה עבריה ש\u0003אינה נמכרת ונשנית,\u0004 שאין מוכרים אותה פעם שניה. ומדייקים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003עבד עברי נמכר ונשנה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"\u0004ונמכר \u0003בגנבתו\"\u0004 (שמות כב, ב), כוונתו — בגניבתו \u0003ולא בכפילו,\u0004 שאף שנמכר כדי לשלם את עצם הגניבה שגנב, אינו נמכר כדי לשלם את כפל הגניבה שחייב. \u0003\"בגניבתו\"\u0004 — \u0003ולא בזממו,\u0004 שאם היה עד זומם ונתחייב לשלם בשל כך דמי גניבה ואין לו — אינו נמכר לעבד, ועוד אמרו \u0003\"בגניבתו\"\u0004 — לומר: על גניבה אחת בלבד הוא נמכר, ו\u0003כיון שנמכר פעם אחת שוב אי\u0004 (אין) \u0003אתה רשאי למוכרו.\u0004","\u0003אמר רבא:\u0004 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 מדובר \u0003בגניבה אחת,\u0004 אם גנב גניבה אחת גדולה, ואין בדמיו כדי לשלם את כל מה שגנב — אין מוכרים אותו פעם שניה. \u0003כאן בשתי גניבות,\u0004 שאם גנב פעם אחת ונמכר, ואחר כך גנב שוב — מוכרים אותו שנית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הלא משמעות הכתוב \u0003\"בגניבתו\"\u0004 — \u0003טובא\u0004 \u0005[הרבה]\u0006 \u0003משמע\u0004 ואפילו כמה גניבות! \u0003אלא אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 מדובר \u0003ב\u0004מי שגנב מ\u0003אדם אחד\u0004 שאינו נמכר ונשנה על כמה גניבות, \u0003כאן\u0004 מדובר \u0003ב\u0004שגנב מ\u0003שני בני אדם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גניבו\u0004 (הדבר שגנב) שווה \u0003אלף, ו\u0004הוא עצמו \u0003שוה\u0004 כעבד רק \u0003חמש מאות\u0004 — \u0003נמכר וחוזר ונמכר.\u0004 אם \u0003גניבו חמש מאות, ו\u0004הוא \u0003שוה אלף\u0004 — \u0003אינו נמכר כלל. ר' אליעזר אומר: אם היה גניבו\u0004 בדיוק \u0003כנגד ממכרו\u0004 — \u0003נמכר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינו נמכר.\u0004","\u0003אמר רבא: בהא זכנהו\u0004 \u0005[בזה נצחם]\u0006 \u0003ר' אליעזר לרבנן\u0004 \u0005[לחכמים],\u0006 \u0003דמאי שנא\u0004 \u0005[שמה שונה]\u0006 \u0003גניבו חמש מאות ושוה אלף\u0004 שהם מודים ש\u0003אין נמכר,\u0004 והטעם מפני ש\u0003נמכר כולו אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא חציו, הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר לומר: \u0003נמכר בגניבתו אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא נמכר בחצי גניבתו.\u0004","ועוד אמרנו בברייתא אודות אמה עבריה ש\u0003מפדין אותה בעל כרחו. סבר\u0004 \u0005[חשב]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]\u0006 כי הכוונה היא \u0003בעל כרחיה\u0004 \u0005[כרחו]\u0006 של ה\u0003אדון\u0004 שגם אם אינו רוצה — פודים אותה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי ניהו\u0004 \u0005[מה\u0006 כיצד \u0005הוא]\u0006 נעשה השחרור בעל כרחו של האדון — \u0003דכתבנא ליה שטרא אדמיה\u0004 \u0005[שכותבים לו שטר על דמיה]?\u0006 וכשיהיה לה כסף תשלם לו חוב זה. \u0003אמאי\u0004 \u0005[מדוע]\u0006 ישחררו אותה בעל כרחו? \u0003נקיט מרגניתא בידיה יהיבנא ליה חספא\u0004 \u0005[\u0006הוא \u0005מחזיק מרגלית בידו\u0006 ו\u0005אנו נותנים לו\u0006 במקומה \u0005חרס]?\u0006 שהרי עכשיו אין אפשרות לגבות בשטר, ונותנים לו שטר זה תמורת ההחזקה בה עצמה.","\u0003אלא אמר אביי: בעל כרחיה\u0004 \u0005[בעל כרחו]\u0006 של ה\u0003אב, משום פגם משפחה,\u0004 שכופים את האב לדחוק עצמו ביותר ולפדותה, משום שפגם הוא למשפחה שאחת מבנותיה היא אמה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003עבד עברי נמי נכפינהו\u0004 \u0005[נכפה אותם]\u0006 \u0003לבני משפחה\u0004 שיפדוהו \u0003משום פגם משפחה!\u0004 ומשיבים: יש לחשוש כי \u0003הדר אזיל ומזבין נפשיה\u0004 \u0005[יחזור ילך וימכור עצמו].\u0006","ומקשים: \u0003הכא נמי הדר אזיל ומזבין לה\u0004 \u0005[כאן\u0006 באמה \u0005גם כן\u0006 האב \u0005יחזור ילך וימכור אותה]\u0006 שוב לאמה, ויקבל שוב כסף עבורה! ומשיבים: \u0003הא קתני\u0004 \u0005[הרי שנה]:\u0006 \u0003אינה נמכרת ונשנית. ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מוכר\u0004 (כלומר, מוסר ומקבל קידושין) \u0003אדם את בתו\u0004 קטנה \u0003לאישות ושונה\u0004 (וחוזר) ומקדשה אם נתגרשה או נתאלמנה, וכן מוכרה \u0003לשפחות ושונה,\u0004 וכן מוסרה \u0003לאישות אחר\u0004 שמכרה ל\u0003שפחות, אבל לא\u0004 יכול למוכרה \u0003לשפחות אחר אישות. ר' שמעון אומר: כשם שאין אדם מוכר את בתו לשפחות אחר אישות, כך אין אדם מוכר את בתו לשפחות אחר שפחות. ו\u0004מעירים כי דבר זה הוא שנוי","\u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על הכתוב \u0003\"\u0004לעם נכרי לא ימשול למכרה \u0003בבגדו בה\"\u0004 (שמות כא, ח)"],["\u0003כיון שפירש\u0004 האדון \u0003טליתו\u0004 (\"בגדו\") \u0003עליה,\u0004 כלומר, שייעד אותה לו לאשה — \u0003שוב אין רשאי\u0004 האב \u0003למוכרה,\u0004 אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר: \"בבגדו בה\"\u0004 הוא מלשון בגידה \u0003כיון שבגד בה\u0004 האב ומכרה פעם אחת — \u0003שוב אין רשאי למוכרה.\u0004","שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, הם \u0005חלוקים]?\u0006 ומסבירים, \u0003ר' אליעזר סבר: יש אם למסורת,\u0004 כלומר, סומכים על הכתיב בלבד וכאילו היה הניקוד \"בבגדו\", ולכן הוא אומר שאין שפחות אחר שפחות, \u0003ור' עקיבא סבר יש אם למקרא\u0004 וכיון שקוראים \"בבגדו\" הריהו מלשון בגד, \u0003ור' שמעון סבר יש אם למקרא ולמסורת\u0004 גם יחד ולכן אמר שאין שפחות לא אחר אישות ולא אחר שפחות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה בר אבוה: יעוד\u0004 שמייעד האדון את האמה להיות אשתו האם \u0003נישואין\u0004 הוא \u0003עושה, או אירוסין\u0004 בלבד \u0003עושה? נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 הבדל למעשה לענין \u0003ליורשה,\u0004 האם בעלה יורש אותה כנשואה, \u0003ו\u0004חייב \u0003ליטמא לה\u0004 במותה אם הוא כהן, \u0003ולהפר נדריה\u0004 לבדו, בלא האב, כאשה נשואה. ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: מה שנאמר \u0003\"בבגדו בה\"\u0004 — כוונת הדברים: \u0003כיון שפירש טליתו עליה שוב אינו רשאי למוכרה.\u0004 ונדייק מכאן: \u0003זבוני\u0004 \u0005[למכור]\u0006 \u0003הוא דלא מזבין לה\u0004 \u0005[שאינו\u0006 יכול אביה \u0005למכור אותה]\u0006 עוד, \u0003הא יעודי מייעד לה\u0004 \u0005[הרי לייעד מייעד אותה]\u0006 האב לאחר, כשמת או גירשה הבעל הראשון, \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003נישואין עושה\u0004 הייעוד, \u0003כיון\u0004 ש\u0003נישאת\u0004 הרי \u0003שוב אין לאביה רשות בה! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי ייעוד \u0003אירוסין\u0004 הוא \u0003עושה.\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לדחות ולומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא זו \u0003בקידושין דעלמא\u0004 \u0005[בכלל,\u0006 סתם\u0005]\u0006 של בתו \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 ולא במוכר בתו לאמה. \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003כיון שמסרה\u0004 (שקידשה) \u0003אביה למי שנתחייב בשארה כסותה ועונתה\u0004 — \u0003שוב אין יכול\u0004 הוא \u0003למוכרה,\u0004 ואין מכאן הוכחה לענייננו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 האב \u0003אין מוכרה\u0004 את בתו לשפחה \u0003לקרובים,\u0004 כלומר, לאלה שאסורים בה משום ערוה, לפי שאינם יכולים לקיים בה מצוות ייעוד. \u0003משום ר' אליעזר אמרו: מוכרה\u0004 אף \u0003לקרובים,\u0004 שכיון שאין הייעוד אלא אפשרות בלבד, אין הוא מעכב כשלא יוכל לעשותו. \u0003ושוין שמוכרה\u0004 אף שהיא \u0003אלמנה לכהן גדול,\u0004 או \u0003גרושה וחלוצה לכהן הדיוט,\u0004 שאף על פי שהם אסורים בה, מכל מקום קידושיהם תופסים בה, כך שאין הייעוד בלתי אפשרי לחלוטין.","ונברר: \u0003האי אלמנה היכי דמי\u0004 \u0005[אלמנה זו\u0006 שהזכרנו \u0005כיצד היתה בדיוק]\u0006 \u0003אילימא דקדיש נפשה\u0004 \u0005[אם תאמר ש\u0006היא \u0005קידשה\u0006 את \u0005עצמה]\u0006 בהיותה קטנה ומת בעלה, וכי \u0003אלמנה קרי לה\u0004 \u0005[קורא אותה]?\u0006 הרי אין ממש בקידושין אלה ואינה נחשבת בכך אשתו. \u0003ואלא\u0004 צריך לומר ש\u0003קדשה אביה\u0004 ונתאלמנה. אולם אז \u0003מי מצי מזבין לה\u0004 \u0005[האם\u0006 הוא \u0005יכול\u0006 הוא \u0005למכור אותה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 אמרנו ש\u0003אין אדם מוכר את בתו לשפחות אחר אישות\u0004 (אחר שהיתה כבר נשואה).","\u0003ואמר רב עמרם אמר ר' יצחק: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003ב\u0004אלמנה מ\u0003קדושי יעוד, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי בר' יהודה\u0004 ש\u0003אמר: מעות הראשונות\u0004 שקיבל האב עבור בתו \u0003לאו לקידושין ניתנו\u0004 אלא כשכר עבדותה בלבד, ואם רוצה הוא לייעד, צריך הוא לקדש אותה בכסף אחר שנותן לה. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שהייעוד \u0003נישואין עושה, כיון שנישאת שוב אין לאביה רשות בה\u0004 וכיצד מכרה לאחר מות בעלה פעם נוספת!","ומקשים לצד שני; \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, שהייעוד \u0003אירוסין עושה\u0004 — אם כן, מדוע נאמר שם: \u0003ושוין שמוכרה?! הא\u0004 \u0005[הרי]\u0006 \u0003אין אדם מוכר את בתו לשפחות אחר אישות\u0004 ואפילו אחרי קידושין! \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]:\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003אירוסין דידה\u0004 \u0005[שלה]\u0006 \u0003מאירוסין\u0004 של \u0003אביה,\u0004 שאם היא נתארסה מעצמה — אין איסור על האב למוכרה, מה שאין כן כאשר האב מארס אותה. אם כן \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהייעוד \u0003נישואין עושה,\u0004 תוכל לומר כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003נישואין דידה\u0004 \u0005[שלה]\u0006 \u0003מנישואין\u0004 של \u0003אביה.\u0004","קושיה זו דוחים: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 כלומר, טענה זו מה טיבה? \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003אירוסין מאירוסין שאני\u0004 \u0005[שונים],\u0006 לפי שיש להבדיל בין אירוסין סתם שהם מדעת האב לאירוסין שבדרך ייעוד שהם מדעת האדון, ולאחר אירוסין כאלה עדיין יכול האב למוכרה שנית. \u0003אלא נישואין מנישואין,\u0004 לאחר שכבר היו נישואין של ממש, ויצאה לגמרי מרשות אביה"],["\u0003מי שאני\u0004 \u0005[האם משנה\u0006 הדבר\u0005]?\u0006","ושואלים: \u0003ול\u0004דעת \u0003רב נחמן בר יצחק\u0004 ש\u0003אמר\u0004 כי \u0003אפילו ל\u0004דעת \u0003ר' יוסי בר' יהודה מעות הראשונות לקידושין ניתנו, במאי מוקים לה\u0004 \u0005[במה\u0006 באיזו שיטה הוא \u0005מעמיד אותה]\u0006 ברייתא המתירה לאב למכור את בתו האלמנה? והרי אין אדם מוכר את בתו לשפחות אחר שמסרה לאישות! ומסבירים: \u0003מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003כ\u0004דעת \u0003ר' אליעזר\u0004 ש\u0003אמר: לשפחות אחר שפחות הוא דלא מצי מזבין לה\u0004 \u0005[שאינו יכול למכור אותה]\u0006 \u0003אבל לשפחות אחר אישות\u0004 — \u0003מצי מזבין לה\u0004 \u0005[יכול למכור אותה].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ריש לקיש: מהו שמייעד אדם\u0004 אמה עבריה \u0003לבנו קטן?\u0004 וצדדי השאלה: האם מן הכתוב \"לבנו ייעדנה\" (שמות כא, ט) נלמד \u0003\"בנו\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 וכוונתה \u0003בנו כל דהו\u0004 \u0005[כל שהוא]\u0006 אף שאינו ראוי עתה לנישואין, \u0003או דילמא\u0004 \u0005[שמא]\u0006 הכוונה \u0003בנו דומיא דידיה\u0004 \u0005[הדומה לו]:\u0006 \u0003מה הוא גדול\u0004 — \u0003אף בנו גדול?\u0004","\u0003אמר ר' זירא תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: את האמור בתורה \"ואיש אשר ינאף את אשת איש... מות יומת הנואף והנואפת\" (ויקרא כ, י) דרשו: \u0003\"איש\"\u0004 — \u0003פרט לקטן\u0004 שנאף. \u0003\"אשר ינאף את אשת איש\"\u0004 — \u0003פרט לאשת קטן,\u0004 משום שאין נישואי קטן נחשבים, ואם נשא אשה אינה נידונה כאשת איש. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003מייעד\u0004 האב אשה לבנו הקטן ודין הייעוד כאירוסין או כנישואין — \u0003אם כן מצינו אישות לקטן\u0004 — נמצא שיש נישואין אפילו בקטן.","על ראיה זו מקשים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, שהאב \u0003אינו מייעד\u0004 לבנו הקטן — אם כן \u0003אמאי קא מעט ליה קרא\u0004 \u0005[מדוע ממעט אותו הכתוב]\u0006 שאם אין כל מקרה שיש תוקף לנישואי קטן לשם מה צריך מיעוט מיוחד בכתוב? ולהיפך, \u0003תיפשוט מינה\u0004 \u0005[תפתור,\u0006 תסיק \u0005מכאן]\u0006 ש\u0003מייעד. אמר רב אשי:\u0004 אפשר לומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 הפסוק הממעט אשת קטן מדובר \u0003ביבם בן תשע שנים ויום אחד הבא על יבמתו\u0004 שביאתו נחשבת לביאה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006","\u0003דמדאורייתא חזיא ליה\u0004 \u0005[שמדין תורה ראויה\u0006 היא \u0005לו],\u0006 שהרי לא נאמר בדין ייבום בן כמה צריך להיות היבם, וכיון שביאת בן תשע שנים ויום אחד נחשבת לביאה, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דמדאורייתא חזיא ליה\u0004 \u0005[שמן התורה ראויה\u0006 היא \u0005לו]\u0006 \u0003וביאתו ביאה\u0004 ואם כן יקנה אותה ותיחשב כאשתו לכל דבר, ו\u0003הבא עליה מתחייב ב\u0004איסור \u0003אשת איש,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שבכל זאת אינה נחשבת כאשת איש ממש.","ושואלים: בסופו של דבר \u0003מאי הוי עלה\u0004 \u0005[מה דנו, אמרו עליה]\u0006 על בעיה זו לגבי ייעוד לבן קטן? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ש\u0003אמר ר' אייבו אמר ר' ינאי: אין יעוד אלא בגדול\u0004 (מבוגר), \u0003אין יעוד אלא מדעת.\u0004 שואלים: \u0003תרתי\u0004 \u0005[שתי]\u0006 הלכות בענין זה למה לי? שכיון שאמר שאין ייעוד אלא מדעת ממילא מובן שאין ייעוד אלא בגדול, שהרי קטן נחשב כמי שאינו בן־דעת. ומשיבים: יש לומר כי בדרך של \u0003\"מה טעם\" קאמר\u0004 \u0005[אומר]\u0006 ויש כאן דין וטעמו; \u0003מה טעם\u0004 אמרנו ש\u0003אין יעוד אלא בגדול\u0004 — \u0003לפי שאין יעוד אלא מדעת.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מדעת\u0004 שאמרנו — \u0003מדעת דידה\u0004 \u0005[מדעתה שלה].\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אביי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו:\u0004 מה שנאמר \u0003\"אשר לא יעדה\"\u0004 (שמות כא, ח) — \u0003מלמד שצריך ליעדה\u0004 (להודיע לה).","\u0003הוא תני לה\u0004 \u0005[הוא שנה אותה,\u0006 את הברייתא הזו\u0005],\u0006 \u0003והוא אמר לה\u0004 \u0005[\u0006פירש \u0005אותה]:\u0006 מדובר כאן \u0003בקידושי יעוד, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי בר' יהודה\u0004 ש\u0003אמר: מעות הראשונות\u0004 שנתן האדון לאב \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לקידושין ניתנ\u0004 \u0003ו\u0004ומשום כך צריך לעשות עוד מעשה קידושין, מדעתה. \u0003רב נחמן בר יצחק אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שגם הוא סבור כי מעות הראשונות \u0003לקידושין ניתנו, שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 \u0003\"יעדה\"\u0004 ולשון מיוחדת זו רומזת שיהא הדבר לדעתה.","כיון שהוזכרה כמה פעמים דעת ר' יוסי בר' יהודה שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 המקור שבו נזכרת שיטה זו של \u0003ר' יוסי בר' יהודה?\u0004 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בפסוק \u0003\"\u0004אשר לא \u0003יעדה, והפדה\"\u0004 (שם) הוקשו ייעוד ופדיון, ולמדים מן ההיקש כי אין יעוד אלא כאשר יש אפשרות של פדיה, ולכן אם היא בסוף זמן עבדותה \u0003צריך שיהא שהות ביום\u0004 שמייעד אותה \u0003כדי פדייה,\u0004 שיישאר מזמן עבודתה כדי שיעור שאפשר לפדות, שאם נשאר רק מעט זמן (פחות מכדי שווה פרוטה) אי אפשר לפדותה.","\u0003מכאן אמר ר' יוסי בר' יהודה: אם יש שהות ביום כדי לעשות\u0004 (לעבוד) \u0003עמו שוה פרוטה\u0004 — \u0003מקודשת,\u0004 שבסכום זה שהיא חייבת לו בעבודה (שהוא שווה לפרוטה) הוא מקדש אותה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת. אלמא קסבר\u0004 \u0005[הרי שהוא סבור]\u0006 ש\u0003מעות הראשונות\u0004 שנותן האדון בקנייתה — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לקידושין ניתנו.\u0004","\u0003רב נחמן בר יצחק אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמעות ראשונות \u0003לקידושין ניתנו, שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 בסמיכות \u0003\"\u0004יעדה \u0003והפדה\"\u0004 שגזירת הכתוב היא שיהא היעוד בזמן שיש בו כדי פדיון.","\u0003אמר רבא אמר רב נחמן: אומר אדם לבתו קטנה \"צאי וקבלי קידושיך\",\u0004 וכשהיא מקבלת את הקידושין, אף שהיא עצמה אינה בת־דעת, הרי היא נעשית כשלוחת אביה לענין קידושי עצמה. ומניין — \u0003מ\u0004דברי \u0003ר' יוסי בר' יהודה;\u0004","\u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003אמר ר' יוסי בר' יהודה מעות הראשונות לאו\u0004 \u0005[לא]\u0006 \u0003לקידושין ניתנו, וכי\u0004 \u0005[וכאשר]\u0006 \u0003משייר בה\u0004 זמן עבודה בשיעור של \u0003שוה פרוטה הוו קידושי\u0004 \u0005[הריהם קידושין]\u0006 כשרוצה לייעד אותה — נמצא שכאשר האב מכר את בתו, עשה אותה כשליחה לקבל קידושין (אם ירצה האדון לייעדה לו), ובזמן הייעוד עצמו האב אינו מקבל דבר, אלא הבת היא המקבלת שווה כסף של עבודתה כקידושין. \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 שיכולה קטנה לקבל קידושיה מרצון אביה.","\u0003ואמר רבא אמר רב נחמן: המקדש במלוה שיש עליה משכון\u0004 שמוחל לה על החוב שחייבת לו ומחזיר לה את המשכון שנתנה לו — \u0003מקודשת,\u0004 ודבר זה נלמד \u0003מ\u0004דברי \u0003ר' יוסי בר' יהודה.\u0004 כיצד, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר ר' יוסי בר' יהודה\u0004 כי \u0003מעות הראשונות לאו\u0004 \u0005[לא]\u0006 \u0003לקידושין ניתנו,\u0004 ואם כן \u0003האי\u0004 \u0005[זו]\u0006 חובת הבת לעבוד כמו \u0003הלואה היא\u0004 שאינה ממון ממש אלא התחייבות בלבד, \u0003והיא גופא\u0004 \u0005[עצמה]\u0006 \u0003משכון היא,\u0004 שהרי גופה הוא האחריות למילוי התחייבות = הלוואה זו,"],["\u0003וכי משייר\u0004 \u0005[וכאשר משאיר]\u0006 \u0003בה,\u0004 בעבודה, \u0003שוה פרוטה ומייעד\u0004 אותה — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 ונמצא שמקדש אותה בהלוואה (בחובתה לעבוד) שיש עליה משכון, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בכל מקרה כגון זה \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 שהלוואה שיש עליה משכון אפשר לקדש בה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד מצות יעוד? אומר לה בפני שנים \"הרי את מקודשת לי\",\u0004 או \u0003\"הרי את מאורסת לי\" אפילו\u0004 אמר לה כן \u0003בסוף שש\u0004 השנים של עבודתה, \u0003ואפילו סמוך לשקיעת החמה\u0004 של היום האחרון לעבודתה. \u0003ו\u0004לאחר שיעדה \u0003נוהג בה מנהג אישות ואינו נוהג בה\u0004 עוד \u0003מנהג שפחות. ר' יוסי בר' יהודה אומר: אם יש שהות ביום כדי לעשות\u0004 (לעבוד) \u0003עמו\u0004 עבודה בשווי \u0003שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004","\u0003משל לאומר לאשה \"התקדשי לי מעכשיו לאחר שלשים יום\" ובא אחר וקידשה בתוך שלשים יום\u0004 — \u0003שמקודשת לראשון.\u0004 ומבררים: \u0003משל\u0004 זה \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 הוא נאמר?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משל ל\u0004דברי \u0003ר' יוסי בר' יהודה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 אמר: \u0003אם יש שהות ביום כדי לעשות עמו שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא!\u0004","נמצא שלדעת ר' יוסי בר' יהודה אינה נחשבת כמקודשת על תנאי מתחילת קנייתה (\"מעכשיו\") אלא רק מזמן שייעדה ומשום כך צריך שישאר זמן לעבודה שיש בה שווה פרוטה ובשווי זה הריהי מתקדשת. \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: משל\u0004 זה הוא \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 האומרים שמזמן קנייתה הרי זה כאילו קידש מעכשיו על תנאי שבמשך שש שנים כשירצה האדון בה תהיה מקודשת למפרע. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, ואין צורך להסביר את הדבר!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 לאב בזמן הקניה שהיא מקודשת לו \u0003\"מעכשיו\",\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשל שדווקא אם אמר \"מעכשיו\" מקודשת.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003המוכר את בתו, ו\u0004אחר כך \u0003הלך וקידשה לאחר\u0004 — הרי זה \u0003שיחק באדון,\u0004 שלמרות שמכרה לו הוא מוציא אותה מרשות האדון, ונמצא שמצחק בו. \u0003ומקודשת לשני,\u0004 אלו \u0003דברי ר' יוסי בר' יהודה. וחכמים אומרים: אם רצה\u0004 האדון \u0003לייעד\u0004 — \u0003מייעד\u0004 ובטלים קידושי השני.","\u0003משל לאומר לאשה \"הרי את מקודשת לי לאחר שלשים יום\"\u0004 (ולא אמר \"מעכשיו\") \u0003ובא אחר וקידשה בתוך שלשים יום ש\u0004היא \u0003מקודשת לשני,\u0004 שהרי בתוך שלושים הימים הללו לא היתה מקודשת לראשון, וחלים קידושי השני. ושואלים: \u0003משל\u0004 זה \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 הוא?","\u0003אילימא לרבנן\u0004 \u0005[אם תאמר ל\u0006דעת \u0005חכמים]\u0006 \u0003האמרי רבנן\u0004 \u0005[הרי אומרים חכמים]\u0006 ש\u0003אם רצה\u0004 האדון \u0003לייעד מייעד\u0004 ואין חלים קידושי שני!","\u0003אלא אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא:\u0004 \u0003משל\u0004 זה הוא \u0003ל\u0004דעת \u0003ר' יוסי בר' יהודה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו שכן הוא!","ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא אמר לה\u0004 בשעת קנייה \u0003\"לאחר שלשים יום\"\u0004 והרי זה כאילו קידשה מעכשיו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שתחילת הייעוד היא רק משעה שירצה לייעדה בפירוש ולא מזמן הקנייה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003המוכר את בתו, ופסק\u0004 (קבע, הסכים) עם הקונה \u0003על מנת שלא לייעד\u0004 אותה — \u0003נתקיים התנאי,\u0004 כלומר, מקיימים את התנאי כמות שהוא, אלו \u0003דברי ר' מאיר. וחכמים אומרים: אם רצה\u0004 האדון \u0003לייעד\u0004 אותה — \u0003מייעד, מפני שהתנה על מה שכתוב בתורה,\u0004 שהרי תנאי זה הוא נגד האמור בתורה שיש באמה דין ייעוד \u0003וכל המתנה על מה שכתוב בתורה\u0004 — \u0003תנאו בטל.\u0004","ושואלים: \u0003ו\u0004האם \u0003ל\u0004דעת \u0003ר' מאיר\u0004 בכגון זה \u0003תנאו קיים? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי על מנת שאין לך עלי\u0004 (שאין אני מחוייב לך) ב\u0003שאר\u0004 (מזונות) \u0003כסות ועונה\"\u0004 — \u0003הרי זו מקודשת, ותנאו בטל,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בדבר שבממון,\u0004 כגון שאר וכסות — \u0003תנאו קיים.\u0004 הרי שר' מאיר סבור שאינו יכול להתנות כלל על הכתוב בתורה!","\u0003אמר חזקיה: שאני הכא\u0004 \u0005[שונה כאן]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 והדגיש \u0003\"\u0004וכי ימכור איש את בתו \u0003לאמה\"\u0004 (שמות כא, ז), לומר: \u0003פעמים שאינו מוכרה אלא לאמה בלבד,\u0004 ולא לשם נישואין. משמע שאין ייעוד האמה העבריה בגדר חובה מן התורה, אלא רק רשות, ולכן יכול לבטלם על ידי תנאי, ואין בכך משום מתנה על מה שכתוב בתורה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"לאמה\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003האי מיבעי להו לכדתניא\u0004 \u0005[\u0006כתוב \u0005זה צריכים הם לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"לאמה\"\u0004 — הרי זה \u0003מלמד שמוכרה לפסולים\u0004 כגון לממזר, שאסור לו לשאת אותה.","ושואלים: \u0003ו\u0004לכאורה \u0003הלא דין הוא\u0004 שמובן מן הסברה, ואין הדבר צריך לימוד מן הכתוב, שהרי \u0003אם\u0004 אביה \u0003מקדשה לפסולים,\u0004 שהלא קידושין לפסולים (כגון חייבי לאוין) תופסים, אף שאינם מותרים — וכי \u0003לא ימכרנה לפסולים?\u0004 ומשיבים: יש צורך בלימוד מיוחד שכן \u0003מה למקדשה לפסולים\u0004 — \u0003שכן אדם מקדש את בתו\u0004 אפילו \u0003כשהיא נערה,\u0004 וכי אפשר ללמוד מזה שגם \u0003ימכרנה לפסולים?\u0004 — \u0003ש\u0004הרי \u0003אין אדם מוכר את בתו כשהיא נערה\u0004 ונמצא שגדול כוח האב בקידושין, יותר מאשר במכירה. לכן \u0003תלמוד לומר\u0004 מן הכתוב: \u0003\"לאמה\"\u0004 — \u0003מלמד ש\u0004אכן יכול ל\u0003מוכרה לפסולין.\u0004","\u0003ר' אליעזר אומר: אם ללמד שמוכרה לפסולין\u0004 אינו צריך — \u0003הרי כבר נאמר \"אם רעה בעיני אדניה\u0004 אשר לו יעדה\u0003\"\u0004 (שם כא, ח), לומר \u0003שרעה בנישואיה,\u0004 שהנישואין האלה יש בהם איסור, ומכל מקום המכירה קיימת. אם כן \u0003מה תלמוד לומר \"לאמה\"\u0004 — \u0003מלמד שמוכרה\u0004"],["\u0003לקרובים\u0004 (כגון לאביו) אף שהיא אסורה עליהם משום ערוה.","ולכאורה \u0003והלא דין\u0004 (סברה) \u0003הוא: אם מוכרה לפסולין\u0004 לנישואין \u0003לא ימכרנה לקרובים?\u0004 ויש לדחות: \u0003מה למוכרה לפסולין, שאם רצה לייעד\u0004 — \u0003מייעד,\u0004 שאף שאסור לשאתה, מכל מקום תופסים בה קידושין, אבל לא \u0003ימכרנה לקרובים, שאם רצה לייעד\u0004 — \u0003אינו מייעד,\u0004 שהרי אין קידושין תופסים בה מחמת הקירבה כלל, על כן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לאמה\"\u0004 — \u0003מלמד שמוכרה לקרובים.\u0004","ושואלים: \u0003ור' מאיר\u0004 הלומד מ\"לאמה\" שיכול להתנות שלא לייעד, מהיכן למד הוא הלכות אלה? ומשיבים: דין זה שמוכרה \u0003לפסולין נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד, \u0005לו]\u0006 \u0003מהיכא דנפקא ליה\u0004 \u0005[ממקום שיצאה,\u0006 נלמדה, \u0005לו]\u0006 \u0003לר' אליעזר\u0004 — (\"אם רעה בעיני אדוניה\"). ואילו \u0003בקרובים סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרבנן דאמרי\u0004 \u0005[כ\u0006דעת \u0005חכמים שאומרים]\u0006 \u0003אין מוכרה לקרובים.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003מוכרה\u0004 את הבת \u0003לאביו, ואין מוכרה לבנו. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מוכרה לא לאביו ולא לבנו.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 הברייתא האומרת ש\u0003אינו מוכרה לא לאביו ולא לבנו\u0004 — הרי היא \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 שאינו יכול למכור אותה לקרובים שאסורים לשאת אותה. \u0003אלא\u0004 אותה ברייתא שנאמר בה ש\u0003מוכרה לאביו ואין מוכרה לבנו, כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 היא?","\u0003לא כרבנן\u0004 \u0005[לא כ\u0006דעת \u0005חכמים]\u0006 האוסרים מכירה לכל קרוב \u0003ולא כ\u0004דעת \u0003ר' אליעזר\u0004 המתיר לקרובים! ומשיבים: \u0003לעולם כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים],\u0006 ואף שהם אומרים שאין מוכרה לקרובים, מכל מקום \u0003מודו רבנן\u0004 \u0005[מודים חכמים]\u0006 שמותר למוכרה \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003צד יעוד.\u0004 וכאן אף על פי שאביו אינו רשאי לשאת אותה, מכל מקום יכול הוא לייעד אותה לבנו האחר שהוא אחיו של אבי הנערה ודודה של הנערה עצמה ומותר בה. וכיון שיש צד ייעוד בכך לכן המכירה מותרת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 לפרש את הנאמר בעבד עברי \u0003\"אם בגפו יבא בגפו יצא\"\u0004 (שמות כא, ג), לומר \u0003בגופו נכנס בגופו יצא. ר' אליעזר בן יעקב אומר,\u0004 כך יש לומר: \u0003יחידי נכנס יחידי יצא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש השיטה הראשונה \u0003\"בגפו\"\u0004 — \u0003בגופו נכנס בגופו יצא? אמר רבא: לומר שאינו יוצא בראשי אברים כעבד\u0004 כנעני, שכמו שנכנס בגופו כך הוא יוצא בגופו אבל אינו יוצא על ידי פגם שנעשה בגופו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הדין \u0003ההוא\u0004 נלמד ממקום אחר — \u0003מ\"לא תצא כצאת העבדים\"\u0004 (שם ז) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006","משיב רבא: \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003ניתיב ליה\u0004 \u0005[ישיב לו]\u0006 את \u0003דמי עיניה\u0004 \u0005[עינו]\u0006 שהוציא לו \u0003וניפוק\u0004 \u0005[וייצא\u0006 לחופשי\u0005],\u0006 והייתי מפרש שמה שנאמר בשפחה שלא תצא כצאת העבדים אין כוונתו שאינה יוצאה כלל בראשי אברים, אלא שבניגוד לעבד כנעני היא מקבלת גם פיצוי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק השני שאין זה כך, שאף שצריך לשלם לה דמי עינה, מכל מקום אינה משתחררת על ידי כך.","\u0003ר' אליעזר בן יעקב אומר: יחידי נכנס יחידי יצא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003יחידי יצא? אמר רב נחמן בר יצחק הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003יש לו\u0004 לעבד העברי \u0003אשה ובנים\u0004 כשנכנס — \u0003רבו\u0004 (אדוניו) \u0003מוסר לו שפחה כנענית,\u0004 ואם \u0003אין לו אשה ובנים\u0004 (\"יחידי נכנס\") — \u0003אין רבו מוסר לו שפחה כנענית\u0004 (\"יחידי יצא\").","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נמכר\u0004 העבד לאדוניו \u0003במנה\u0004 (מאה דינר), \u0003והשביח\u0004 במשך הזמן \u0003ועמד\u0004 ערכו \u0003על מאתים\u0004 דינר, \u0003מנין שאין מחשבין לו\u0004 אם רוצה לפדות את עצמו, ולשלם לאדון עבור השנים שנותרו לו לעבוד \u0003אלא\u0004 לפי חשבון של \u0003מנה\u0004 כדמי המכירה — \u0003שנאמר: \"מכסף מקנתו\"\u0004 (ויקרא כה, נא).","אם \u0003נמכר במאתים והכסיף\u0004 (פחת ערכו) \u0003ועמד על מנה, מנין שאין מחשבין לו\u0004 בפדיונו \u0003אלא\u0004 לפי חשבון של \u0003מנה\u0004 — \u0003תלמוד לומר: \"כפי שניו\u0004 ישיב את גאולתו","\u0003\"\u0004(שם נב), כלומר, כפי ערכו בשנים שנותרו לו. \u0003אין לי אלא\u0004 דין זה ב\u0003עבד הנמכר לגוי, הואיל\u0004 והקילה התורה בפדיונו \u0003ונגאל\u0004 אף \u0003בקרובים\u0004 שמשלמים דמיו ומשחררים אותו, נמצא ש\u0003ידו\u0004 של הקונה \u0003על התחתונה\u0004 ובין בהשבחת ערכו ובין בהפחתת ערכו משלם העבד תמיד בשווי הנמוך יותר.","ואולם אם \u0003נמכר\u0004 העבד \u0003לישראל מנלן\u0004 \u0005[מניין לנו]\u0006 שגם כן נוהג בו דין זה? — \u0003תלמוד לומר: \"שכיר\" \"שכיר\" לגזירה שוה,\u0004 שנאמר בעבד עברי הנמכר לישראל: \"כשכיר כתושב יהיה עמך\" (ויקרא כה, מ) ובנמכר לגוי נאמר: \"כשכיר שנה בשנה יהיה עימו\" (שם נג), לומר שכדין הנמכר לגוי כך דין הנמכר לישראל לענין זה.","פעם אחת \u0003אמר אביי\u0004 כשהיתה דעתו בדוחה: \u0003הריני כבן עזאי בשוקי טבריא\u0004 (טבריה). כלומר, אני חריף ובקי כמוהו ומוכן לענות על כל שאלה. \u0003אמר ליה ההוא מרבנן\u0004 \u0005[אמר לו אחד החכמים]\u0006 \u0003לאביי\u0004 שאלה זו: \u0003מכדי הני קראי\u0004 \u0005[הרי אותם הכתובים]\u0006 שאמרנו \"כסף מקנתו\" \"וכפי שניו\" \u0003איכא למידרשינהו לקולא\u0004 \u0005[יש\u0006 מקום \u0005לדרוש אותם להקל],\u0006 כלומר, לחשוב לפי הסכום הקטן יותר, \u0003ואיכא למידרשינהו לחומרא\u0004 \u0005[ויש\u0006 מקום \u0005לדרוש אותם להחמיר]\u0006 ולומר שאם היה שווה יותר בשעת הקניה משלם ב\"כסף מקנתו\", ואם השביח בשעת הפדיון משלם \"כפי שניו\" כמה ששווה עכשיו. \u0003מאי חזית דדרשינהו לקולא, נידרשינהו לחומרא\u0004 \u0005[מה ראית שאתה דורש אותם להקל, נדרוש אותם להחמיר]?!\u0006","ענה לו אביי: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לדרוש או תם לחומרה. ומדוע? \u0003מדאקיל רחמנא לגביה\u0004 \u0005[מפני שהקילה התורה אצלו]\u0006 אצל העבד ודאגה לטובתו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"כי טוב לו עמך\"\u0004 (דברים טו, טז), הרי זה בא לומר: \u0003עמך\u0004 וכמותך יהיה העבד העברי, \u0003במאכל,\u0004 שכמו שאתה אוכל כך הוא אוכל, \u0003ועמך במשתה,\u0004 לומר","\u0003שלא תהא אתה אוכל פת נקיה והוא אוכל פת קיבר\u0004 (של קמח גס המעורב בסובין והוא גרוע יותר), או \u0003אתה שותה יין ישן\u0004 שהוא מובחר \u0003והוא שותה יין חדש, אתה ישן\u0004 בנוחות \u0003על גבי\u0004 מצע של \u0003מוכים\u0004 (סמרטוטים רכים) \u0003והוא ישן על גבי התבן. מכאן אמרו: כל הקונה עבד עברי כקונה אדון לעצמו,\u0004 שהרי הוא חייב לדאוג לו ולהשוות את תנאי חייו לתנאי חייו שלו.","ומקשים: \u0003ואימא הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה]\u0006 שמקילים בעבד העברי — הרי זה \u0003לענין אכילה ושתיה, כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליצטער ליה\u0004 \u0005[יצטער אצלו]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין פדיון נחמיר עליה\u0004 \u0005[עליו],\u0006 והטעם שיש להחמיר עליו — \u0003מ\u0004דברי \u0003ר' יוסי בר' חנינא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי בר' חנינא אומר: בא וראה כמה קשה אבקה של שביעית,\u0004 כלומר, מה קשה עונשו של אדם שמזלזל בקדושת שביעית, ולא רק באיסור העיקרי (עבודת אדמה) אלא אף באיסור קל (\"אבק\") שלה, שהוא האיסור לעשות מסחר בפירות שביעית. כיצד?","— \u0003אדם נושא ונותן\u0004 במסחר \u0003בפירות שביעית\u0004 — \u0003לסוף\u0004 הוא נעשה עני ונזקק עד ש\u0003מוכר את מטלטליו, שנאמר: \"בשנת היובל\u0004 הזאת \u0003תשבו איש אל אחזתו\"\u0004 (ויקרא כה, יג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך\"\u0004 (שם יד) — שכוונתו \u0003דבר הנקנה מיד ליד,\u0004 כלומר, מכירת מטלטלין. לומר שאם חטא בדבר הנוגע לשנת היובל או השמיטה סופו שנזקק למכור את רכושו.","\u0003לא הרגיש\u0004 שדבר זה בא לו כעונש, ולא עשה תשובה — \u0003לסוף מוכר את שדותיו, שנאמר\u0004 בסמוך לאלה: \u0003\"כי ימוך אחיך ומכר מאחזתו\"\u0004 (שם כה). \u0003לא באת לידו\u0004 ולא חזר בו \u0003עד שמוכר את ביתו, שנאמר:\u0004 \u0003\"\u0004ואיש \u0003כי ימכר בית מושב עיר חומה\"\u0004 (שם כט).","לפני שנוגעים בעיקר הדבר מבררים את הלשון: \u0003מאי שנא התם\u0004 \u0005[מה שונה שם]\u0006 במשפט הראשון ש\u0003אמר \"לא הרגיש\" ומאי שנא הכא\u0004 \u0005[ומה שונה כאן]\u0006 בהמשך ש\u0003אמר \"לא באת לידו\"?\u0004 ומשיבים שביטוי זה מלמדנו בדרך אגב כפי שאמר \u0003רב הונא.\u0004 ש\u0003אמר רב הונא: כיון שעבר אדם עבירה ושנה בה\u0004 — \u0003הותרה לו.\u0004 ומיד תוהים על הלשון: \u0003הותרה לו סלקא דעתך\u0004 \u0005[עולה על דעתך]!\u0006 וכי מותר לאדם לעבור עבירה בפעם השניה? \u0003אלא\u0004 הכוונה הותרה לו = בעיניו, ש\u0003נעשית לו כהיתר.\u0004 ולכן כשעבר בפעם השניה, אומרים \"לא הרגיש\", ובפעם השלישית ודאי אינו שב עד שעובר פעם נוספת.","וממשיכים בדברי הברייתא: \u0003לא באת לידו,\u0004 כלומר, שוב לא חזר בו מעבירה שעשה ילך עוניו ויגדל \u0003עד שמוכר את בתו\u0004 — \u0003שנאמר: \"וכי ימכר איש את בתו לאמה\"\u0004 (שמות כא, ז). ומעירים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003בתו לא כתיבא בהאי ענינא\u0004 \u0005[כתובה בענין זה]\u0006 אלא בספר שמות, מכל מקום \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003ניזבין אינש ברתיה\u0004 \u0005[שימכור אדם\u0006 את \u0005בתו]\u0006 \u0003ולא ניזיף בריביתא\u0004 \u0005[ילוה בריבית],\u0006 שהדבר גרוע יותר. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003ברתיה מגרעא ונפקא\u0004 \u0005[בתו\u0006 מפעם לפעם \u0005נגרע\u0006 החוב והיא \u0005יוצאת]\u0006 \u0003והא מוספא ואזלא\u0004 \u0005[וזו\u0006 הריבית \u0005מוסיפה והולכת].\u0006","וחוזרים שוב לענין דרשת המקראות בספר ויקרא: \u0003לא באת לידו\u0004 ולא חזר בו \u0003עד שלוה ברבית, שנאמר: \"וכי ימוך אחיך ומטה ידו עמך\"\u0004 (ויקרא כה, לה) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"אל תקח מאתו\u0004 נשך\u0003\"\u0004 (שם לו). \u0003לא באת לידו\u0004 — \u0003עד שמוכר את עצמו, שנאמר: \"וכי ימוך אחיך\u0004 עמך \u0003ונמכר לך\"\u0004 (שם לט).","וממשיכים: \u0003לא לך\u0004 לאדם מישראל בלבד הוא נמכר \u0003אלא\u0004 אף \u0003לגר\u0004 הוא נמכר \u0003שנאמר:\u0004 \"ונמכר \u0003לגר\u0004 תושב עמך\" (שם מז), \u0003ולא לגר צדק\u0004 בלבד הוא נמכר \u0003אלא לגר תושב\u0004 שלא התגייר ממש \u0003שנאמר \"גר תושב\".\u0004 ועל המשך הפסוק \"או לעקר משפחת גר\" דורשים \u0003\"משפחת גר\"\u0004 — \u0003זה גוי,\u0004 שיכול להגיע למצב שצריך להמכר לגוי. \u0003כשהוא אומר \"לעקר\u0004 משפחת גר \u0003\"\u0004"],["\u0003זה הנמכר לעבודה זרה עצמה\u0004 שצריך למכור את עצמו להיות שמש לעבודה זרה. ומדברי ברייתא זו יכולים ללמוד שאין אדם מוכר את עצמו לעבד אלא מפני שחטאיו גרמו לו, ושמא צריך להחמיר עליו לענין פדיון, שלא ייפדה בקלות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003התם, הא אהדריה קרא\u0004 \u0005[שם, הרי החזירו הכתוב]\u0006 כלומר, שמן המקרא רואים שבכל זאת דואגים לו לזה שנמכר לגוי להחזירו לישראל, \u0003דתני דבי\u0004 \u0005[ששנויה\u0006 ברייתא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל והלך זה\u0004 שמכר את עצמו לעבד \u0003ונעשה כומר לעבודה זרה, אימא\u0004 \u0005[אמור]:\u0006 \u0003לידחי\u0004 \u0005[נדחה,\u0006 נזרוק\u0005]\u0006 \u0003אבן אחר הנופל,\u0004 כלומר, כיון שהגיע לידי כך — לא נדאג לו יותר ונפקירנו — \u0003תלמוד לומר: \"אחרי נמכר גאלה תהיה לו אחד מאחיו יגאלנו\"\u0004 (ויקרא כה, מח).","ועדיין ממשיכים להקשות: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003\"גאלה תהיה לו\"\u0004 דווקא במקרה זה \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליטמע\u0004 \u0005[ייטמע\u0006 ויאבד\u0005]\u0006 \u0003בין הגוים, הא\u0004 \u0005[הרי]\u0006 \u0003לענין פדיון\u0004 ויציאה לחפשי \u0003נחמיר עליה\u0004 \u0005[עליו]\u0006 \u0003מ\u0004דברי \u0003ר' יוסי בר' חנינא\u0004 שנמכר לעבד בגלל העבירות שעבר עליהן!","\u0003אמר רב נחמן בר יצחק: תרי קראי כתיבי\u0004 \u0005[שני כתובים נאמרו]\u0006 בפדיונו של הנמכר לגוי: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אם עוד רבות בשנים\u0004... מכסף מקנתו\u0003\"\u0004 (שם נא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואם מעט נשאר בשנים\u0004... כפי שניו\u0003\"\u0004 (שם נב). ויש לשאול: \u0003וכי יש שנים מרובות ויש שנים מועטות?\u0004 והרי אינו עובד יותר משש שנים! \u0003אלא\u0004 כך הכוונה: אם \u0003נתרבה כספו\u0004 שמחירו עלה במשך השנים — פודים אותו לפי \u0003\"מכסף מקנתו\"\u0004 שהיה מועט, ואם \u0003נתמעט כספו,\u0004 שירד ערכו במשך השנים — דנים בו \u0003\"כפי שניו\"\u0004 ולא לפי מחירו הגבוה הקודם.","ושואלים: \u0003ואימא הכי קאמר\u0004 \u0005[ואמור\u0006 ש\u0005כך אמר]:\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003עבד תרי\u0004 \u0005[במקום שעבד שתי\u0006 שנים\u0005]\u0006 \u0003ופש ליה\u0004 \u0005[ונשארו לו]\u0006 עוד \u0003ארבע\u0004 (\"עוד רבות בשנים\") — \u0003ניתיב ליה\u0004 \u0005[ישיב לו]\u0006 לאדון דמי \u0003ארבע\u0004 שנים שחייב לו \u0003\"מכסף מקנתו\",\u0004 ואם \u0003עבד ארבע\u0004 שנים \u0003ופשו ליה תרתי\u0004 \u0005[ונשארו לו שתים]\u0006 (\"מעט נשאר בשנים\") \u0003ניתיב תרתי\u0004 \u0005[ישיב\u0006 דמי \u0005שתי\u0006 שנים\u0005]\u0006 \u0003\"כפי שניו\"?\u0004","ודוחים: \u0003אם כן נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"אם עוד רבות שנים\",\u0004 וכן \u0003\"אם מעט נשאר שנים\", מאי\u0004 \u0005[מה]\u0006 משמעות השינוי בלשון \u0003\"בשנים\"\u0004 — לומר שאם \u0003נתרבה כספו ב\u0004משך ה\u0003שנים\u0004 — דנים בו \u0003\"מכסף מקנתו\",\u0004 ואם \u0003נתמעט כספו ב\u0004משך ה\u0003שנים\u0004 — דנים בו \u0003\"כפי שניו\". אמר רב יוסף\u0004 כששמע את הדברים: \u0003דרשינהו\u0004 \u0005[דרש אותם]\u0006 \u0003רב נחמן בר יצחק להני קראי\u0004 \u0005[לכתובים אלה]\u0006 \u0003כסיני\u0004 שנראה שכיוון לאמיתה של תורה כפי שניתנה מהר סיני, שכל אחד מהדברים מתיישב יפה.","\u0003(סימן\u0004 לבעיות הבאות: \u0003עבד, בית, חצאין, בית עבד, קרובים). בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הונא בר חיננא מרב ששת: עבד עברי הנמכר לגוי,\u0004 האם \u0003נגאל לחצאין, או אינו נגאל לחצאין?\u0004 כלומר, האם אפשר לשלם רק חלק ממחירו ולהפחית משנות עבודתו, או לא?","וצדדי השאלה: האם \u0003\"גאלתו\" \"גאלתו\" משדה אחוזה גמר\u0004 \u0005[למד]\u0006 בגזירה שווה, ונאמר כך: \u0003מה שדה אחוזה אינו נגאל לחצאין\u0004 אלא או משלם הכל או שאינו גואל כלל — \u0003אף האי נמי\u0004 \u0005[זה\u0006 העבד \u0005גם כן]\u0006 \u0003אינו נגאל לחצאין. או דילמא\u0004 \u0005[שמא]\u0006 \u0003לקולא אמרינן\u0004 \u0005[להקל אנו אומרים]\u0006 שאינו נגאל לחצאין, \u0003לחומרא לא אמרינן\u0004 \u0005[להחמיר אין אנו אומרים]\u0006 שאינו נגאל?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אמרת התם\u0004 \u0005[\u0006האם \u0005לא אמרת שם]\u0006 בנמכר בגניבתו (לשלם מה שגנב) \"ו \u0003נמכר\"\u0004 (שמות כב, ב) כוונתו — \u0003כולו ולא חציו,\u0004 שאם שווה אלף וחייב בגניבתו חמש מאות אינו נמכר, \u0003הכי נמי\u0004 \u0005[כך\u0006 בנמכר לגוי \u0005גם כן]\u0006 \u0003\"נגאל\"\u0004 כוונתו \u0003כולו ולא חציו.\u0004","\u0003אמר אביי: אם תימצי לומר\u0004 \u0005[מוצא אתה לומר]\u0006 ש\u0003נגאל לחצאין\u0004 — \u0003משכחת לה לקולא ולחומרא\u0004 \u0005[מוצא אתה בה\u0006 צדדים \u0005להקל ולהחמיר];\u0006 כיצד? \u0003לקולא\u0004 \u0005[להקל]\u0006 יש בו צד זה: אם \u0003זבניה\u0004 \u0005[קנה אותו]\u0006 \u0003במאה, יהב ליה חמשין, פלגא דדמי\u0004 \u0005[נתן לו\u0006 הגואל \u0005חמישים,\u0006 שהם \u0005חצי דמיו],\u0006 \u0003ו\u0004אחר כך \u0003אשבח\u0004 \u0005[והשביח]\u0006 העבד \u0003וקם על מאתן\u0004 \u0005[ועומד\u0006 מחירו עכשיו \u0005על מאתיים];\u0006 \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003נגאל לחצאין,\u0004 הרי שנגאל כבר חציו, ואם כן \u0003יהיב ליה\u0004 \u0005[נותן לו]\u0006 \u0003מאה\u0004 שהם חצי דמיו \u0003ונפיק\u0004 \u0005[ויוצא],\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אין נגאל לחצאין\u0004 — \u0003יהיב ליה מאה וחמשין ונפיק\u0004 \u0005[נותן לו מאה וחמישים ויוצא]\u0006 שהרי מה ששילם לו קודם לא היה אלא כתשלום ראשון, ועכשיו מחירו מאתיים.","ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003נתרבה כספו\u0004 (עלה ערכו — דנים בו בכל מקרה \u0003\"מכסף מקנתו\"\u0004 כלומר כערכו בזמן הקניה אפילו כשהוא נמוך יותר! ומשיבים: עוסקים אנו במקרה \u0003כגון\u0004 שבתחילה \u0003אוקיר\u0004 \u0005[התייקר]\u0006 ונמכר במאתיים \u0003ו\u0004אחר כך \u0003זל\u0004 \u0005[והוזל]\u0006 מחירו למאה \u0003ו\u0004שוב \u0003אוקיר\u0004 \u0005[התייקר]\u0006 וחזר ערכו כמו שהיה בתחילה.","וממשיכים לבאר כיצד \u0003משכחת לה לחומרא\u0004 \u0005[מוצא אתה אותה להחמיר]\u0006 אם \u0003זבניה במאתן\u0004 \u0005[קנה אותו במאתיים]\u0006 \u0003יהיב\u0004 \u0005[נתן]\u0006 הגואל \u0003מאה, פלגי דדמי\u0004 \u0005[נתן\u0006 הגואל \u0005מאה,\u0006 שהם \u0005חצי דמיו],\u0006 \u0003ואיכסף וקם\u0004 \u0005[והתקלקל\u0006 ירד ערכו של העבד \u0005ועמד]\u0006 \u0003על מאה; אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהוא \u0003נגאל לחצאין\u0004 — \u0003יהיב ליה חמשין ונפיק\u0004 \u0005[נותן לו חמישים ויוצא],\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003אין נגאל לחצאין\u0004 לפיכך \u0003הנך\u0004 \u0005[אותם]\u0006 \u0003מאה\u0004 שנתן לו \u0003פקדו‍ן נינהו גביה\u0004 \u0005[הם אצלו]\u0006 \u0003יהיב להו ניהליה ונפיק\u0004 \u0005[נותן לו אותם\u0006 בשעת פדיון \u0005ויוצא],\u0006 ואינו צריך להוסיף שהרי עכשיו הוא שווה מאה.","שאלה אחרת בנושא דומה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הונא בר חיננא מרב ששת: המוכר בית בבתי ערי חומ\u0004 \u0003ה\u0004שיכול בעליהם לפדותם מיד הקונה רק במשך השנה הראשונה למכירתם, האם \u0003נגאל לחצאין, או אינו נגאל לחצאין?\u0004 ושאלה זו מבוססת על הספק בהבנת הכתוב: האם נאמר כי \u0003\"גאלתו\" \"גאלתו\" משדה אחוזה גמר\u0004 \u0005[למד]\u0006 בגזירה שווה, ונאמר: \u0003מה שדה אחוזה אינה נגאלת לחצאין\u0004 — \u0003אף האי נמי\u0004 \u0005[זה גם כן]\u0006 \u0003אינו נגאל לחצאין,\u0004","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר כך: \u0003היכא דגלי\u0004 \u0005[במקום שגילה\u0006 הכתוב במפורש שכך הדין\u0005]\u0006 — \u0003גלי\u0004 \u0005[גילה],\u0006 שהרי כך כתוב בגואל שדה אחוזה: \"והשיגה ידו ומצא כדי גאולתו\" (ויקרא כה, כו), כלומר, כל שוויו ולא חציו, \u0003היכא\u0004 \u0005[\u0006ו\u0005במקום]\u0006 ש\u0003לא גלי\u0004 — \u0003לא גלי\u0004 \u0005[גילה],\u0006 ויגאל לחצאין?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ממדרשו של\u0004 (מן המדרש שדרש) \u0003ר' שמעון נשמע\u0004 (נלמד) \u0003ש\u0004בבתי ערי חומה \u0003לוה וגואל, ו\u0004כן \u0003גואל לחצאין. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב במקדיש שדהו: \u0003\"\u0004ו\u0003אם גאל יגאל\"\u0004 (ויקרא כז, יט) — \u0003מלמד שלוה וגואל, וגואל לחצאין.\u0004","\u0003אמר ר' שמעון: מה טעם\u0004 הלכה זו בתורה — \u0003לפי שמצינו במוכר שדה אחוזה שיפה כחו שאם הגיע יובל ולא נגאלה חוזרת\u0004 האחוזה \u0003לבעליה ביובל\u0004 בלי שישלם, לפיכך \u0003הורע כחו\u0004 של המוכר \u0003שאינו לוה וגואל\u0004 אלא צריך שתשיג ידו מעצמו, \u0003ו\u0004אינו \u0003גואל לחצאין.\u0004","אבל \u0003מקדיש\u0004 את שדהו \u0003שהורע כחו, ש\u0004כן \u0003אם הגיע יובל ולא נגאלה\u0004 בינתיים, ומכרה הגיזבר לאחרים — \u0003יוצאה\u0004 האחוזה \u0003ל\u0004היות רכוש \u0003כהנים ביובל\u0004 ושוב אינה חוזרת לבעליה, \u0003יפה\u0004 הכתוב \u0003כחו, ש\u0004גם \u0003לוה וגואל ו\u0004גם \u0003גואל לחצאין.\u0004 הרי שכנגד חומרה שהחמירו בדין הקדש שאינו חוזר ביובל יש קולה כנגדה שלווה וגואל וגואל לחצאין.","ואם כן לפי סברה זו \u0003הא\u0004 \u0003י\u0004 \u0005[זה]\u0006 ה\u0003מוכר בית בבתי ערי חומה נמי\u0004 \u0005[גם כן]\u0006 \u0003הואיל והורע כחו, שאם מלאה לו שנה תמימה ולא נגאלה נחלט\u0004 (נשאר לצמיתות) הבית לקונה — לכן \u0003יפה כחו\u0004 מצד אחר \u0003שלוה וגואל, ו\u0004גם \u0003גואל לחצאין.\u0004","\u0003איתיביה\u0004 \u0005[היקשה לו]\u0006 רבא בר חיננא ממה ששנינו בברייתא: נאמר במקדיש שדהו \u0003\"אם גאל יגאל\"\u0004 (שם) — \u0003מלמד שלוה וגואל וגואל לחצאין.\u0004","\u0003שיכול\u0004 היית לומר: \u0003והלא דין הוא\u0004 אפשר ללמוד מסברה להיפך: \u0003ומה מוכר שדה אחוזה שיפה כחו, שאם הגיע יובל ולא נגאלה חוזרת לבעליה ביובל\u0004 — ובכל זאת \u0003הורע כחו שאין לוה וגואל ו\u0004אין \u0003גואל לחצאין, מקדיש\u0004 שדה \u0003שהורע כחו, שאם הגיע יובל ולא נגאלה יוצאה לכהנים ביובל\u0004 — \u0003אינו דין שהורע כחו שאין לוה וגואל ו\u0004אין \u0003גואל לחצאין?\u0004","ודוחים: \u0003מה למוכר שדה אחוזה שכן הורע כחו ליגאל מיד,\u0004 שאינו יכול לגאול מיד אלא צריך להמתין לפחות שנתיים, \u0003תאמר במקדיש שיפה כחו ליגאל מיד,\u0004 שאם יש לו כסף והוא רוצה לגאול — יכול לגאול מיד, ואם כן, אין פה קל וחומר.","ודוחים: \u0003מוכר בית בבתי ערי חומה יוכיח, שיפה כחו\u0004 שיכול \u0003ליגאל מיד\u0004 ובכל זאת \u0003אין לוה וגואל ו\u0004אין \u0003גואל לחצאין.\u0004 ועל כל פנים מדברי ברייתא מובן להיפך: שמוכר בית בבתי ערי חומה אין גואל לחצאין! השיב רב ששת: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006"],["\u0003הא\u0004 \u0005[\u0006ברייתא אחרונה \u0005זו\u0006\u0005]\u0006 היא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה לווה וגואל וגואל לחצאין היא כשיטת \u0003ר' שמעון.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 לגבי בתי ערי חומה: \u0003לוה וגואל וגואל לחצאין, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין לוה וגואל וגואל לחצאין\u0004 והרי זו סתירה בין ברייתות, ומשיבים באותו אופן: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — כשיטת \u0003רבנן, הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' שמעון\u0004","\u0003(סימן\u0004 לחכמים שהקשו את הקושיות הבאות ולמי שאלו אותן: \u0003חר\"ש חב\"ש זמ\"ן,\u0004 שהם רמז לשמות הבאים: רב א\u0003ח\u0004א בריה ד\u0003ר\u0004בא לרב א\u0003ש\u0004י, רב א\u0003ח\u0004א ס\u0003ב\u0004א לרב א\u0003ש\u0004י, מר \u0003ז\u0004וטרא בריה דרב \u0003מ\u0004רי לרבי\u0003נ\u0004א\u0003).\u0004","אמר ליה \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]\u0006 על השוואה זו שהוזכרה בברייתא: \u0003מה למוכר בית בבתי ערי חומה\u0004 — \u0003שכן הורע כחו ליגאל לעולם, תאמר במקדיש שיפה כחו ליגאל לעולם!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא סבא לרב אשי: משום דאיכא למימר\u0004 \u0005[שיש לומר]\u0006 \u0003ניהדר דינא\u0004 \u0005[יחזור,\u0006 ישוב, \u0005הדין]\u0006 ונלמדנו מצד אחר, \u0003תיתי\u0004 \u0005[שתבוא\u0006 תילמד\u0005]\u0006 הוכחה לדבר כשיטת הלימוד של \u0003במה הצד\u0004 השווה ביניהם. כיצד: \u0003מוכר שדה אחוזה יוכיח, שיפה כחו ליגאל לעולם ואין לוה וגואל ו\u0004אין \u0003גואל לחצאין\u0004 ואם תאמר: \u0003מה למוכר שדה אחוזה, שכן הורע כחו ליגאל מיד\u0004 — אולם \u0003מוכר בית בבתי ערי חומה יוכיח,\u0004 שעל אף שנגאל מיד, בכל זאת לווה ונגאל ונגאל לחצאין.","\u0003וחזר הדין,\u0004 שאפשר להפוך את הנימוקים לצד זה ולצד זה, ובסופו של דבר \u0003לא ראי זה כראי זה\u0004 אין דבר זה דומה לזה, \u0003הצד השוה שבהן\u0004 — \u0003שנגאלין, ואין לוה וגואל וגואל לחצאין, אף אני אביא מקדיש\u0004 — \u0003שנגאל, ואין לוה וגואל ו\u0004אין \u0003גואל לחצאין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]\u0006 על לימוד זה מן הצד השוה: \u0003מה להצד השוה שבהן\u0004 — \u0003שכן הורע כחם ליגאל בשנה שניה,\u0004 שבשנה שניה שניהם אינם יכולים להיגאל, \u0003תאמר במקדיש שיפה כחו ליגאל בשנה שניה!\u0004","\u0003אמר לו רבינא\u0004 תשובה לכך: \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003עבד עברי הנמכר לגוי יוכיח, שיפה כחו ליגאל בשנה שניה ו\u0004בכל זאת \u0003אין לוה וגואל ו\u0004אין \u0003גואל לחצאין.\u0004","ועוד מעין שאלות קודמות שנשאלו, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הונא בר חיננא מרב ששת: המוכר בית בבתי ערי חומה, נגאל לקרובים או\u0004 ש\u0003אין\u0004 הוא \u0003נגאל לקרובים\u0004 ורק המוכר בעצמו יכול לגאול? וצדדי השאלה: האם \u0003\"גאלתו\" \"גאלתו\" משדה אחוזה גמר\u0004 \u0005[למד]\u0006 בגזירה שווה ואפשר ללמוד ממנה: \u0003מה שדה אחוזה אינה נגאלת לחצאין ונגאלת לקרובים\u0004 — \u0003אף האי נמי\u0004 \u0005[אף זה,\u0006 בית בבתי ערי חומה \u0005גם כן]\u0006 \u0003אין נגאל לחצאין ונגאל לקרובים.\u0004","\u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כי כתיבא\u0004 \u0005[כאשר נאמרה]\u0006 לשון \u0003\"גאולה\"\u0004 בשדה אחוזה — \u0003ב\u0004ענין גאולה ל\u0003חצאין הוא דכתיב\u0004 \u0005[הוא שנאמרה],\u0006 אולם \u0003ב\u0004ענין \u0003קרובים לא כתיב\u0004 \u0005[נאמרה]\u0006 לשון גאולה ולענין זה אין למדים גזירה שווה לבתי ערי חומה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003: אינו נגאל\u0004 לקרובים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו שעל הכתוב \"ו \u0003בכל\u0004 ארץ אחוזתכם \u0003גאולה תתנו\u0004 לארץ\" (ויקרא כה, כד) דרשו: \u0003לרבות בתי\u0004 \u0003ם ועבד עברי, מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ב\"בתים\" ל\u0003בתי ערי חומה,\u0004 שאף הם נפדים על ידי קרובים? ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003בתי חצרים,\u0004 כלומר, בתים הנמצאים במקום שאינו מוקף חומה.","ומקשים: \u0003בתי חצרים בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"על שדה הארץ יחשב\"\u0004 (שם לא) כלומר, הריהם כשדה אחוזה ואין צריך בדרשה לרבותם! ומשיבים: הפסוק \u0003ההוא\u0004 (\"בכל... גאולה תתנו\") בא \u0003לקובעו חובה\u0004 לגאולת קרובים, \u0003ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' אליעזר.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שהכתוב במוכר שדה אחוזה \u0003\"וגאל את ממכר אחיו\"\u0004 (שם כה) — הרי זו \u0003רשות,\u0004 אם רוצה — גואל. \u0003אתה אומר רשות, או אינו אלא חובה? תלמוד לומר: \"ואיש כי לא יהיה לו גואל\"\u0004 (שם כו) \u0003וכי יש אדם בישראל שאין לו גואלים?\u0004 הרי כל אדם בישראל יש לו קרוב כלשהו עד יעקב אבינו. \u0003אלא\u0004 הכוונה ל\u0003זה שיש לו\u0004 אמנם גואל \u0003ואינו רוצה ליקח, שהרשות בידו.\u0004 אלו \u0003דברי ר' יהושע.\u0004","ואילו \u0003ר' אליעזר אומר:\u0004 מה שנאמר \u0003\"וגאל את ממכר אחיו\"\u0004 — הרי זו \u0003חובה. אתה אומר חובה או אינו אלא רשות? תלמוד לומר: \"בכל... גאלה תתנו\"\u0004 — \u0003הכתוב קבעו חובה.\u0004 הרי שלשיטת ר' אליעזר זהו משמעו של הכתוב.","\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרב אשי, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים אותה]\u0006 בגירסה אחרת שאמר זאת \u0003רבינא לרב אשי: בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003לרבות בתי ערי חומה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זה הוא שנאמר]\u0006 \u0003\"בכל\"\u0004 — שיש כאן לשון ריבוי של דבר שאינו בכלל \"גאולה תתנו לארץ\". \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לרבות בתי חצרים\u0004 — \u0003מאי\u0004 לשון \u0003\"בכל\"?\u0004 והרי נאמר כבר שהם בכלל שדה הארץ! לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 שנינו: \u0003מה תלמוד לומר\u0004 בכתוב \u0003\"יגאלנו\" \"יגאלנו\" \"יגאלנו\" שלש פעמים\u0004 — הרי זה \u0003לרבות כל הגאולות שנגאלות כסדר הזה\u0004 האמור בעבד עברי הנמכר לגוי, שאם לא גאל את עצמו — נגאל על ידי קרובים. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בשלושה הריבויים הללו לרבות גם \u0003בתי ערי חומה, ו\u0004גם \u0003עבד עברי\u0004 לגאולת קרובים? ודוחים: \u0003לא,\u0004 הכוונה היא לרבות \u0003בתי חצרים ושדה אחוזה.\u0004","ותוהים: \u0003בתי חצרים ושדה אחוזה\u0004 הלא \u0003בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 \u0003\"על שדה הארץ יחשב\"!\u0004 ומשיבים: כפי ש\u0003אמר רב נחמן בר יצחק\u0004 שגאולת קרובים האמורה בשדה אחוזה הכוונה היא \u0003לקרוב קרוב קודם,\u0004 שמי שקרוב יותר מחבירו עליו מוטלת החובה או זכות הגאולה, \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 בבתי החצרים ללמד \u0003לקרוב קרוב קודם.\u0004","ושואלים: \u0003היכא איתמר\u0004 \u0005[היכן נאמר]\u0006 דבר זה של \u0003רב נחמן בר יצחק\u0004 במקורו? ומשיבים: \u0003אהא\u0004 \u0005[על\u0006 ענין \u0005זה],\u0006 \u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם]\u0006 ללומדים: \u0003עבד עברי הנמכר לישראל\u0004 האם \u0003נגאל לקרובים או אינו נגאל לקרובים?\u0004 ומעירים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רבי לא תבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך\u0004 ש\u0003אמר: מי שאינו נגאל באלה,\u0004 בקרובים — \u0003נגאל בשש, אלמא לא מיפרק\u0004 \u0005[מכאן שאינו נגאל]\u0006 בקרובים, שהרי הוא מניח שאינו נגאל ב\"אלה\".","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא דרבנן\u0004 \u0005[על פי שיטת חכמים]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003ילפינן\u0004 \u0005[לומדים אנו]\u0006 בגזירה שווה \u0003\"שכיר\" \"שכיר\"\u0004 מנמכר לגוי, וכשם שאם נמכר לגוי נגאל לקרובים — אף בישראל נגאל, \u0003ולא דרשי\u0004 \u0005[ואינם דורשים]\u0006 \u0003\"יגאלנו\"\u0004 האמור בנמכר לגוי בלשון מיעוט, \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר כי הכוונה ב\u0003\"יגאלנו\"\u0004 בנמכר לגוי היא לשון מיעוט שכוונתו \u0003לזה\u0004 בלבד נאמרה הלכה זו שנגאל לקרובים \u0003ולא לאחר?\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 נאמר \u0003\"בכל... גאלה תתנו\"\u0004 — \u0003לרבות בתים ועבד עברי. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003בתי ערי חומה ועבד עברי הנמכר לישראל?\u0004 ודוחים: \u0003לא,\u0004 אפשר לומר שמדובר ב\u0003עבד עברי הנמכר לגוי.\u0004","ומקשים: \u0003עבד עברי הנמכר לגוי\u0004 הלא \u0003בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו]\u0006 \u0003\"או דדו או בן דדו יגאלנו\"\u0004 (ויקרא כה, מט) ואין צורך ללמדו מלשון ריבוי שבפסוק אחר!"],["\u0003ההוא\u0004 \u0005[אותו]\u0006 פסוק בא \u0003לקובעו חובה\u0004 לגאול אותו, \u0003ואפילו ל\u0004דעת \u0003ר' יהושע\u0004 שאין חובת גאולה בקרקעות, הרי במקרה זה חובה על הקרובים לגאול כדי שלא יטמע בין הגויים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מה תלמוד לומר \"יגאלנו\" \"יגאלנו \"יגאלנו\" שלש פעמים\u0004 — \u0003לרבות כל הגאולות שנגאלות כסדר הזה. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בריבוי זה ל\u0003בתי ערי חומה ועבד עברי הנמכר לישראל\u0004 שנגאלים בקרובים? ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003בתי חצרים ושדה אחוזה.\u0004 ותוהים: \u0003בתי חצרים בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"על שדה הארץ יחשב\"! אמר רב נחמן בר יצחק: ל\u0004למד שלענין מצוה זו \u0003קרוב קרוב קודם,\u0004 שכל הקרוב יותר קודם למצוה זו. וזהו המקום שבו אמר רב נחמן בר יצחק את דבריו אלה.","וחוזרים שוב לפירושה של המשנה. שנינו שהעבד \u0003הנרצע נקנה ברציעה.\u0004 ומקור הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ורצע אדניו את אזנו במרצע\u0004 ועבדו לעולם\u0003\"\u0004(שמות כא, ו).","עוד שנינו ש\u0003קונה\u0004 הנרצע \u0003את עצמו ביובל ובמיתת האדון\u0004 ומקור הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ועבדו\"\u0004 ואנחנו מדייקים מלשון הכתוב שהוא עובד רק את האדון, \u0003ולא את הבן ולא את הבת.\u0004 ומה שנאמר שם \u0003\"לעלם\"\u0004 הכוונה היא \u0003לעולמו של יובל,\u0004 שאין הכוונה לעולם = לנצח, אלא למסגרת זו של עולם, הכוללת את שנות היובל בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"מרצע\", אין לי\u0004 שיכול לנקב את אזנו של העבד הנרצע \u0003אלא\u0004 ב\u0003מרצע\u0004 בלבד, \u0003מנין לרבות\u0004 גם את \u0003הסול\u0004 (עץ מחודד) \u0003והסירא\u0004 (הקוץ) \u0003והמחט, והמקדח, והמכתב\u0004 שחורטים בו על שעווה, שאפשר לרצוע גם בהם — \u0003תלמוד לומר: \"ולקחת\u0004 את המרצע\u0003\"\u0004 (דברים טו, יז), \u0003לרבות כל דבר שנקח\u0004 (שנלקח) \u0003ביד,\u0004 אלו \u0003דברי ר' יוסי בר' יהודה.\u0004","\u0003רבי אומר:\u0004 אין לרבות את כל הכלים הללו, אלא רק חלק מהם, שכן \u0003מה מרצע מיוחד\u0004 בכך שהוא \u0003של מתכת\u0004 — \u0003אף כל\u0004 כלי שהוא \u0003של מתכת,\u0004 להוציא דברים שאינם של מתכת, שבהם אין לרצוע את אזנו. \u0003דבר אחר:\u0004 מה שנאמר \u0003\"\u0004ולקחת את \u0003המרצע\"\u0004 הרי זה \u0003להביא\u0004 (לרבות) את \u0003המרצע הגדול\u0004 שאפשר לרצוע בו.","\u0003אמר ר' אלעזר: יודן בריבי\u0004 (ר' יהודה הגדול) כך \u0003היה דורש: כשהן רוצעים אין רוצעים אלא במילתא,\u0004 בחלק הרך של האוזן. \u0003וחכמים אומרים:\u0004 אין הרציעה בחלק זה, שכן הדין הוא ש\u0003אין עבד עברי כהן נרצע\u0004 כלל, \u0003מפני שנעשה\u0004 ברציעה \u0003בעל מום\u0004 ונפסל בכך לעבודה במקדש, \u0003ואם תאמר\u0004 כי \u0003במילתא,\u0004 בחלק הרך של האוזן \u0003הם רוצעים\u0004 — \u0003היאך עבד עברי כהן יעשה\u0004 ברציעתו \u0003בעל מום?\u0004 והרי פצע בחלק הרך של האוזן איננו נחשב למום. \u0003הא\u0004 \u0005[הרי]\u0006 אתה למד מכאן ש\u0003אין נרצע אלא בגובה של אזן,\u0004 בחלק הסחוס שבה. ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005חלוקים]\u0006 רבי ור' יוסי בר' יהודה?","ומשיבים: ש\u0003רבי דריש\u0004 \u0005[דורש]\u0006 את התורה בשיטת \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים]\u0006 וכאן כך הוא לומד: \u0003\"ולקחת\"\u0004 — הרי זה \u0003כלל\u0004 לכל דבר שאפשר לרצוע בו, \u0003\"מרצע\"\u0004 — הרי זה \u0003פרט, \"באזנו ובדלת\"\u0004 — \u0003חזר וכלל,\u0004 ולפי שיטת \u0003כלל ופרט וכלל\u0004 — \u0003אי אתה דן\u0004 ומוסיף דברים נוספים \u0003אלא כעין הפרט; מה הפרט מפורש\u0004 מרצע, שהוא \u0003של מתכת\u0004 — \u0003אף כל\u0004 דבר שרוצעים בו יהיה \u0003של מתכת.\u0004","ואילו \u0003ר' יוסי דריש\u0004 \u0005[דורש]\u0006 את התורה בשיטת \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים],\u0006 וכך היא דרך דרשתו כאן: \u0003\"ולקחת\"\u0004 — הרי \u0003ריבה\u0004 כל דבר הנלקח ביד, \u0003\"מרצע\"\u0004 — \u0003מיעט, \"באזנו ובדלת\"\u0004 — \u0003חזר וריבה,\u0004 ולפי שיטת \u0003ריבה ומיעט וריבה\u0004 — \u0003ריבה הכל\u0004 חוץ מדבר אחד, ולענייננו כאן","\u0003מאי רבי\u0004 \u0005[מה ריבה ]\u0006 — \u0003רבי\u0004 \u0005[ריבה]\u0006 \u0003כל מילי\u0004 \u0005[הדברים]\u0006 הנוקבים אוזן, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מיעט\u0004 רק את הדבר הרחוק ביותר ממרצע — שהוא \u0003סם,\u0004 שאין דין רציעה על ידי סם העושה נקב.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003\"המרצע\"\u0004 — \u0003להביא מרצע הגדול.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה משמעות\u0006 הדברים\u0005]\u0006 כיצד מובן מכאן שמדובר במרצע גדול? ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רבא\u0004 שפירוש הכתוב \u0003\"\u0004גיד הנשה אשר על כף \u0003הירך\"\u0004 (בראשית לב, לב) כוונתו \u0003המיומנת שבירך,\u0004 שה\"א הידיעה באה ללמד שמדובר פה בדבר בולט וניכר, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"המרצע\"\u0004 כוונתו ל\u0003מיוחד שבמרצעין.\u0004","ועוד שנינו בברייתא: \u0003אמר ר' אלעזר, יודן בריבי היה דורש: כשהן רוצעין אין רוצעין אלא במילתא, וחכמים אומרים: אין עבד עברי כהן נרצע מפני שנעשה בעל מום.\u0004 ושואלים: ומדוע באמת לא יירצע \u0003ויעשה בעל מום\u0004 וייפסל! \u0003אמר רבה בר רב שילא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושב אל משפחתו\"\u0004 (ויקרא כה, מא) כוונתו \u0003למוחזק שבמשפחתו,\u0004 שחוזר לכל הדברים שמשפחתו החזיקה בהם קודם. ואם בזמן עבדותו נעשה הכהן בעל מום, נמצא שכאשר הוא משתחרר אינו יכול לחזור למשפחתו ולחזקת עבודתו במקדש כפי שהיה קודם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003עבד עברי כהן, מהו שימסור לו רבו\u0004 (אדוניו) \u0003שפחה כנענית?\u0004 וצדדי השאלה: האם נאמר כי עצם העובדה שעבד עברי מותר בשפחה כנענית \u0003חידוש הוא\u0004 שחידשה תורה בענין זה להתיר שפחה לאדם מישראל, וכיון שהוא חידוש \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דינם של \u0003כהנים ולא שנא\u0004 \u0005[ואינו שונה]\u0006 דינם של \u0003ישראל\u0004 זה מזה שכולם מותרים,","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003כהנים\u0004 מישראל \u0003הואיל וריבה בהן הכתוב מצות יתירות\u0004 משאר ישראל, ולכן יש לאסור גם כאן שפחה לכהן, למרות שלישראל היא מותרת. בתשובתה של שאלה זו נחלקו אמוראים, \u0003רב אמר: מותר\u0004 עבד עברי כהן בשפחה כנענית, \u0003ושמואל אמר: אסור.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב ענן: כי הויתו בי\u0004 \u0005[כאשר הייתם בביתו]\u0006 של \u0003מר שמואל\u0004 ולמדתם אצלו, \u0003באיסקומדרי איטלליתו\u0004 \u0005[בכלבלבים שיחקתם]?\u0006 כלומר, וכי לא למדתם ברצינות? \u0003מאי טעמא לא תימרו ליה מהא\u0004 \u0005[מדוע אין אתם אומרים לו\u0006 ראיה \u0005מכאן]\u0006 שכן שנינו, \u0003וחכמים אומרים: אין עבד עברי כהן נרצע מפני שנעשה בעל מום.\u0004","\u0003ואם תאמר\u0004 ש\u0003אין רבו מוסר לו שפחה כנענית\u0004 — אם כן לא שייך בכלל שעבד כהן יירצע, כי \u0003תיפוק לי\u0004 \u0005[תצא לו]\u0006 הלכה זו שאינו נרצע מטעם אחר — \u0003דבעינא\u0004 \u0005[שצריך]\u0006 שיתקיים בו \u0003\"אהבתי את אדני את אשתי\u0004 השפחה \u0003ואת בני\"\u0004 (שמות כא, ה) \u0003וליכא\u0004 \u0005[ואין]\u0006 הדבר יכול להתקיים בכהן אם אין אדוניו מוסר לו שפחה כנענית, \u0003תו לא מידי\u0004 \u0005[\u0006ו\u0005אין עוד דבר]\u0006 לענות על הוכחה זו. ואף מן הטעם שנתנו חכמים מוכח שאף לעבד שהוא כהן נותנים שפחה כנענית.","בדומה לכך \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003כהן\u0004 שיצא למלחמה, \u0003מהו\u0004 שיהא מותר \u0003ב\u0004ביאת אשת \u0003יפת תואר?\u0004 האם נאמר כי היתר זה ביפת תואר — \u0003חידוש הוא\u0004 שחידשה תורה לבוא על הגויה, ולכן \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דינו של \u0003כהן ולא שנא\u0004 \u0005[ואינו שונה]\u0006 דינו של \u0003ישראל\u0004 זה מזה, והכל מותרים, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003כהנים, הואיל וריבה בהן מצות יתרות?\u0004 בתשובתה של שאלה זו נחלקו אמוראים, \u0003רב אמר: מותר, ושמואל אמר: אסור.\u0004","ומעירים: \u0003בביאה ראשונה\u0004 שבא היוצא למלחמה על יפת התואר \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[שהכל אינם חלוקים שמותר],\u0006 שהרי \u0003לא דברה תורה\u0004 כשהתירה לבוא על יפת תואר \u0003אלא כנגד יצר הרע\u0004 שלא יבוא עליה באיסור, ולענין זה בודאי שיצרו של כהן תוקפו כמו לישראל.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה \u0003בביאה שניה,\u0004 האם יהא מותר לכהן להביאה לביתו לגיירה ולשאתה לאשה; \u0003רב אמר: מותר, ושמואל אמר: אסור.\u0004 וטעמיהם: \u0003רב אמר: מותר, הואיל ואישתריא\u0004 \u0005[והותרה לו]\u0006 בפעם הראשונה — כבר \u0003אישתרי\u0004 \u0005[הותרה]\u0006 לגמרי. \u0003ושמואל אמר: אסור, דהא הויא לה\u0004 \u0005[שהרי היא]\u0006 על כל פנים \u0003גיורת, וגיורת לכהן לא חזיא\u0004 \u0005[אינה ראויה].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את מחלוקתם בדרך אחרת: \u0003בביאה שניה\u0004 — \u0003כולי עלמא לא פליגי דאסירא\u0004 \u0005[הכל אינם חלוקים ש\u0006היא \u0005אסורה]\u0006 מהטעם \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003גיורת\u0004 ואסורה לכהן. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בביאה ראשונה. רב אמר: מותר, דהא\u0004 \u0005[שהרי]\u0006 \u0003לא דברה תורה אלא כנגד יצר הרע, ושמואל אמר: אסור,\u0004 שכן \u0003כל היכא דקרינא ביה\u0004 \u0005[בכל מקום שאנו קוראים בו]\u0006 ויכולים לקיים גם את ההמשך \u0003\"והבאתה אל תוך ביתך\"\u0004 (דברים כא, יב) — \u0003קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 גם את ההתחלה \u0003\"וראית בשביה\u0004... וחשקת בה ולקחת לך לאשה\u0003\"\u0004 (שם יא). \u0003כל היכא דלא קרינא ביה\u0004 \u0005[כל מקום שאין אנו קוראים בו]\u0006 \u0003\"והבאתה אל תוך ביתך\",\u0004 שאינו רשאי לעשות זאת — \u0003לא קרינא ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 \u0003\"וראית בשביה\".\u0004","בדין אשת יפת תואר \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"וראית בשביה\"\u0004 — כוונתו \u0003בשעת שביה,\u0004 שנתן עיניו בה מתחילה, כבר בשעת השבי. ומה שנאמר לשון \u0003\"אשת\"\u0004 הרי זה בא להדגיש: \u0003ואפילו\u0004 היא \u0003אשת איש,\u0004 שאף זו הותרה. \u0003\"יפת תואר\",\u0004 מכאן מוכיחים ש\u0003לא דברה תורה\u0004 בענין זה \u0003אלא כנגד יצר הרע,\u0004 שכיון שהיא יפת תואר חושק בה. ומדוע התירה התורה את הדבר? \u0003מוטב שיאכלו ישראל בשר\u0004"],["\u0003תמותות שחוטות\u0004 בהמות גוססות שנשחטו, \u0003ואל יאכלו בשר תמותות נבילות,\u0004 כלומר, מוטב שייעשה דבר זה בהיתר כלשהו ולא ייעשה באיסור גמור. ומה שנאמר בפרשת יפת תואר \u0003\"וחשקת\u0004 בה\u0003\"\u0004 (דברים כא, יא) — לומר \u0003אף על פי שאינה נאה,\u0004 כי על ענין של חשיקה אין מקום לדון אם נאה היא או לא. \u0003\"בה\"\u0004 — למעט: \u0003ולא בה ובחברתה,\u0004 שאינו יכול לקחת אלא יפת תואר אחת.","\u0003\"ולקחת\"\u0004 — לומר: \u0003ליקוחין יש לך בה,\u0004 כלומר, לאחר שלוקחה הרי היא כאשתו ממש. \u0003\"לך לאשה\"\u0004 אף הוא מיעוט — \u0003שלא יקח שתי נשים, אחת לו ואחת לאביו,\u0004 או \u0003אחת לו ואחת לבנו.\u0004 ומה שנאמר \u0003\"והבאתה\u0004 אל תוך ביתך\u0003\"\u0004 (שם, יב) — \u0003מלמד שלא ילחצנה\u0004 לבוא עליה \u0003במלחמה\u0004 אלא יביאנה קודם לביתו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בעבד הנרצע \u0003\"\u0004ו\u0003אם אמר יאמר\u0004 העבד אהבתי את אדוני... לא אצא חפשי\u0003\"\u0004 (שמות כא, ה) בלשון כפולה, לאמר שאינו נרצע \u0003עד שיאמר וישנה,\u0004 כיצד? — \u0003אמר בתחילת שש\u0004 שהוא רוצה להיות עבד נרצע \u0003ולא אמר בסוף שש\u0004 השנים של עבדותו — \u0003אינו נרצע, שנאמר: \"לא אצא חפשי\",\u0004 שאינו נרצע \u0003עד שיאמר בשעת יציאה.\u0004","\u0003אמר בסוף שש ולא אמר בתחילת שש\u0004 — אף זה \u0003אינו נרצע, שנאמר: \"אם אמר יאמר העבד\"\u0004 — \u0003עד שיאמר כשהוא\u0004 עדיין \u0003עבד.\u0004 עד כאן לשון הברייתא.","ודנים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: \u0003אמר בתחילת שש ולא אמר בסוף שש\u0004 — \u0003אינו נרצע, שנאמר: \"לא אצא חפשי\".\u0004 ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע דייק \u0003מ\"לא אצא חפשי\"? תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד, \u0005לו]\u0006 הלכה זו מכך \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 תנאי אחר, שיוכל לומר \u0003\"אהבתי את אדני את אשתי ואת בני\"\u0004 (שם) \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 שהרי בתחילת שש ודאי שאין לו עדיין בנים מאשתו השפחה.","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול, שנינו שם שאם \u0003אמר בסוף שש ולא אמר בתחילת שש אינו נרצע,\u0004 ותלו זאת בכך \u0003שנאמר \"העבד\".\u0004 ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 ב\u0003סוף שש לאו עבד הוא?\u0004 \u0003אמר רבא:\u0004 יש להסביר כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003בתחילת שש\u0004 — לא ממש בתחילת שש שנים, אלא אף \u0003בתחילת פרוטה אחרונה\u0004 שהוא מגיע בזמן עבודתו לתחילת הפרוטה האחרונה של שווי עבודתו, שאז הוא עדיין עבד. \u0003ומאי\u0004 \u0005[ומהו]\u0006 ענין \u0003בסוף שש\u0004 — \u0003בסוף פרוטה אחרונה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היו \u0003לו\u0004 לעבד \u0003אשה ובנים, ולרבו אין אשה ובנים\u0004 — \u0003אינו נרצע, שנאמר: \"כי אהבך ואת ביתך\"\u0004 (דברים טו, טז) וביתו של אדם משמעו אשתו וילדיו, ואם אין הכתוב מתקיים במלואו כאשר אין לאדון אשה ובנים — אינו נרצע. וכן אם היו \u0003לרבו אשה ובנים ולו אין אשה ובנים\u0004 — \u0003אינו נרצע, שנאמר: \"אהבתי את אדני את אשתי ואת בני\"\u0004 (שמות כא, ה).","ועוד, אם היה \u0003הוא אוהב את רבו, ורבו אינו אוהבו\u0004 — \u0003אינו נרצע, שנאמר: \"כי טוב לו עמך\"\u0004 (דברים שם) לומר שלשניהם טוב זה עם זה. אם \u0003רבו אוהבו והוא אינו אוהב את רבו\u0004 — \u0003אינו נרצע, שנאמר: \"כי אהבך\".\u0004 היה \u0003הוא חולה ורבו אינו חולה\u0004 — \u0003אינו נרצע, שנאמר: \"כי טוב לו עמך\",\u0004 וחולה לא טוב לו. כיוצא בך \u0003רבו חולה והוא אינו חולה\u0004 — \u0003אינו נרצע, שנאמר: \"עמך\",\u0004 כלומר, טוב לו בדומה לך.","על סמך אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי בר אביי:\u0004 אם היו \u0003שניהם חולין, מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם \u0003\"עמך\" בעינן\u0004 \u0005[צריכים אנו]\u0006 שעיקר הדבר שהעבד יהיה כאדוניו — \u0003והא איכא\u0004 \u0005[והרי יש כאן],\u0006 ולכן, נרצע העבד. \u0003או דילמא\u0004 \u0005[שמא]\u0006 עיקר הדיוק הוא \u0003\"כי טוב לו עמך\" בעינן\u0004 \u0005[צריכים אנו]\u0006 שלשניהם יהיה טוב — \u0003והא ליכא\u0004 \u0005[והרי אין כאן]\u0006 שהרי שניהם חולים, ואינו נרצע. שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"כי טוב לו עמך\"\u0004 כוונתו: \u0003עמך\u0004 וכמותך יהא העבד \u0003במאכל, עמך במשתה, שלא תהא אתה אוכל פת נקיה והוא אוכל פת קיבר, אתה שותה יין ישן\u0004 שהוא טוב יותר \u0003והוא שותה יין חדש, אתה ישן על גבי\u0004 מצע של \u0003מוכין\u0004 (סמרטוטים רכים) \u0003והוא ישן על גבי תבן. מכאן אמרו: כל הקונה עבד עברי\u0004 — \u0003כקונה אדון לעצמו,\u0004 שהרי הוא צריך לדאוג לו כמי שצריך לדאוג לאדונו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בשחרור העבד \u0003\"ויצא מעמך הוא ובניו עמו\"\u0004 (ויקרא כה, מא). \u0003אמר ר' שמעון:\u0004 לכאורה הפסוק תמוה, שכן \u0003אם הוא נמכר\u0004 — \u0003בניו ובנותיו מי\u0004 \u0005[האם]\u0006 \u0003נמכרים?\u0004 ואם כן מדוע צריך לומר שיוצאים גם הם עימו? אלא \u0003מכאן שרבו חייב במזונות בניו,\u0004 שחייב לפרנס את בניו במקומו כל עוד הוא עבדו, וכשמשתחרר העבד יוצאים גם בניו. \u0003כיוצא בדבר אתה אומר,\u0004 על הכתוב \u0003\"אם בעל אשה הוא ויצאה אשתו עמו\"\u0004 (שמות כא, ג) \u0003אמר ר' שמעון:\u0004 לכאורה \u0003אם הוא נמכר\u0004 — \u0003אשתו מי\u0004 \u0005[האם]\u0006 \u0003נמכרה?\u0004 אלא \u0003מכאן שרבו חייב במזונות אשתו.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים; \u0003דאי אשמועינן\u0004 \u0005[שאם היה השמיע לנו]\u0006 רק לגבי \u0003בניו\u0004 שהאדון חייב במזונותיהם, היינו אומרים \u0003משום\u0004 ש\u0003לא בני מיעבד ומיכל נינהו\u0004 \u0005[עבודה ואכילה הם],\u0006 שאינם ראוים לפרנס את עצמם, שהרי קטנים הם, ולכן חייב לפרנסם. \u0003אבל אשתו\u0004 ש\u0003בת מיכל ומיעבד\u0004 \u0005[אכילה ושתיה]\u0006 \u0003היא\u0004 \u0003אימא תעביד ותיכול\u0004 \u0005[אמור\u0006 ש\u0005תעבוד ותאכל\u0006 בשכר עבודתה\u0005]\u0006 ולא יצטרך האדון לפרנסה.","ומצד שני: \u0003ואי אשמעינן\u0004 \u0005[ואם היה השמיע לנו]\u0006 רק בענין \u0003אשתו,\u0004 היינו אומרים שחייב האדון במזונותיה \u0003דלאו דירכה להדורי\u0004 \u0005[שאין דרכה לחזר]\u0006 על הפתחים מפני בושתה, \u0003אבל בניו דדירכייהו להדורי\u0004 \u0005[שדרכם לחזר],\u0006 שאינם מתביישים, מפני שקטנים הם \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצטרך לפרנסם, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006"],["\u0003אילו נאמר \"אזנו בדלת\"\u0004 — \u0003הייתי אומר: ידקור כנגד אזנו בדלת\u0004 בלבד, שאת ה\u0003דלת\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 ידקור, ואת \u0003אזנו\u0004 — \u0003לא.\u0004 ותוהים: איך אפשר לומר \u0003ואזן לא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ורצע אדניו את אזנו במרצע\"\u0004 (שמות כא, ו)!","\u0003אלא\u0004 כך יש לומר: \u0003הייתי אומר ירצענה לאזן מאבראי\u0004 \u0005[מבחוץ]\u0006 ולאו דווקא על גבי הדלת \u0003ויניחנה\u0004 אחר כך \u0003על הדלת, וידקור כנגד אזנו בדלת\u0004 — \u0003תלמוד לומר: \"\u0004ולקחת את המרצע ונתתה \u0003באזנו ובדלת\"\u0004 (דברים טו, יז). \u0003הא כיצד\u0004 עושה — \u0003דוקר\u0004 באזנו \u0003והולך עד שמגיע אצל דלת.\u0004","נאמר בכתוב \u0003\"דלת\", שומע אני\u0004 כל דלת: \u0003בין\u0004 שהיא \u0003עקורה\u0004 ממקומה \u0003בין שאינה עקורה,\u0004 — \u0003תלמוד לומר \"מזוזה\", מה מזוזה\u0004 (מסגרת הדלת) דווקא שהיא \u0003מעומד\u0004 וקבועה — \u0003אף דלת נמי\u0004 \u0005[גם כן]\u0006 \u0003מעומד,\u0004 שהדלת צריכה להיות במקומה ולא עקורה.","\u0003רבן יוחנן בן זכאי היה דורש את המקרא הזה כמין חומר\u0004 כענין של משל ודוגמא: \u0003מה נשתנה אזן מכל אברים שבגוף\u0004 שתירצע דווקא היא? \u0003אמר הקדוש ברוך הוא: אזן ששמעה קולי על הר סיני בשעה שאמרתי \"כי לי בני ישראל עבדים\"\u0004 (ויקרא כה, נה) ויש בכך הדגשה: \u0003ולא עבדים לעבדים, והלך\u0004 אדם \u0003זה וקנה\u0004 מרצונו \u0003אדון לעצמו\u0004 — הרי מגיע לאוזן הזו ש\u0003ירצע.\u0004","\u0003ור' שמעון בר רבי היה דורש את המקרא הזה כמין חומר: מה נשתנה דלת ומזוזה מכל כלים שבבית\u0004 שדווקא בהן נעשית הרציעה? \u0003אמר הקדוש ברוך הוא: דלת ומזוזה שהיו עדים במצרים בשעה שפסחתי על המשקוף ועל שתי המזוזות\u0004 של בתי בני ישראל, \u0003ואמרתי \"כי לי בני ישראל עבדים\" ולא עבדים לעבדים, והוצאתים\u0004 אז \u0003מעבדות לחירות, והלך זה וקנה אדון לעצמו\u0004 ונעשה עבד — על כן \u0003ירצע בפניהם,\u0004 שהם כעדים שעבר על דברים שנאמרו בתורה.","\u0003עבד כנעני נקנה בכסף ובשטר ובחזקה, וקונה את עצמו\u0004 להשתחרר \u0003בכסף על ידי אחרים,\u0004 שנותנים כסף לאדוניו, \u0003ובשטר\u0004 שחרור אפילו \u0003על ידי עצמו,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: בכסף\u0004 גם \u0003על ידי עצמו ובשטר על ידי אחרים, ובלבד שיהא הכסף משל אחרים\u0004 ולא משל העבד, שהרי אין לעבד קנין לעצמו, שכל שקנה העבד — נקנה לרבו.","שואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שאלו דרכי קנייתו של העבד? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעבדים גויים: \u0003\"והתנחלתם אתם לבניכם אחריכם לרשת אחזה\"\u0004 (ויקרא כה, מו) \u0003הקישן\u0004 (הישווה אותם) \u0003הכתוב\u0004 את העבדים \u0003לשדה אחוזה; מה שדה אחוזה נקנה בכסף,\u0004 או \u0003בשטר,\u0004 או \u0003בחזקה\u0004 — \u0003אף עבד כנעני נקנה בכסף בשטר ובחזקה.\u0004","ויש לשאול: \u0003אי\u0004 \u0005[או]\u0006 אולי נדרוש אחרת: \u0003מה שדה אחוזה חוזרת לבעלים ביובל\u0004 — \u0003אף עבד כנעני חוזר לבעלים\u0004 הראשונים \u0003ביובל?\u0004 — \u0003תלמוד לומר: \"לעלם בהם תעבדו\"\u0004 (שם) משמע שהמכירה היא לחלוטין.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003אף בחליפין\u0004 נקנה העבד. ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנה, שלא שנה קנין חליפין, מה טעמו? ומשיבים: \u0003מילתא דליתא\u0004 \u0005[דבר,\u0006 קנין, \u0005שאינו\u0006 קיים\u0005]\u0006 \u0003ב\u0004קניית \u0003מטלטלין\u0004 — \u0003קתני\u0004 \u0005[שנה],\u0006 מפני שיש חידוש בזה, שהעבד אף על פי שהוא מיטלטל נקנה כדרך שנקנות קרקעות, \u0003ו\u0004\u0003מילתא דאיתא\u0004 \u0005[דבר,\u0006 קנין, \u0005שישנו]\u0006 \u0003ב\u0004קניית \u0003מטלטלין\u0004 — \u0003לא קתני\u0004 \u0005[שנה].\u0006","\u0003אמר שמואל: עבד כנעני נקנה במשיכה,\u0004 כדרך שנקנים שאר מטלטלים. ו\u0003כיצד\u0004 נעשית משיכה בעבד — \u0003תקפו\u0004 (החזיק בו בכח) האדון \u0003ובא\u0004 העבד \u0003אצלו\u0004 — הרי \u0003קנאו\u0004 בכך. אבל אם \u0003קראו ובא אצלו\u0004 מרצונו — \u0003לא קנאו.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנתנו, הרי מובן מדוע לא שנה דין קנין זה, כי כאמור \u0003מילתא דאיתא במטלטלי לא קתני, דליתא במטלטלי קתני\u0004 \u0005[דבר שישנו ב\u0006דין קנין \u0005מטלטלין לא שנה, דבר שאינו ב\u0006קנין \u0005מטלטלין שנה]\u0006 וקנין משיכה ישנו במטלטלין. \u0003אלא לתנא ברא\u0004 \u0005[החיצון]\u0006 של התוספתא ששנה חליפין \u0003ניתני\u0004 \u0005[שישנה]\u0006 גם \u0003משיכה!\u0004 ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 קנין חליפין הרי זה בגלל שהוא \u0003מילתא דאיתא\u0004 \u0005[דבר שישנו]\u0006 \u0003בין במקרקעי\u0004 \u0005[בקרקעות]\u0006 \u0003בין במטלטלי\u0004 \u0005[במטלטלין],\u0006 אבל \u0003משיכה דבמטלטלי איתא, במקרקעי ליתא\u0004 \u0005[שבמטלטלין ישנה, בקרקעות אינה]\u0006 — \u0003לא קתני\u0004 \u0005[שנה].\u0006","ולבירור דברי שמואל: \u0003כיצד\u0004 דרך קנין עבד במשיכה, \u0003תקפו\u0004 (החזיק בו בכח) האדון \u0003ובא אצלו\u0004 — \u0003קנאו,\u0004 אם \u0003קראו ובא אצלו\u0004 — \u0003לא קנאו.\u0004 שואלים: \u0003וקראו לא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד\u0004 נקנית בהמה \u0003במסירה?\u0004 אם \u0003אחזה בטלפה\u0004 (בפרסה שלה), או \u0003בשערה,\u0004 או \u0003באוכף שעליה,\u0004 או \u0003בשליף\u0004 (משא) \u0003שעליה,\u0004 או \u0003בפרומביא\u0004 (מתג) \u0003שבפיה\u0004 או \u0003בזוג\u0004 (בפעמון) \u0003שבצוארה\u0004 — \u0003קנאה.\u0004","\u0003כיצד\u0004 קונה בהמה \u0003במשיכה? קורא לה והיא באה, או שהכישה\u0004 (היכה אותה) \u0003במקל ורצתה\u0004 (רצה) \u0003לפניו, כיון שעקרה יד ורגל\u0004 ממקום עמידתה — \u0003קנאה\u0004 בכך. \u0003ר' אסי ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003ר' אחא אומר: עד שתהלך לפניו מלא קומתה,\u0004 ולא די בעקירת יד ורגל. על כל פנים למדנו מכאן שבהמה נקנית במשיכה גם על ידי קריאה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 שיש להבדיל בין קנין עבד לקנין בהמה: \u0003בהמה אדעתא דמרה אזלה\u0004 \u0005[על דעת בעליה\u0006 היא \u0005הולכת]\u0006 שאין בה דעת, ואם הולכת למי שקורא לה הרי זו כמשיכה, ואילו \u0003עבד אדעתיה דנפשיה קאזיל\u0004 \u0005[על דעת עצמו\u0006 הוא \u0005הולך]\u0006 ולכן אין זה קנין משיכה, שהרי לא עשה האדון בכך פעולת קנין. \u0003אמר רב אשי: עבד קטן כבהמה דמי\u0004 \u0005[נחשב],\u0006 שכיון שאין לו דעת — הרי הוא נקנה בקריאה, כדין בהמה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד\u0004 קונה את העבד \u0003בחזקה?\u0004 אם \u0003התיר לו\u0004 העבד את \u0003מנעלו, או הוליך כליו\u0004 (בגדיו) \u0003אחריו לבית המרחץ,\u0004 או \u0003הפשיטו\u0004 או \u0003הרחיצו,\u0004 או \u0003סכו,\u0004 או \u0003גרדו\u0004 (גרד ממנו את השמן שסך בו), או \u0003הלבישו\u0004 או \u0003הנעילו,\u0004 או \u0003הגביהו\u0004 — \u0003קנאו. אמר ר' שמעון: לא תהא חזקה גדולה מהגבהה שהגבהה קונה בכל מקום.\u0004 על הדברים האחרונים שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 ר' שמעון? שנראה שהוא חולק, אך אין הענין מובן, שהרי גם תנא קמא אמר שקונה בהגבהה.","\u0003אמר רב אשי:\u0004 כך צריך להבין: אם \u0003הגביהו הוא לרבו\u0004 (את רבו) — \u0003קנאו,\u0004 שהרי עושה מלאכה לאדוניו, אבל \u0003במקרה ש\u0004\u0003הגביהו רבו לו\u0004 — \u0003לא קנאו,\u0004 שהרי לא עשה העבד עבורו עבודה. ועל כך \u0003אמר ר' שמעון: לא תהא\u0004 קנין \u0003חזקה גדולה מ\u0004קנין \u0003הגבהה, שהגבהה קונה בכל מקום,\u0004 ואם כן, גם המגביה את העבד — קנאו.","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 שבמקרה ש\u0003הגביהו הוא לרבו\u0004 — \u0003קנאו,\u0004 שקונה אותו האדון בכך לדעת, \u0003אלא מעתה שפחה כנענית תקנה\u0004 לאדון \u0003בביאה\u0004 שבא עליה, שהרי אפשר לומר שהיא מגביהה אותו בשעת ביאה! ומשיבים: ביאה שבא עליה אינה כמלאכה שעושה עבורו, ומדוע? \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שהוא קונה את העבד בעבודה שהעבד עובד בשבילו — הרי זה במקום ש\u0003זה\u0004 (האדון) \u0003נהנה, וזה\u0004 העבד \u0003מצטער\u0004 (סובל) בכך, ובכך מתבטאת בעלותו של האדון, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בביאה: \u0003זה נהנה וזה נהנה הוא\u0004 וכיון ששני הם נהנים מכך, אין לראות בזה דרך קנין.","שואלים: ואם בא עליה \u0003שלא כדרכה מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אז אין לאשה הנאה בכך. \u0003אמר רב אחיי [בר אדא] דמן אחא: מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 \u0003דלאו הנאה אית להו לתרוייהו\u0004 \u0005[שאין להם הנאה, לשניהם]\u0006 אפילו בביאה שלא כדרכה? \u0003ועוד: \"משכבי אשה\"\u0004 (ויקרא יח, כב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 וכיון שנאמר הדבר בלשון רבים, למדים שיש שני משכבות באשה ו\u0003הקישה\u0004 (הישווה) \u0003הכתוב\u0004 את הביאה \u0003כדרכה לשלא כדרכה\u0004 לכל ענין.","מסופר: \u0003ר' יהודה הנדואה\u0004 \u0005[מהודו]\u0006 \u0003גר שאין לו יורשין הוה\u0004 \u0005[היה].\u0006 כאשר \u0003חלש\u0004 \u0005[חלה],\u0006 \u0003על\u0004 \u0005[נכנס]\u0006 \u0003מר זוטרא לשיולי ביה\u0004 \u0005[לשאול בו]\u0006 לשלומו, \u0003חזייה דתקיף ליה עלמא טובא\u0004 \u0005[ראה אותו שמתגבר עליו העולם ביותר],\u0006 כלומר, שהוא גוסס ועומד למות בעוד זמן קצר. \u0003אמר ליה לעבדיה\u0004 \u0005[אמר לו\u0006 מר זוטרא \u0005לעבדו]\u0006 של ר' יהודה: \u0003שלוף\u0004 \u0005[התר]\u0006 \u0003לי מסנאי\u0004 \u0005[נעלי]\u0006 \u0003ואמטינהו לביתא\u0004 \u0005[והבא אותם לביתי],\u0006 שרצה לקנות אותו על ידי זה בשעת מותו של בעליו, שכיון שמת הגר ואין לו יורשים — כל הקודם ולוקח נכסיו זוכה. ומעירים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאותו עבד \u0003גדול\u0004 (מבוגר) \u0003הוה\u0004 \u0005[היה].\u0006"],["\u0003זה\u0004 ר' יהודה \u0003פירש למיתה, וזה\u0004 מר זוטרא \u0003פירש לחיים\u0004 וזכה בעבד.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שאותו עבד \u0003קטן הוה\u0004 \u0005[היה],\u0006 \u0003ו\u0004מר זוטרא עשה זאת ש\u0003לא כ\u0004שיטת \u0003אבא שאול.\u0004 ומה עניינה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גר שמת\u0004 בלי יורשים \u0003ובזבזו\u0004 (בזזו, לקחו) \u0003ישראל\u0004 את \u0003נכסיו\u0004 שהרי נעשו כהפקר, \u0003והיו בהן,\u0004 בנכסים, \u0003עבדים, בין גדולים בין קטנים\u0004 — כל העבדים הללו \u0003קנו עצמן\u0004 ברגע מותו של אדונם הגר כ\u0003בני חורין,\u0004 משום שבמותו נעשו כל נכסיו הפקר, ואף העבדים זכו בעצמם מן ההפקר. \u0003אבא שאול אומר:\u0004 העבדים ה\u0003גדולים\u0004 שיש בהם דעת לקנות — \u0003קנו עצמן\u0004 והריהם \u0003בני חורין,\u0004 ואילו ה\u0003קטנים\u0004 — \u0003כל המחזיק בהן זכה בהן\u0004 גם כשחלף זמן מפטירתו של הגר. ואם כן לשיטה זו לא היה צריך מר זוטרא למהר ולזכות בו בחיי ר' יהודה לפני שיזכה העבד בעצמו, אלא היה יכול להמתין עד שימות ר' יהודה ואז היה זוכה בו.","שנינו במשנה על העבד ש\u0003קונה\u0004 את \u0003עצמו בכסף\u0004 ולדעת ר' מאיר \u0003בכסף על ידי אחרים.\u0004 ומדייקים: משמע כשהשתחרר העבד בכסף על ידי אחרים — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל לא על ידי עצמו.\u0004 ומעתה נברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים],\u0006 באיזה מקרה מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששחרר את העבד הכנעני \u0003שלא מדעתו\u0004 של העבד — אולם \u0003מכדי שמענא ליה\u0004 \u0005[הלא שמענו אותו]\u0006 את \u0003ר' מאיר דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003חוב הוא לעבד שיצא מיד רבו לחירות,\u0004 ששחרור עבד אינו זכות לו כי מפסיד הוא בכך הנאות מסויימות, אלא חוב לו. \u0003ותנינא\u0004 \u0005[ושנינו]:\u0006 \u0003זכין לאדם שלא בפניו, ואין חבין לו אלא בפניו.\u0004 ואם כן כיצד יכולים האחרים לחוב לעבד שלא בפניו ולשחרר אותו שלא מדעתו?","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 ששחררוהו \u0003מדעתו\u0004 של העבד, \u0003והא קמשמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003על ידי אחרים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003על ידי עצמו\u0004 — \u0003לא. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אין קנין לעבד בלא רבו,\u0004 שלא ייתכן שיהיה לעבד קנין כלשהו שלו, שכל דבר שזוכה בו העבד מיד זוכה בו אדוניו. ולכן אין אפשרות שיהיה לו עצמו כסף שיוכל לקנות את עצמו, אלא הכסף צריך להינתן לבעליו על ידי אחרים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003בשטר על ידי עצמו.\u0004 ונדייק: \u0003על ידי עצמו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003על ידי אחרים\u0004 שהם יקבלו את השטר בשבילו — \u0003לא. ו\u0004לפי דבריך \u0003אי\u0004 \u0005[ואם]\u0006 שטר זה נעשה \u0003מדעתו\u0004 של העבד, אם כן \u0003על ידי אחרים אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003על ידי עצמו\u0004 — כוונתו לא רק על ידי אחרים אלא \u0003אף על ידי עצמו, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 על ידי כך: ש\u0003גיטו וידו באים כאחד,\u0004 שהגט = שטר שחרורו, וידו = זכות הקנין שלו בשטר באים בבת אחת, שאף שקודם לכן, בהיותו עבד אין לו כוח משפטי לקנות קנין, כיון שהוא מקבל שטר שחרור — הרי קבלת השטר וקבלת כוח הקנין באים ביחד. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא תני הכי\u0004 \u0005[שנה כך]\u0006 ר' מאיר בברייתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשטר\u0004 דווקא \u0003על ידי עצמו ולא על ידי אחרים,\u0004 אלו \u0003דברי ר' מאיר!\u0004","\u0003אמר אביי: לעולם\u0004 יש לפרש את כל דברי ר' מאיר שהעבד משתחרר אף \u0003שלא מדעתו, ושאני\u0004 \u0005[ושונה]\u0006 \u0003כסף, הואיל וקני ליה בעל כורחיה\u0004 \u0005[וקונה אותו\u0006 מאדון אחר בכסף \u0005בעל כרחו]\u0006 ואין צורך בדעת העבד, אף \u0003מקני ליה בעל כורחיה\u0004 \u0005[מקנה אותו\u0006 לעצמו גם כן \u0005בעל כרחו]\u0006 ואינו צריך לדעתו למרות שחוב הוא לו לצאת.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003שטר נמי\u0004 \u0005[גם כן],\u0006 שהרי העבד נקנה בעל כרחו בשטר, וישתחרר בעל כרחו גם כן בשטר על ידי אחרים! ומשיבים: \u0003האי שטרא\u0004 \u0005[זה שטר]\u0006 \u0003לחוד והאי שטרא\u0004 \u0005[והז שטר]\u0006 \u0003לחוד\u0004 ואינו דומה שטר המכר לשטר השחרור.","ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בקניה ושחרור \u0003האי כספא\u0004 \u0005[זה כסף]\u0006 \u0003לחוד והאי כספא\u0004 \u0005[וזה\u0006 \u0003כסף]\u0004 \u0003לחוד,\u0004 שבכל אחד מהמקרים נותן הכסף למטרה אחרת, ואין הוא אותו כסף ואיך אפשר להשוותם? ומשיבים: \u0003טיבעא מיהא חד\u0004 \u0005[מטבע על כל פנים אחד]\u0006 \u0003הוא,\u0004 אף שהפעולה המשפטית אינה דומה, מכל מקום אין הבדל בגוף הכסף שמשתמשים בו לכך. מה שאין כן בשטר שתוכנו הוא המחשיב אותו לשטר, ותוכן השטר שונה בקניה ובשחרור.","\u0003רבא אמר,\u0004 כך יש לחלק: בשחרור על ידי \u0003כסף, קבלת רבו\u0004 היא ש\u0003גרמה לו\u0004 להשתחרר, ולא נתינת הכסף על ידי האחרים, ומשום כך אין הם נחשבים כחבים לעבד שלא מדעתו, ואילו ב\u0003שטר\u0004 — \u0003קבלת אחרים\u0004 את השטר בשביל העבד היא ש\u0003גרמה לו\u0004 להשתחרר ואין חבים לו לאדם שלא בפניו ושלא מדעתו.","שנינו במשנה ש\u0003חכמים אומרים\u0004 שעבד משתחרר \u0003בכסף על ידי עצמו.\u0004 ונדייק מכאן: \u0003בכסף על ידי עצמו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003על ידי אחרים\u0004 — \u0003לא.\u0004 ועל כך שואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נהי נמי\u0004 \u0005[\u0006אם \u0005אמנם גם כן]\u0006 שנעשה הדבר ב\u0003שלא מדעתו\u0004 של העבד, \u0003מכדי שמענא להו לרבנן דאמרי\u0004 \u0005[הלוא שמענו אותם, את החכמים, שאומרים]:\u0006 \u0003זכות הוא\u0004 לעבד \u0003שיצא מתחת יד רבו לחירות, ותנינא\u0004 \u0005[ושנינו]:\u0006 \u0003זכין לאדם שלא בפניו, ואין חבין לו אלא בפניו.\u0004 ומדוע אם כן אינו משתחרר על ידי אחרים הנותנים את הכסף, ואפילו שלא מדעתו — שהרי זכות היא לו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003על ידי עצמו\u0004 — כוונתו שלא רק על ידי אחרים יכול להיפדות אלא \u0003אף על ידי עצמו, וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 בכך ש\u0003יש קנין לעבד בלא רבו\u0004 — \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003בשטר על ידי אחרים\u0004 ומשמע \u0003ולא על ידי עצמו. והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 לדעת חכמים ש\u0003גיטו וידו באין כאחד,\u0004 ואם כן מדוע לא ישתחרר בשטר על ידי עצמו?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003על ידי אחרים\u0004 — כוונתו לא רק על ידי אחרים אלא \u0003אף על ידי אחרים, והא קא משמע לן\u0004 \u0005[ו\u0006חידוש \u0005זה משמיע\u0006 הוא \u0005לנו]\u0006 בביטוי זה ש\u0003זכות הוא לעבד שיצא מיד רבו לחירות, אי הכי\u0004 \u0005[אם כך]\u0006 אתה מבין את כל המשנה, הרי שאין כל הבדל בין שחרור בכסף לשחרור בשטר, ואם כן \u0003נערבינהו וניתנינהו\u0004 \u0005[נערבם ונשנה אותם]\u0006 יחד, ונאמר כך: \u0003בכסף ובשטר בין על ידי אחרים בין על ידי עצמו!\u0004","\u0003אלא\u0004 בהכרח יש לומר שבכל אחד יש דין לעצמו: \u0003בכסף\u0004 — \u0003בין על ידי אחרים בין על ידי עצמו, בשטר\u0004 — \u0003על ידי אחרים ולא על ידי עצמו. ו\u0004קטע אחרון זה שיטת \u0003ר' שמעון בן אלעזר הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 העבד משתחרר \u0003אף בשטר על ידי אחרים ולא על ידי עצמו. ו\u0004אם כן נמצא שיש \u0003שלש מחלוקות\u0004 (דעות חלוקות) \u0003בדבר:\u0004 דעת ר' מאיר, דעת חכמים ודעת ר' שמעון בן אלעזר.","\u0003אמר רבה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון בן אלעזר\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 גזירה שווה \u0003\"לה\" \"לה\" מאשה,\u0004 שבשפחה נאמר \"חופשה לא ניתן לה\" (ויקרא יט, כ), ובאשה נאמר \"וכתב לה ספר כריתות\" (דברים כד, ג), ובגזירה שווה זו נלמד: \u0003מה אשה\u0004 אינה מגורשת \u0003עד שיוציא\u0004 הבעל \u0003גט לרשות שאינה שלו\u0004 וכל עוד הגט ברשותו אינו מועיל, \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 אינו משוחרר \u0003עד שיוציא\u0004 האדון \u0003גט לרשות שאינה שלו,\u0004 וכיון שהעבד הוא שלו, הרי שטר שנותן לו נשאר ברשות האדון, ולכן אינו יכול להשתחרר בשטר רק על ידי שאחרים יקבלו בשבילו את השטר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004"],["\u0003לר' שמעון בן אלעזר, עבד כנעני מהו שיעשה\u0004 (שימנה) \u0003שליח לקבל\u0004 את \u0003גיטו\u0004 (שטר שחרורו) \u0003מיד רבו?\u0004 האם \u0003כיון דגמר\u0004 \u0005[שלמד]\u0006 לגבי עצם השחרור בשטר של עבד בגזירה שווה \u0003\"לה\" \"לה\" מאשה,\u0004 הרי הוא \u0003כאשה\u0004 ורשאי למנות שליח,","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אשה דאיהי מצי\u0004 \u0005[שהיא יכולה]\u0006 להיות \u0003מקבלת גיטה\u0004 בעצמה — \u0003שליח נמי מצי משויא\u0004 \u0005[גם כן יכולה לעשות].\u0006 אבל \u0003עבד דאיהו לא מקבל גיטיה\u0004 \u0005[שהוא\u0006 עצמו \u0005אינו מקבל את שטרו]\u0006 לשיטת ר' שמעון בן אלעזר — \u0003שליח נמי לא מצי משוי\u0004 \u0005[גם כן אינו יכול לעשות].\u0006 \u0003בתר דבעיא הדר פשטא\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר\u0006 ו\u0005פתרה]:\u0006 כיון שלמד גזירה שווה \u0003\"לה\" \"לה\" מאשה\u0004 דינו לכל דבר \u0003כאשה\u0004 ויכול לעשות שליח.","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הני כהני\u0004 \u0005[הכהנים הללו]\u0006 \u0003שלוחי דרחמנא נינהו\u0004 \u0005[הקדוש ברוך הוא הם],\u0006 שעבודתם היא כשליחותו של הקדוש ברוך הוא. \u0003דאי סלקא דעתך שלוחי דידן נינהו\u0004 \u0005[שאם עולה על דעתך\u0006 לומר ש\u0005שלוחים שלנו הם],\u0006 \u0003מי איכא מידי דאנן לא מצינן עבדינן ואינהו מצי עבדי\u0004 \u0005[האם יש דבר שאנו\u0006 המשלחים \u0005איננו יכולים לעשות והם\u0006 השליחים \u0005יכולים לעשות]?\u0006 וכיון שאסור לישראל לעבוד במקדש ככהנים — משמע שאין הכהנים נחשבים שליחי ישראל!","ויש לשאול: \u0003ולא?!\u0004 והאם אין דבר ששליח יכול לעשות אף שאין המשלח יכול לעשותו?! \u0003והא עבדא דאיהו לא מצי מקבל גיטיה\u0004 \u0005[והרי\u0006 לפי מסקנת רבא יש כגון זה ב\u0005עבד, שהוא\u0006 עצמו \u0005אינו יכול לקבל\u0006 את \u0005גיטו]\u0006 \u0003ושליח\u0004 לקבל את גיטו \u0003מצי משוי\u0004 \u0005[יכול\u0006 הוא \u0005לעשות,\u0006 למנות\u0005]!\u0006","ודוחים: \u0003ולא היא,\u0004 אין זו קושיה שהרי \u0003ישראל לא שיכי\u0004 \u0005[אינם שייכים]\u0006 \u0003בתורת קרבנות כלל,\u0004 שאינם רשאים להקריב קרבנות בשום אופן, ואילו \u0003עבד שייך\u0004 בצד מסויים \u0003בגיטין\u0004 (בשטרות שחרור). \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נראין הדברים שהעבד מקבל\u0004 את \u0003גיטו\u0004 (שטר שחרורו) \u0003של חבירו מיד רבו של חבירו, אבל לא מיד רבו שלו\u0004 אם רוצה לשחרר על ידי כך עבד אחר שלו. כי אין כאן קנין, שהרי לא יצא השטר מרשות הבעלים, שרשות העבד היא כרשות רבו. וכיון שכל עבד ראוי לקבל שטר שחרור (לפחות עבור עבד אחר) אפשר לומר שיש לו שייכות לדיני שטרות, ורשאי למנות שליח לכך שיקבל בשבילו שטר שחרור.","שנינו במשנה כי לדעת ר' מאיר עבד כנעני נפדה בכסף על ידי אחרים ולדעת חכמים על ידי עצמו, \u0003ובלבד שיהא הכסף משל אחרים.\u0004 ומציעים: \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006עניין \u0005זה חלוקים\u0006 הם\u0005]:\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין קנין לעבד בלא רבו,\u0004 שאין לו קנין פרטי, והרב זוכה מיד בכל מה שקונה העבד, \u0003ו\u0004כן \u0003אין קנין לאשה בלא בעלה,\u0004 ומשום כך לעולם לא יכול העבד לקבל כסף שבו יפדה את עצמו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003יש קנין לעבד בלא רבו, ויש קנין לאשה בלא בעלה.\u0004","\u0003אמר רבה אמר רב ששת: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין קנין לעבד בלא רבו, ואין קנין לאשה בלא בעלה. והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים],\u0006 — במקרה מיוחד, וכגון \u0003דאקני ליה\u0004 \u0005[שהקנה לו]\u0006 אדם \u0003אחר מנה,\u0004 והוסיף \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003\"על מנת שאין לרבך רשות בו\".\u0004","\u0003ר' מאיר סבר: כי אמר ליה \"קני\"\u0004 \u0005[כאשר אומר לו\u0006 האחר \u0005\"קנה\"]\u0006 את הכסף — \u0003קני\u0004 \u0005[קונה]\u0006 ה\u0003עבד ו\u0004מיד על ידי כך \u0003קני רביה\u0004 \u0005[קונה רבו].\u0006 \u0003וכי אמר ליה\u0004 \u0005[ו\u0006גם \u0005כאשר אומר לו]\u0006 נותן הכסף את תנאי ההגבלה בנוסח \u0003\"על מנת\"\u0004 — \u0003לא כלום קאמר ליה\u0004 \u0005[אומר הוא לו],\u0006 שאין בתנאו זה ממש. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003כיון\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"על מנת\"\u0004 — \u0003אהני ליה תנאיה\u0004 \u0005[הועיל לו תנאו]\u0006 וקנה העבד בלבד, ואין לרבו קנין במנה זה ויש לעבד כסף שבו יוכל לפדות את עצמו.","\u0003ור' אלעזר אמר: כל כי האי גוונא\u0004 \u0005[כל כגון זה]\u0006 \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דקני\u0004 \u0005[שקונה]\u0006 ה\u0003עבד וקני רביה\u0004 \u0005[וקונה רבו]\u0006 מה שקנה העבד, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן,\u0006 במחלוקת ר' מאיר וחכמים, \u0005במה אנו עוסקים]\u0006 — \u0003כגון דאקני ליה\u0004 \u0005[שהקנה לו]\u0006 \u0003אחר מנה ואמר ליה\u0004 \u0005[לו]\u0006 \u0003\"על מנת שתצא בו לחירות\".\u0004","\u0003ר' מאיר סבר: כי אמר ליה \"קני\"\u0004 \u0005[כאשר אומר לו \"קנה\"]\u0006 — \u0003קני\u0004 \u0005[קונה]\u0006 ה\u0003עבד וקני רביה\u0004 \u0005[וקונה רבו]\u0006 מידו את המנה והוא שייך מיד לאדון. \u0003וכי אמר ליה\u0004 \u0005[וכאשר אומר לו]\u0006 \u0003\"על מנת\"\u0004 — \u0003לא כלום קאמר ליה\u0004 \u0005[אומר הוא לו],\u0006 שאין ממש בדבריו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לדידיה נמי הא\u0004 \u0005[לו,\u0006 לעבד עצמו, \u0005הרי]\u0006 \u0003לא קא מקני ליה\u0004 \u0005[מקנה הוא לו]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003אלא \"על מנת שתצא בו לחירות\",\u0004 ולכן אם מתקיים תנאי זה ויוצא העבד לחירות — יש כאן מתנה, ואם לא — אין כאן מתנה כלל.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 בין דברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר, ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מ\u0003דרבנן אדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003אין אשה פודה מעשר שני\u0004 של בעלה \u0003בלא\u0004 להוסיף \u0003חומש\u0004 כדין אדם הפודה מעשר שני של עצמו, \u0003ר' שמעון בן אלעזר אומר משום\u0004 (משמו של) \u0003ר' מאיר: אשה פודה מעשר שני בלא חומש.\u0004 ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא בזוזי\u0004 \u0005[אם תאמר\u0006 שפודה \u0005בכספים]\u0006 של ה\u0003בעל\u0004 שנותן לה שתפדה בהם, \u0003ומעשר\u0004 גם כן של ה\u0003בעל\u0004 — אם כן \u0003שליחותיה\u0004 \u0005[\u0006את \u0005שליחותו]\u0006 של ה\u0003בעל קא עבדה\u0004 \u0005[\u0006היא \u0005עושה]\u0006 וכשם שהוא צריך להוסיף חומש כשפודה מעשר שני של עצמו, כך צריכה היא להוסיף חומש ומהו טעמו של ר' מאיר?!","\u0003ואלא\u0004 תאמר שמדובר \u0003בזוזי דידה\u0004 \u0005[בכסף שלה]\u0006 \u0003ומעשר דידיה\u0004 \u0005[שלו]\u0006 — הרי היא נחשבת כאדם זר הפודה לו ופטורה מחומש, כדברי ר' מאיר, שהרי \"ואם גאל יגאל \u0003איש\u0004 ממעשרו\" \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 (ויקרא כז, לא) ומהדגשת הכתוב \"איש\" נלמד: \u0003ולא אשה\u0004 ממעשר בעלה!","\u0003אלא לאו כי האי גוונא\u0004 \u0005[האם לא\u0006 עוסקים אנו ב\u0005כגון זה]\u0006 \u0003דאקני\u0004 \u0005[שהקנה]\u0006 \u0003לה\u0004 אדם \u0003אחר מנה, ואמר לה: \"על מנת שתפדי בו את המעשר\u0004 של בעלך \u0003\", ו\u0004הרי \u0003איפכא שמענא להו\u0004 \u0005[ההיפך שמענו אותם]\u0006 אומרים בענין זה! שהרי ר' מאיר הוא האומר שמה שמקנים לאשה בכל דרך קונה בעלה מיד, אם כן \u0003לר'\u0004 מאיר הרי זה כאילו הבעל בעצמו פודה, וכיצד אמר ר' מאיר שאשה פודה מעשר שני בלא חומש! וחכמים הם החולקים עליו.","\u0003אמר אביי: איפוך\u0004 \u0005[הפוך]\u0006 את השיטות בענין פדיון המעשר. \u0003רבא אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך].\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003במעשר\u0004 שני \u0003דאתא מבי נשא עסקינן\u0004 \u0005[שבא\u0006 לה \u0005מבית אביה\u0006 בירושה \u0005אנו עוסקים],\u0006 \u0003ור' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: מעשר, ממון הקדש הוא, ולא קני ליה בעל\u0004 \u0005[והבעל אינו קונה אותו]\u0006 ואינו נעשה כרכושו, ולכן יכולה האשה לפדותו מכספי בעלה בלא להוסיף חומש, שהרי הוא לענין זה כאדם זר.","\u0003ורבנן לטעמייהו\u0004 \u0005[וחכמים לטעמם,\u0006 לשיטתם\u0005]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003ממון הדיוט הוא, ו\u0004לכן \u0003קני ליה בעל\u0004 \u0005[וקונה אותו הבעל]\u0006 כשאר נכסי מלוג, שהבעל אוכל מהם פירות, ונחשב כרכושו, \u0003הילכך שליחותא\u0004 \u0005[\u0006ו\u0005על כן\u0006 את ה\u0005שליחות]\u0006 של ה\u0003בעל קעבדא\u0004 \u0005[היא עושה]\u0006 ועליה להוסיף חומש.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003יוצא\u0004 העבד הכנעני \u0003בשן ועין ו\u0004בשאר \u0003ראשי אברים שאינן חוזרים\u0004 וגדלים לאחר שנקצצו. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שן ועין\u0004 — \u0003כתיבי\u0004 \u0005[כתובים]\u0006 במפורש (שמות כא, כו–כז), שאם השחיתם האדון יוצא העבד לחופשי. \u0003אלא\u0004 שאר \u0003ראשי אברים מנלן\u0004 \u0005[מניין לנו]\u0006 שאף אם קטע אותם האדון משתחרר העבד בכך? ומשיבים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שן ועין; מה\u0004 הוצאת \u0003שן ועין\u0004 שהם \u0003מומין שבגלוי, ואינן חוזרין\u0004 — \u0003אף כל מומין\u0004 שהוא עושה בו \u0003ש\u0004הם \u0003בגלוי ואינן חוזרין.\u0004","ושואלים: \u0003ואימא ניהוו\u0004 \u0005[ואמור\u0006 ש\u0005יהיו]\u0006 \u0003שן ועין כשני כתובים הבאים כאחד\u0004 ללמד אותו דין עצמו, \u0003ו\u0004כלל הוא בידינו כי \u0003כל שני כתובים הבאים כאחד\u0004 — \u0003אין מלמדין\u0004 ולא נאמרו אלא לעניינם בלבד. ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו גם שן וגם עין ואינם נלמדים זה מזה, ולכן אינם נחשבים כשני כתובים הבאים כאחד; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק \u0003שן, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו\u0004"],["\u0003שן דחלב,\u0004 שן של ילד שעתידה ליפול ותצמח אחרת במקומה, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 \u0003\"עין\",\u0004 לומר שהוא דווקא דבר שאינו חוזר כמו עין. \u0003ו\u0004להיפך, \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 רק \u0003\"עין\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מה עין\u0004 שהיא דבר \u0003שנברא עמו\u0004 מלידתו — \u0003אף כל\u0004 דבר \u0003שנברא עמו\u0004 בדווקא, \u0003אבל שן\u0004 כיון שצומחת רק לאחר זמן — \u0003לא\u0004 ייצא בה לחירות אם הפילה האדון, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנלמד בדרך זו: מה שנאמר \u0003\"\u0004ו\u0003כי יכה\"\u0004 (שמות כא, כו) הרי זה \u0003כלל, \"שן ועין\"\u0004 — \u0003פרט,\u0004 נמצא שיש לפנינו \u0003כלל ופרט\u0004 ולפי כללי מדרש ההלכה: \u0003אין בכלל אלא מה שבפרט,\u0004 ולכן \u0003שן ועין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","ומשיבים: \u0003\"לחפשי ישלחנו\"\u0004 (שם כז) \u0003חזר וכלל,\u0004 ואם כן יש לפנינו \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה אנו למדים שכללים אלה באים להוסיף, אבל \u0003אי אתה דן אלא כעין הפרט; מה הפרט\u0004 ש\u0003מפורש\u0004 הוא \u0003מום שבגלוי ו\u0004דברים ש\u0003אינן חוזרים\u0004 — \u0003אף כל\u0004 שהם \u0003מומין שבגלוי ואינן חוזרין.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם\u0006 כך\u0005]\u0006 נדייק יותר: \u0003מה הפרט מפורש\u0004 — \u0003מומין שבגלוי ובטל ממלאכתו,\u0004 כלומר, שהאיבר שניזק אינו יכול עוד לשמש בתפקידו, \u0003ואינו חוזר\u0004 — \u0003אף כל מומין שבגלוי, ואינו חוזר, ובטל ממלאכתו. אלמה תניא\u0004 \u0005[\u0006ו\u0005מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003תלש בזקנו ו\u0004על ידי כך \u0003דילדל בו עצם\u0004 מן הלסת, ששברה ויצאה ממקומה — \u0003עבד יוצא בהם לחירות,\u0004 והרי אין כאן ביטול מלאכה! ומשיבים: \u0003\"לחפשי ישלחנו\"\u0004 — \u0003ריבויא\u0004 \u0005[\u0006לשון \u0005ריבוי]\u0006 \u0003הוא\u0004 ובא לרבות גם את הדברים שאינן בדיוק כעין הפרט.","ושואלים: \u0003ואי ריבויא\u0004 \u0005[ואם ריבוי]\u0006 \u0003הוא\u0004 שבא לרבות גם דברים אחרים, אם כן \u0003אפילו הכהו על ידו וצמתה\u0004 (התייבשה, נשתתקה היד) \u0003וסופה לחזור\u0004 (להתרפא) \u0003נמי\u0004 \u0005[גם כן]\u0006 יצא בכך לחפשי, \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הכהו על ידו וצמתה וסופה לחזור\u0004 — \u0003אין עבד יוצא בה לחירות?\u0004 ומשיבים: \u0003אם כן\u0004 היית אומר שגם דבר שסופו לחזור בכלל — \u0003שן עין מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006 שנמצא שאין אנו למדים דבר משן ועין שנזכרו במפורש. ולכן אין לרבות אלא כעין הפרט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כשהכהו האדון והזיקו, \u0003בכולם,\u0004 בכל ראשי איברים, \u0003עבד יוצא בהם לחירות, וצריך\u0004 לקבל מאדוניו \u0003גט שחרור,\u0004 אלו \u0003דברי ר' שמעון. ר' מאיר אומר: אינו צריך\u0004 גט שחרור. \u0003ר' אליעזר אומר: צריך. ר' טרפון אומר: אינו צריך. ר' עקיבא אומר: צריך.\u0004","\u0003המכריעים לפני חכמים\u0004 שדנו בדברים הללו \u0003אומרים\u0004 בדרך פשרה (\"הכרעה\"): \u0003נראין דברי ר' טרפון בשן ועין, ש\u0004כן ביחס להם \u0003התורה זכתה לו\u0004 את שיחרורו במפורש, ולכן אינו צריך שטר, שהרי שחרורו מפורש בתורה, \u0003ו\u0004נראים \u0003דברי ר' עקיבא בשאר אברים, הואיל וקנס חכמים הוא.\u0004 ותוהים: \u0003קנס הוא?!\u0004 הלא \u0003קראי קא דרשינן\u0004 \u0005[כתובים אנו דורשים]\u0006 ומן התורה אנו למדים! \u0003אלא,\u0004 יש לתקן: \u0003הואיל ומדרש חכמים הוא\u0004 שאינו מפורש בתורה — לכן צריך לתת לו גם שטר שחרור.","ומעתה דנים, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 — \u0003יליף\u0004 \u0005[לומד]\u0006 הוא בגזירה שווה \u0003\"שילוח\" \"שילוח\" מאשה. מה אשה\u0004 אין יציאתה מבעלה אלא \u0003בשטר\u0004 — \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 אינו יוצא מתחת יד אדונו אלא \u0003בשטר\u0004 בלבד. \u0003ור' מאיר\u0004 אומר: \u0003אי כתב\u0004 \u0005[אילו\u0006 היה \u0005כותב]\u0006 בתורה \u0003\"חפשי\" לבסוף\u0004 (\"ישלחנו חפשי\") — הייתי מפרש \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 שצריך פעולת שילוח שטר קודם שיהיה חופשי. \u0003השתא דכתב\u0004 \u0005[עכשיו שכתוב]\u0006 \u0003\"לחפשי ישלחנו\"\u0004 משמעו — \u0003הוה ליה חפשי מעיקרא\u0004 \u0005[הריהו חפשי מתחילה]\u0006 ואינו צריך מעשה נוסף של שילוח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכהו על עינו וסמאה\u0004 (עיוור אותה), \u0003על אזנו וחרשה\u0004 — \u0003עבד יוצא בהן\u0004 במומים אלה \u0003לחירות.\u0004 ואם הכהו לא ממש על עינו אלא \u0003נגד\u0004 (בצד) \u0003עינו ו\u0004גרם לו ש\u0003אינו רואה,\u0004 או הכהו \u0003כנגד אזנו ו\u0004כתוצאה מכך \u0003אינו שומע\u0004 — \u0003אין עבד יוצא בהן לחירות. אמר רב שמן לרב אשי: למימרא דקלא\u0004 \u0005[\u0006האם \u0005תאמר שקול]\u0006 הגורם נזק \u0003לאו כלום הוא?\u0004","\u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רמי בר יחזקאל\u0004 ברייתא זו: \u0003תרנגול שהושיט ראשו לאויר\u0004 (לחלל של) \u0003כלי זכוכית, ותקע\u0004 (השמיע קול) \u0003בו, ו\u0004מחמת הקול \u0003שברו\u0004 — \u0003משלם\u0004 בעליו \u0003נזק שלם,\u0004 כשאר נזקים שהוא עושה כדרכו. \u0003ואמר רב יוסף, אמרי בי\u0004 \u0005[אומרים\u0006 החכמים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: סוס שצנף\u0004 (השמיע קול) \u0003וחמור שנער, ושברו\u0004 על ידי כך \u0003כלים בתוך הבית\u0004 — \u0003משלמים חצי נזק.\u0004 ואף שיש חילוק במקרים השונים אם משלם נזק שלם או חצי נזק — ברור שקול נחשב לדבר של ממש, שמתחייבים על נזקיו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אדם,\u0004 ש\u0003כיון\u0004 ש\u0003בר דעת הוא\u0004 — \u0003איהו מיבעית נפשיה\u0004 \u0005[הוא\u0006 ש\u0005מפחיד\u0006 את \u0005עצמו],\u0006 כלומר, לא הקול כאמצעי חומרי הוא שגרם לנזק, אלא הנזק נגרם לו מחמת הפחד ודבר זה תלוי בדעתו של האדם שנבהל, ואינו תוצאה מיידית וישירה של המעשה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המבעית\u0004 (מפחיד) \u0003את חבירו\u0004 ונגרם לו נזק — \u0003פטור מדיני אדם וחייב בדיני שמים. כיצד? תקע באזנו וחרשו\u0004 — \u0003פטור,\u0004 אבל אם \u0003אחזהו ותקע באזנו וחרשו\u0004 — \u0003חייב\u0004 אף בדיני אדם, שהרי עשה מעשה בגופו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכהו על עינו וכהתה\u0004 שלא נתעוורה לגמרי אלא נתמעט כוח הראיה שלה, או הכהו \u0003על שינו ונדדה\u0004 (שהיא עכשיו מתנועעת), \u0003אם יכול להשתמש בהן עכשיו\u0004 — \u0003אין עבד יוצא בהן לחירות, ואם לאו\u0004 שאינו יכול להשתמש בהן כלל — \u0003עבד יוצא בהן לחירות. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הרי שהיתה עינו\u0004 של העבד \u0003כהויה\u0004 מקודם \u0003ו\u0004האדון \u0003סמאה\u0004 לגמרי, היתה \u0003שינו נדודה והפילה, אם יכול\u0004 היה \u0003להשתמש בהן כבר\u0004 קודם לכן, לפני שהכהו — \u0003עבד יוצא בהן לחירות, ואם לאו\u0004 — \u0003אין עבד יוצא בהן לחירות.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו הדברים בשתי הברייתות, למרות שלכאורה דין אחד הוא — שעין כהויה אינה נחשבת לפגם; \u0003דאי אשמועינן הך קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק ברייתא \u0005זו הראשונה]\u0006 הייתי אומר \u0003משום דמעיקרא נהורא בריא והשתא נהורא כחישא\u0004 \u0005[שמתחילה\u0006 היה \u0005מאור\u0006 עיניו \u0005בריא\u0006 וחזק \u0005ועכשיו מאור\u0006 עיניו \u0005קלוש]\u0006 משום כך הוא זכאי לשחרור. \u0003אבל הכא דמעיקרא נמי נהורא כחישא\u0004 \u0005[כאן,\u0006 בברייתא השניה \u0005שמתחילה גם כן\u0006 היה \u0005מאור עיניו קלוק]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ישתחרר אם סימא אותה לגמרי, שהרי עין זו מתחילה לא שימשה היטב.","\u0003ו\u0004להיפך, \u0003אי אשמועינן הא\u0004 \u0005[אם היה השמיע לנו\u0006 רק ברייתא \u0005זו\u0006 האחרונה\u0005],\u0006 הייתי אומר \u0003משום דסמיא\u0004 \u0005[שעיוור\u0006 אותו\u0005]\u0006 \u0003לגמרי\u0004 — יוצא לחירות, \u0003אבל התם\u0004 \u0005[שם]\u0006 ש\u0003לא סמיא\u0004 \u0005[עיוור אותו]\u0006 \u0003לגמרי אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצא בו, אף שהכהה מקצת את מאור עיניו, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי שהיה רבו\u0004 (אדוניו) של העבד \u0003רופא, ואמר לו\u0004 העבד \u0003לכחול לו\u0004 את \u0003עינו\u0004 לריפוי \u0003וסמאה\u0004 בתוך כך, או שביקש ממנו \u0003לחתור\u0004 (לקדוח) \u0003לו\u0004 את \u0003שינו\u0004 הכואבת \u0003והפילה\u0004 האדון — נמצא ש\u0003שיחק\u0004 העבד \u0003באדון\u0004 שגרם לו שישחררנו, \u0003ויצא לחירות. רבן שמעון בן גמליאל אומר:\u0004 מה שנאמר \u0003\"ושחתה\"\u0004 (שמות כא, כו), כוונתו: \u0003עד שיתכוין\u0004 האדון \u0003לשחתה.\u0004 ובמקום שנתכוון לריפוי, גם אם לבסוף גרם נזק — אין העבד יוצא בכך לחפשי.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ושחתה\", מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 שהרי אינם למדים ממנו דבר. ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[צריכים\u0006 הם \u0005אותו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: הרי שהושיט ידו למעי\u0004 \u0003שפחתו\u0004 לסייע לה בלידתה \u0003וסימא עובר שבמעיה\u0004 — \u0003פטור\u0004 ואין העובר הזה משתחרר. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ושחתה\"\u0004 — \u0003עד שיכוין לשחתה,\u0004 וכאן לא נתכוון כלל לנגוע בעינו של העובר.","\u0003ואידך\u0004 \u0005[והאחר],\u0006 רבן שמעון בן גמליאל — \u0003מ\u0004מה שהיה יכול לומר \u0003\"ושחת\"\u0004 ונאמר \u0003\"שחתה\"\u0004 (כלומר, שחת אותה) \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר, שאין העבד משתחרר אלא אם כן עשה זאת האדון לשם השחתה, וגם שתהיה כוונתו למעשה זה. \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 — את ההבדל בין \u0003\"שחת\"\u0004 ל\u0003\"שחתה\" לא דריש\u0004 \u0005[אינו דורש],\u0006 שאינם סבורים שיש לכך משמעות להלכה.","\u0003אמר רב ששת: הרי שהיתה עינו\u0004 של העבד \u0003סמויה ו\u0004האדון \u0003חטטה\u0004 (עקר אותה) לגמרי — \u0003עבד יוצא בהן לחירות. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — משום שכעת העבד \u0003מחוסר אבר הוא,\u0004 ודבר זה חמור יותר ממצבו קודם לכן.","\u0003ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו\u0006 במשנה\u0005]:\u0006 יש דין \u0003תמות\u0004 שהקרבן יהיה תמים \u0003ו\u0004דין \u0003זכרות\u0004 שיהיה הקרבן זכר רק \u0003ב\u0004קרבנות \u0003בהמה, ואין תמות וזכרות בעופות,\u0004 שלא נאמר בתורה שיש להקפיד על כך.","\u0003יכול\u0004 שאם הביא ציפור ש\u0003יבשה גפה\u0004 (כנפה) או ש\u0003נקטעה רגלה,\u0004 או \u0003נחטטה עינה\u0004 שתהיה כשירה לקרבן? \u0003תלמוד לומר:\u0004 \"ואם \u0003מן העוף\u0004 עולה קרבנו...\" (ויקרא א, יד), \"מן העוף\" בא למעט — \u0003ולא כל העוף.\u0004 שחסרון גדול כאיבר אינו נחשב לכל העוף. ומכאן שהוצאת עין נחשבת לחסרון גדול יותר מאשר עיוורון בלבד. ולכן, אם הוציא את עינו העיוורת של העבד צריך לשחררו.","\u0003אמר רב חייא בר אשי אמר רב: היתה לו,\u0004 לעבד"],["\u0003יתרת\u0004 (אצבע יתירה), כגון שהיו לו שש אצבעות בידו \u0003וחתכה\u0004 האדון — \u0003עבד יוצא בהן לחירות. אמר רב הונא: והוא שנספרת\u0004 האצבע \u0003על גב היד,\u0004 כלומר, שהיתה אצבע זו מצויה באותה שורת אצבעות, אבל אם היא בצד אחר של כף היד אינה נחשבת כאצבע אלא כבליטה סתם ואין בהשחתתה משום הורדת איבר.","מסופר: \u0003סבי\u0004 \u0005[זקני]\u0006 העיר \u0003נזוניא לא אתו לפירקיה\u0004 \u0005[באו לדרשתו]\u0006 של \u0003רב חסדא, אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא \u0003לרב המנונא: זיל צנעינהו\u0004 \u0005[לך\u0006 ו\u0005נדה אותם]\u0006 משום שהם מזלזלים בכבוד הרב. \u0003אזל\u0004 \u0005[הלך]\u0006 ו\u0003אמר להו\u0004 \u0005[להם]\u0006 תחילה: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אתו רבנן לפירקא\u0004 \u0005[באו חכמים לדרשה]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי ניתי\u0004 \u0005[מדוע נבוא]?\u0006 \u0003דבעינן מיניה מילתא\u0004 \u0005[ששאלנו ממנו דבר]\u0006 \u0003ולא פשט לן\u0004 \u0005[פתר לנו],\u0006 ולפיכך אין לנו מה לשמוע ממנו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי בעיתו מינאי מידי\u0004 \u0005[האם שאלתם ממני דבר]\u0006 \u0003ולא פשיטנא לכו\u0004 \u0005[פתרתי לכם]?\u0006 שאלו אפוא את השאלה ממני.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 שאלה זו: \u0003עבד שסרסו רבו בבצים,\u0004 כלומר, שעקר את האשכים בלבד, \u0003מהו\u0004 דינו? האם \u0003כמום שבגלוי דמי\u0004 \u0005[נחשב]\u0006 הדבר ויוצא בו לחירות, \u0003או לא?\u0004 ומספרים: \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 של רב המנונא תשובה לשאלתם. \u0003אמרו לו: מה שמך? אמר להו\u0004 \u0005[להם]:\u0006 \u0003המנונא. אמרו ליה\u0004 \u0005[לו]\u0006 בלגלוג: \u0003לאו\u0004 \u0005[לא]\u0006 \u0003המנונא\u0004 צריך לקרוא לך, כלומר, דג חם וטוב (חם־נונא) \u0003אלא קרנונא,\u0004 דג קר שאינו טעים עוד (ר\"ח).","לאחר מעשה \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 וסיפר לו כל אותו ענין. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתא בעו מינך\u0004 \u0005[ברייתא שאלו ממך]\u0006 ואתה לא ידעת להשיב להם. כיצד? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עשרים וארבעה ראשי אברים שבאדם כולם אין מטמאין משום מחיה,\u0004 שנאמר בתורה שאם יש בנגע הצרעת מחית בשר (בשר חי) הרי הוא מטמא מיד בטומאת צרעת, ובראשי איברים אלה אין דין זה שייך, משום שצריך הכהן לראות את המחיה מכל צד בראיה אחת, ובאלה, בגלל צורתם — אינו יכול לראות את כל צדדיהם כאחת. ולכן לא חל דין מחיה עליהם.","\u0003ואלו הם\u0004 ראשי האיברים: \u0003ראשי אצבעות ידים ורגלים\u0004 — הרי עשרים, \u0003וראשי אזנים, וראש החוטם, וראש הגוייה\u0004 (איבר המין הזכרי) \u0003וראשי דדים\u0004 (פיטמות השדיים) \u0003שבאשה. ר' יהודה אומר: אף\u0004 הפיטמות \u0003שבאיש. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 \u0003בכולם עבד יוצא בהם לחירות.\u0004 כלומר, שכל אותם איברים שמנינו לענין נגעים הם גם אלה שהעבד יוצא בהם לחירות אם עקרם אדונו. \u0003רבי אומר: אף הסירוס\u0004 העבד יוצא בו לחירות. \u0003בן עזאי אומר: אף הלשון\u0004 נחשבת כאיבר שבגלוי, כי היא נחשפת בזמן שמדברים, ואם חתכה האדון — יוצא בה העבד לחירות.","ומעתה נברר \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003רבי אומר אף הסירוס.\u0004 ויש לשאול: \u0003סירוס דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003סירוס\u0004 של ה\u0003גיד,\u0004 שחתך האדון את איבר המין של העבד — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003גוייה\u0004 וכבר מנינו ראש הגוייה, ומה מוסיף רבי? \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 התכוון אלא ל\u0003סירוס\u0004 של ה\u0003ביצים,\u0004 ואם כן יש פה פתרון לשאלה ששאלו זקני נזוניא.","לעצם הדברים שנאמרו בברייתא ש\u0003רבי אומר אף הסירוס,\u0004 שואלים: \u0003ו\u0004לדעת \u0003רבי\u0004 האם \u0003לשון לא\u0004 נחשבת דבר שבגלוי? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003הרי מי שהיה מזה\u0004 מי חטאת לטהר אדם מטומאת המת \u0003ונתזה הזאה על פיו\u0004 של הטמא, \u0003רבי אומר: היזה,\u0004 כלומר, הרי זו הזאה ראויה ונטהר בכך. \u0003וחכמים אומרים: לא היזה,\u0004 כלומר, אין זו נחשבת הזאה כי הזאה צריכה להיעשות רק על איברים גלויים.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר במקרה שניתזה הזאה \u0003על לשונו,\u0004 ומכאן שרבי סבור שהלשון היא איבר שבגלוי? ודוחים: \u0003לא,\u0004 מדובר שהיזה על \u0003שפתיו.\u0004 ותוהים: \u0003על שפתיו פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שטהור הוא, שהרי הן גלויות! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003זימנא דחלים שפתיה\u0004 \u0005[פעמים ש\u0006הוא \u0005סוגר את שפתיו]\u0006 בחוזק וחלק מהן נכנס פנימה ואינו גלוי, ואפשר לומר שהוא דבר שבסתר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלדעת רבי נחשב חלק זה כגלוי.","וממשיכים ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש שכל שהיזה \u0003על לשונו\u0004 — טהור לשיטת רבי! \u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 לענין מומי כהנים וקרבנות\u0005:\u0006 \u0003ושניטל רוב הלשון\u0004 — הרי זה מום, \u0003רבי אומר: רוב המדבר שבלשונו,\u0004 כלומר, לא רוב אורכה של הלשון כולה עד לשרשה, אלא רוב אותו חלק בלשון המשתתף בחיתוך הדיבור, שהוא רק ראש הלשון. משמע שגם רבי סבור שעקירת הלשון מום הוא!","\u0003אלא\u0004 יש לפרש כך, \u0003רבי אומר: סירוס ולא מיבעיא\u0004 \u0005[ולא נצרכה\u0006 לומר\u0005]\u0006 \u0003לשון,\u0004 שיוצא לחירות שכן, היא נחשבת מגולה.\u0003 בן עזאי אמר\u0004: \u0003לשון, אבל\u0004 \u0003סירוס\u0004 — \u0003לא. ומאי\u0004 \u0005[ומה]\u0006 פירוש הלשון \u0003\"אף\"\u0004 שנאמר בברייתא, שבן עזאי אומר \"אף הלשון\", שלכאורה משמעה שבא להוסיף על דברי רבי — יש לפרשה \u0003אקמייתא\u0004 \u0005[על\u0006 הדברים \u0005הראשונים]\u0006 של תנא קמא, הוא מוסיף \"אף הלשון\". ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש — \u0003נקדמה\u0004 \u0005[שיקדים]\u0006 את דברי \u0003בן עזאי ברישא\u0004 \u0005[בתחילה],\u0006 שבן עזאי מוסיף לשון, על דברי תנא קמא, ורבי אומר \"אף הסירוס\" שהוא מוסיף גם על בן עזאי!","ומשיבים: באמת כך היה צריך להיות, אלא ה\u0003תנא שמעה ל\u0004שיטתו של \u0003רבי וקבעה\u0004 בגירסתו בברייתא, \u0003ו\u0004אחר כך \u0003שמעה ל\u0004שיטתו של \u0003בן עזאי ותני\u0004 \u0005[ושנה]\u0006 גם אותה לאחר מכן, ולפי הענין ראוי היה באמת שישנה את סדר הדברים, \u0003ו\u0004לא שינה כי \u0003משנה לא זזה ממקומה,\u0004 שמשאירים את נוסח המשנה כפי שהיה, כדי שלא לבלבל את הלומדים.","\u0003אמר עולא: הכל מודים בלשון לענין טומאה,\u0004 ש\u0003גלוי הוא\u0004 נחשב \u0003אצל\u0004 טומאת \u0003השרץ\u0004 ושאר טומאות. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"אשר יגע בו\"\u0004 (ויקרא ט ו, יא) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003והאי נמי\u0004 \u0005[וזה,\u0006 הלשון, \u0005גם כן]\u0006 \u0003בר נגיעה הוא,\u0004 כלומר, דבר שיכול לנגוע הוא, ואם נגע דבר טמא, כעין שרץ מת בלשון — הרי הוא מטמא.","וכן הכל מודים שהלשון \u0003לענין טבילה\u0004 — \u0003כטמון דמי\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 שאין צריך לפתוח את פיו כדי שיהיו מי הטבילה על לשונו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — שנאמר: \u0003\"ורחץ בשרו במים\"\u0004 (שם יג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003מה בשרו מאבראי\u0004 \u0005[מבחוץ],\u0006 \u0003אף כל\u0004 שטובל הוא מה שנמצא \u0003מאבראי\u0004 \u0005[מבחוץ]\u0006 ולא דבר שהוא בדרך כלל בפנים.","\u0003לא נחלקו אלא לענין הזאה,\u0004 אם דינה של הלשון כגלוי או כטמון. \u0003רבי מדמי לה\u0004 \u0005[מדמה אותה,\u0006 את ההזאה\u0005]\u0006 \u0003לטומאה,\u0004 שהלשון נחשבת כגלויה. \u0003ורבנן מדמו לה\u0004 \u0005[וחכמים מדמים אותה]\u0006 \u0003לטבילה\u0004 שנחשבת הלשון כטמונה.","ומעירים: \u0003ותרוייהו בהאי קרא קמיפלגי\u0004 \u0005[ושניהם\u0006 בפירושו של \u0005כתוב זה נחלקו],\u0006 שנאמר: \u0003\"והזה הטהר על הטמא\u0004 ביום השלישי וביום השביעי וחטאו ביום השביעי וכבס בגדיו ורחץ במים וטהר בערב\u0003\"\u0004 (במדבר יט, יט) \u0003רבי סבר:\u0004 שכך הוא צירוף הדברים \u0003\"והזה הטהר על הטמא ביום השלישי וביום השביעי וחטאו\"\u0004 שההזאה (\"וחיטאו\") דינה כטומאה, שכל חלק בגוף שיכול להיטמא, אם נפלה עליו הזאה — נטהר.","ואילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 \u0003\"וחטאו ביום השביעי וכבס בגדיו ורחץ במים\"\u0004 שהזאה דינה כטבילה (\"ורחץ במים\"), ורק חלק מן הגוף הצריך טבילה צריך הזאה.","ושואלים: \u0003ורבנן נמי נדמייה\u0004 \u0005[וחכמים גם כן,\u0006 מדוע לא \u0005ידמוה]\u0006 \u0003ל\u0004ענין \u0003טומאה?\u0004 ומשיבים: \u0003טהרה מטהרה הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 כשם שטבילה היא דרך טהרה — אף הזאה דרך טהרה וצריך להשוות את דיניהן. ושואלים מצד אחר: \u0003ורבי\u0004 מדוע לא \u0003נדמייה\u0004 \u0005[ידמה אותה]\u0006 \u0003לטבילה?\u0004 ומשיבים: מה שנאמר \u0003\"וכבס בגדיו\"\u0004 — \u0003הפסיק הענין,\u0004 לומר שדין הזאה ודין טבילה אינם נחשבים כדבר אחד, אלא דיני הזאה כדיני טומאה האמורים קודם.","לעצם הדברים שואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003רבי לענין טבילה\u0004 שלשון \u0003כטמון דמי\u0004 \u0005[\u0006היא \u0005נחשבת]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבין אמר רב אדא אמר ר' יצחק: מעשה בשפחה של בית רבי שטבלה\u0004 לטהרתה, \u0003ועלתה\u0004 מן הטבילה \u0003ונמצא עצם בין שיניה, והצריכה רבי טבילה אחרת.\u0004 משמע שהוא מצריך שלא תהיה חציצה אפילו בתוך הפה, ואם כן גם הלשון צריכה טבילה!","ומשיבים: מכאן אין ראיה, כי \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003ביאת מים\u0004 בתוך הפה \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 בפועל, אבל \u0003מקום הראוי לבוא בו מים בעינן\u0004 \u0005[צריכים אנו],\u0006 ואם יש חציצה הרי אין המקום ראוי לביאת מים.","וטעמו של דבר \u0003כ\u0004מו שאמר \u0003ר' זירא.\u0004 ש\u0003אמר ר' זירא\u0004 בדין מנחות: \u0003כל הראוי לבילה\u0004 (בלילה), כלומר, כל מנחה שלפי גודלה ראויה ויכולה להיבלל בשמן — \u0003אין\u0004 מעשה ה\u0003בילה\u0004 בפועל \u0003מעכבת בו,\u0004 וגם אם לא בלל, כשר. \u0003ו\u0004כל \u0003שאינו ראוי לבילה\u0004 מפני גודלו — העדר \u0003בילה מעכבת בו.\u0004 ואף כאן, אף שאין צורך בביאת מים ממש, מכל מקום צריך המקום להיות ראוי לטבילה ובלי חציצה."],["ושבים ומעירים, שבעיה ראשונה לגבי סירוס בביצים, היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו כבר בבעיה זו. נאמר בפסול קרבנות שיש בהם מום: \u0003\"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה'\u0003\"\u0004 (ויקרא כב, כד) — \u0003כולן\u0004 כל המומים הללו הם \u0003בביצים\u0004 (באשכים) של הבהמה, אלו \u0003דברי ר' יהודה.\u0004","ותוהים: האם כוונתו שמומים אלה הם דווקא \u0003בביצים ולא בגיד?\u0004 הרי ודאי שבגיד עצמו, שהוא גלוי ונראה, ייחשבו אלה למומים! \u0003אלא\u0004 כך יש לשנות את מחלוקתם: \u0003כולן אף בביצים,\u0004 אלו \u0003דברי ר' יהודה. ר' אליעזר בן יעקב אומר: כולם בגיד\u0004 בלבד. \u0003ר' יוסי אומר\u0004 יש לחלק: \u0003\"מעוך וכתות\"\u0004 — \u0003אף בביצים,\u0004 ואילו \u0003\"נתוק וכרות\" בגיד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מום הוא, \u0003בביצים\u0004 — \u0003לא.\u0004","\u0003בהמה גסה נקנית\u0004 לקונה אותה \u0003במסירה,\u0004 כשבעליה הקודם מוסר אותה לקונה במושכות או במתג, \u0003ו\u0004הבהמה \u0003הדקה\u0004 נקנית \u0003בהגבהה,\u0004 אלו \u0003דברי ר' מאיר ור' אליעזר. וחכמים אומרים: בהמה דקה נקנית\u0004 אף \u0003במשיכה,\u0004 ואין צורך להגביה אותה.","\u0003דרש רב ב\u0004עיר \u0003קימחוניא: בהמה גסה נקנית במשיכה. אשכחינהו\u0004 \u0005[מצא אותם]\u0006 \u0003שמואל לתלמידי\u0004 \u0005[לתלמידיו]\u0006 של \u0003רב,\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב\u0004 כי \u0003בהמה גסה נקנית במשיכה? והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003במסירה תנן\u0004 \u0005[שנינו]!\u0006 \u0003ורב נמי\u0004 \u0005[גם כן]\u0006 שמעתי כמה פעמים ש\u0003במסירה אמר,\u0004 האם \u0003הדר ביה מההיא\u0004 \u0005[חזר בו מאותה\u0006 הלכה\u0005]?\u0006 והשיבו לו: אכן רב חזר בו ו\u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003וחכמים אומרים: זו וזו\u0004 בין בהמה דקה בין גסה \u0003נקנית במשיכה. ר' שמעון אומר: זו וזו\u0004 נקנית \u0003בהגבהה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: אלא מעתה, פיל לר' שמעון במה יקנה?\u0004 שהרי אינו יכול להגביה אותו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אפשר שיקנה אותו \u0003ב\u0004קנין \u0003חליפין\u0004 ולא בקנין משיכה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בשוכר את מקומו\u0004 של הפיל לפי שעה וקונה את הפיל אגב הקרקע.","\u0003ר' זירא אמר\u0004 יש דרך אחרת: \u0003מביא ארבעה כלים ומניחן תחת רגליו,\u0004 ועל ידי כך הוא קונה אותו, ככל דבר הנמצא בתוך כליו של הקונה. ושואלים: האם \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 מדברי ר' זירא ש\u0003כליו של לוקח\u0004 אפילו כשהיו \u0003ברשות מוכר קנה לוקח?\u0004 ודוחים: מכאן אין ראיה, כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 כשהיה הדבר לא ברשות המוכר אלא \u0003בסימטא\u0004 שאינה נחשבת רשות הרבים ולא רשות היחיד, ובמקום כזה ודאי כליו של לוקח קונים לו."]]};
